// StayTW Study — TOCFL Level 5 文法
// 正本: 國家教育研究院「臺灣華語文能力基準(TBCL)」語法點表 496 点。
//   第5級 の点をそのまま並べ、最後に官方の表に無い点(書面語・進階)を足している。
//   語法點名(t)と1つ目の例文は官方のまま。説明と訳と2つ目の例文はこちらで書いた。
//   作り直し: node scripts/gen-grammar.mjs → node scripts/build-grammar.mjs
// 形式: id, cat, t=語法點名, g=一言の意味, p=文型, ex=解説, eg=例文[{z,py,j,e,k}]
const GRAMMAR_L5 = [
{"id":"g5-391","cat":"介詞","t":"以1","g":{"j":"〜で(手段)","e":"by means of / using","k":"~로/~을 이용해"},"p":{"j":"A ＋ 以 ＋ 手段 ＋ V","e":"A + yǐ + means + V","k":"A ＋ 以 ＋ 수단 ＋ V"},"ex":{"j":"「以」は書き言葉で「用」と同じ意味。手段・道具を導く。口語では「用」を使うことが多く、「以」は公文書やニュースに多い。","e":"\"以\" is a formal written equivalent of \"用\", introducing a means or method. In speech, \"用\" is far more common; \"以\" appears mainly in official or written contexts.","k":"\"以\"는 문어체에서 \"用\"과 같은 의미로 수단·방법을 나타낸다. 구어에서는 주로 \"用\"을 쓰며, \"以\"는 공문서나 뉴스에 자주 쓰인다."},"eg":[{"z":"今天所討論的，如果有任何建議，歡迎<em>以電子郵件</em>提出。","py":"Jīntiān suǒ tǎolùn de, rúguǒ yǒu rènhé jiànyì, huānyíng yǐ diànzǐ yóujiàn tíchū.","j":"今日話し合われた件について、何かご意見があれば、メールでご提出ください。","e":"Regarding what was discussed today, if you have any suggestions, please feel free to submit them by email.","k":"오늘 논의된 내용에 대해 어떤 의견이라도 있으시면 이메일로 제출해 주시기 바랍니다."},{"z":"有問題的話，請<em>以電話</em>跟客服聯絡。","py":"Yǒu wèntí dehuà, qǐng yǐ diànhuà gēn kèfú liánluò.","j":"問題があれば、電話でカスタマーサービスにご連絡ください。","e":"If you have any issues, please contact customer service by phone.","k":"문제가 있으면 전화로 고객센터에 연락해 주세요."}]},
{"id":"g5-392","cat":"接続","t":"以2","g":{"j":"〜するために(目的)","e":"in order to","k":"~하기 위해"},"p":{"j":"VP1，以 ＋ VP2(目的)","e":"VP1, yǐ + VP2 (purpose)","k":"VP1，以 ＋ VP2(목적)"},"ex":{"j":"「以」は書き言葉で目的を表し、「以便」に近い。前の動作の目的・結果を後ろに続ける。手段を表す「以1」と混同しないよう注意。","e":"Here \"以\" introduces a purpose clause, close in meaning to \"以便\" (\"in order to\"). Don't confuse it with \"以1\", which marks means/instrument instead of purpose.","k":"여기서 \"以\"는 목적을 나타내며 \"以便\"과 비슷하다. 앞 동작의 목적·결과를 뒤에 이어준다. 수단을 나타내는 \"以1\"과 혼동하지 않도록 주의한다."},"eg":[{"z":"學生要加強自己的能力，<em>以增加自己進入理想行業的機會</em>。","py":"Xuéshēng yào jiāqiáng zìjǐ de nénglì, yǐ zēngjiā zìjǐ jìnrù lǐxiǎng hángyè de jīhuì.","j":"学生は理想の業界に入るチャンスを増やすために、自分の能力を高めるべきだ。","e":"Students should strengthen their own abilities in order to increase their chances of entering their ideal industry.","k":"학생은 자신의 능력을 강화하여 원하는 업계에 들어갈 기회를 늘려야 한다."},{"z":"他每天努力練習中文，<em>以提升自己的口說能力</em>。","py":"Tā měitiān nǔlì liànxí Zhōngwén, yǐ tíshēng zìjǐ de kǒushuō nénglì.","j":"彼は毎日一生懸命中国語を練習して、自分のスピーキング力を伸ばそうとしている。","e":"He practices Chinese hard every day in order to improve his own speaking ability.","k":"그는 매일 열심히 중국어를 연습하여 자신의 말하기 실력을 향상시키려 한다."}]},
{"id":"g5-393","cat":"介詞","t":"於1","g":{"j":"〜に(時間・書き言葉)","e":"at [time] (formal)","k":"~에(문어체, 시간)"},"p":{"j":"S ＋ (已/將) ＋ 於 ＋ 時間 ＋ VP","e":"S + (already/will) + yú + time + VP","k":"S ＋ (已/將) ＋ 於 ＋ 시간 ＋ VP"},"ex":{"j":"「於」は書き言葉で時間を表す「在」にあたる。「已於」「將於」の形でよく使われ、正式な文書・ニュースに多い。日常会話では「在」を使う。","e":"\"於\" functions like \"在\" for time in formal writing, often appearing as \"已於\" or \"將於\" in news and official documents. In everyday speech, \"在\" is used instead.","k":"\"於\"는 문어체에서 시간을 나타내는 \"在\"에 해당하며 \"已於\", \"將於\" 형태로 뉴스·공문서에 자주 쓰인다. 일상 회화에서는 \"在\"를 쓴다."},"eg":[{"z":"總經理已<em>於下午兩點</em>前往越南拜訪客戶。","py":"Zǒngjīnglǐ yǐ yú xiàwǔ liǎng diǎn qiánwǎng Yuènán bàifǎng kèhù.","j":"総経理はすでに午後2時にベトナムへ客先を訪問しに出発した。","e":"The general manager already departed for Vietnam at 2 p.m. to visit clients.","k":"총경리는 이미 오후 2시에 베트남으로 고객을 방문하러 떠났다."},{"z":"會議將<em>於明天早上九點</em>開始。","py":"Huìyì jiāng yú míngtiān zǎoshang jiǔ diǎn kāishǐ.","j":"会議は明日の午前9時に始まる予定だ。","e":"The meeting will start at 9 a.m. tomorrow.","k":"회의는 내일 오전 9시에 시작될 예정이다."}]},
{"id":"g5-394","cat":"介詞","t":"於2","g":{"j":"〜で(場所・書き言葉)","e":"at [place] (formal)","k":"~에서(문어체, 장소)"},"p":{"j":"S ＋ 將 ＋ 於 ＋ 場所 ＋ VP","e":"S + will + yú + place + VP","k":"S ＋ 將 ＋ 於 ＋ 장소 ＋ VP"},"ex":{"j":"「於」は場所を表す「在」の書き言葉版で、イベントの開催場所を告知する正式な文でよく使う。時間を表す「於1」との違いは、後ろに続くのが時間か場所かで区別する。","e":"Here \"於\" is the formal written equivalent of \"在\" for location, commonly used to announce where an event will take place. Compare with \"於1\", which marks time rather than place.","k":"여기서 \"於\"는 장소를 나타내는 \"在\"의 문어체 표현으로, 행사 개최 장소를 알리는 공식적인 문장에 자주 쓰인다. 시간을 나타내는 \"於1\"과는 뒤에 오는 것이 시간인지 장소인지로 구분한다."},"eg":[{"z":"本活動將<em>於國際會議中心</em>舉行。","py":"Běn huódòng jiāng yú Guójì Huìyì Zhōngxīn jǔxíng.","j":"本イベントは国際会議センターで開催される予定だ。","e":"This event will be held at the International Convention Center.","k":"본 행사는 국제회의센터에서 개최될 예정이다."},{"z":"畢業典禮將<em>於大禮堂</em>舉辦。","py":"Bìyè diǎnlǐ jiāng yú dàlǐtáng jǔbàn.","j":"卒業式は講堂で行われる予定だ。","e":"The graduation ceremony will be held in the auditorium.","k":"졸업식은 대강당에서 열릴 예정이다."}]},
{"id":"g5-395","cat":"介詞","t":"由2","g":{"j":"〜によって(動作の主体)","e":"by (agent of the action)","k":"~가/~에 의해"},"p":{"j":"A ＋ 由 ＋ B ＋ V","e":"A + yóu + B + V","k":"A ＋ 由 ＋ B ＋ V"},"ex":{"j":"「由」は動作の実行者・担当者を導く。「A由B＋動詞」で「AはBが行う」という意味になる。起点(〜から)を表す「由1」とは意味が異なるので注意。","e":"\"由\" introduces who performs or is responsible for an action (\"A由B+V\" = \"B does A\"). Don't confuse this with \"由1\", which marks a starting point (\"from\") rather than an agent.","k":"\"由\"는 동작을 수행하는 주체를 나타낸다(\"A由B+동사\" = \"B가 A를 한다\"). 출발점을 나타내는 \"由1\"(\"~부터\")과는 의미가 다르므로 주의한다."},"eg":[{"z":"抽獎活動將<em>由電腦</em>選出得獎者。","py":"Chōujiǎng huódòng jiāng yóu diànnǎo xuǎnchū déjiǎngzhě.","j":"抽選イベントはコンピューターによって当選者が選ばれる予定だ。","e":"The prize drawing will have its winners selected by computer.","k":"추첨 행사는 컴퓨터가 당첨자를 선정할 예정이다."},{"z":"這次的表演<em>由學生</em>自己策劃。","py":"Zhè cì de biǎoyǎn yóu xuéshēng zìjǐ cèhuà.","j":"今回の公演は学生自身が企画したものだ。","e":"This performance was planned by the students themselves.","k":"이번 공연은 학생들이 직접 기획한 것이다."}]},
{"id":"g5-396","cat":"副詞","t":"又3","g":{"j":"強調理由(反問で「そもそも〜ない」)","e":"emphasizing a reason in a rhetorical question","k":"이유를 강조(반문에서 '애초에 ~하지도 않다')"},"p":{"j":"A ＋ 又 ＋ 沒/不 ＋ VP，…?(反問)","e":"A + yòu + méi/bù + VP, ...? (rhetorical)","k":"A + 又 + 沒/不 + VP, ...? (반문)"},"ex":{"j":"「又」は反語文で理由を強めて否定を作り、「そもそも〜ない」という開き直りのニュアンスを出す。単純な「又」の反復用法と混同しないこと。","e":"Here 又 reinforces a negated reason in a rhetorical question, meaning 'you didn't even...', not the usual 'again' sense of 又. Don't confuse with 又...又... (both...and).","k":"이 又는 반문문에서 부정된 이유를 강조하며 '애초에 ~하지도 않았는데'라는 뉘앙스를 낸다. '다시/또'라는 기본 의미의 又와 혼동하지 말 것."},"eg":[{"z":"你<em>又</em>沒做錯事，有什麼好怕的？","py":"Nǐ yòu méi zuòcuò shì, yǒu shénme hǎopà de?","j":"君はそもそも何も悪いことをしていないのに、何を怖がることがあるの?","e":"You didn't even do anything wrong—what is there to be afraid of?","k":"너는 애초에 잘못한 일도 없는데, 뭐가 무서울 게 있어?"},{"z":"他<em>又</em>不是不知道，何必裝傻？","py":"Tā yòu búshì bù zhīdào, hébì zhuāngshǎ?","j":"彼はそもそも知らないわけではないのに、なぜとぼけるのか。","e":"He's not even unaware of it—why pretend not to know?","k":"그는 애초에 모르는 것도 아닌데 왜 모르는 척하는 거야?"}]},
{"id":"g5-397","cat":"副詞","t":"就3","g":{"j":"特定の例を強調する「まさに」","e":"highlighting a specific example (in particular)","k":"특정 예를 강조(바로 그)"},"p":{"j":"不是每個N都VP，A就VP。","e":"Búshì měi ge N dōu VP, A jiù VP.","k":"Búshì měi ge N dōu VP, A jiù VP."},"ex":{"j":"全体についての否定的な一般化のあとで「就」を使い、特定の例外を際立たせ「まさにAは〜だ」と強調する。「就是」の断定用法や「すぐに」の意味の就とは区別すること。","e":"就 here singles out a specific instance that contrasts with a preceding general negative statement ('not every X...'), meaning 'X in particular does...'. Distinct from 就 meaning 'then/right away'.","k":"앞의 부정적 일반화(모든 ~가 ~한 것은 아니다) 뒤에서 就를 써서 특정한 예를 부각시켜 '바로 그는 ~하다'는 뜻을 낸다. '바로/즉시'의 就와 구별할 것."},"eg":[{"z":"不是每個外國人都不吃臭豆腐，我的日本朋友<em>就</em>很喜歡吃。","py":"Búshì měi ge wàiguórén dōu bù chī chòudòufu, wǒ de Rìběn péngyǒu jiù hěn xǐhuān chī.","j":"外国人がみんな臭豆腐を食べないわけではなく、私の日本人の友達はまさによく食べる。","e":"Not every foreigner refuses to eat stinky tofu—my Japanese friend, for one, loves eating it.","k":"모든 외국인이 취두부를 못 먹는 것은 아니다. 내 일본인 친구는 오히려 아주 좋아한다."},{"z":"不是每個小孩都怕打針，我弟弟<em>就</em>一點都不怕。","py":"Búshì měi ge xiǎohái dōu pà dǎzhēn, wǒ dìdi jiù yìdiǎn dōu bú pà.","j":"子どもがみんな注射を怖がるわけではなく、私の弟はまったく怖がらない。","e":"Not every kid is afraid of shots—my little brother, in particular, isn't scared at all.","k":"모든 아이가 주사를 무서워하는 것은 아니다. 내 남동생은 전혀 무서워하지 않는다."}]},
{"id":"g5-398","cat":"介詞","t":"透過","g":{"j":"〜を通じて(手段・媒介)","e":"through / by means of","k":"~을 통해(수단・매개)"},"p":{"j":"透過 ＋ N(手段/媒介)，…","e":"Tòuguò + N, ...","k":"Tòuguò + N, ..."},"ex":{"j":"「透過」は書き言葉的な介詞で、方法や媒介を通じて結果に至ることを示す。「經過」(場所や過程を経る)や「通過」(通過する/合格する)と混同しないよう注意。","e":"透過 introduces the means or medium through which something is achieved; it's more formal/written. Don't confuse with 經過 (to pass through a place/process) or 通過 (to pass/get approval).","k":"透過는 수단이나 매개를 통해 결과에 이르는 것을 나타내는 다소 문어적인 개사이다. 장소나 과정을 거치는 經過, 통과/승인을 뜻하는 通過와 혼동하지 말 것."},"eg":[{"z":"<em>透過</em>這本書，我們知道他不斷學習與成長的過程。","py":"Tòuguò zhè běn shū, wǒmen zhīdào tā bùduàn xuéxí yǔ chéngzhǎng de guòchéng.","j":"この本を通じて、私たちは彼が絶えず学び成長していく過程を知ることができる。","e":"Through this book, we learn about his process of continuous learning and growth.","k":"이 책을 통해 우리는 그가 끊임없이 배우고 성장해 온 과정을 알 수 있다."},{"z":"<em>透過</em>網路，我們可以跟世界各地的人聊天。","py":"Tòuguò wǎnglù, wǒmen kěyǐ gēn shìjiè gèdì de rén liáotiān.","j":"インターネットを通じて、私たちは世界各地の人とチャットできる。","e":"Through the internet, we can chat with people all over the world.","k":"인터넷을 통해 우리는 전 세계 사람들과 대화할 수 있다."}]},
{"id":"g5-399","cat":"介詞","t":"順（著）","g":{"j":"〜に沿って/〜のままに(方向・流れ)","e":"along / following (a direction, flow)","k":"~을 따라(방향・흐름)"},"p":{"j":"順（著）＋ N(方向/流れ) ＋ VP","e":"Shùn(zhe) + N + VP","k":"Shùn(zhe) + N + VP"},"ex":{"j":"「順著」はある方向や流れ(音・道など)に沿って動作を行うことを示す。地理的な線に沿うだけの「沿著」より、流れ・傾向に合わせる意味合いが強い。","e":"順(著) means to move along or follow a direction/flow (sound, trend, road). It overlaps with 沿著 but emphasizes following a flow or cue, not just a physical line.","k":"順(著)는 어떤 방향이나 흐름(소리, 길 등)을 따라 동작하는 것을 나타낸다. 단순히 물리적 선을 따르는 沿著보다 흐름이나 단서를 따른다는 뉘앙스가 강하다."},"eg":[{"z":"<em>順著</em>音樂聲走過去，就會看到一群人在運動。","py":"Shùnzhe yīnyuè shēng zǒu guòqù, jiù huì kàndào yì qún rén zài yùndòng.","j":"音楽の音に沿って歩いて行くと、大勢の人が運動しているのが見える。","e":"Follow the sound of the music, and you'll see a group of people exercising.","k":"음악 소리를 따라 걸어가면 한 무리의 사람들이 운동하는 것을 볼 수 있다."},{"z":"<em>順著</em>這條路一直走，就會到火車站。","py":"Shùnzhe zhè tiáo lù yìzhí zǒu, jiù huì dào huǒchē zhàn.","j":"この道に沿ってまっすぐ歩いて行けば、駅に着く。","e":"Follow this road straight ahead, and you'll reach the train station.","k":"이 길을 따라 곧장 걸어가면 기차역에 도착한다."}]},
{"id":"g5-400","cat":"介詞","t":"沿（著）","g":{"j":"〜沿いに(場所・線)","e":"along (a physical place or line)","k":"~을 따라(장소・선)"},"p":{"j":"沿（著）＋ N(場所/道) ＋ VP","e":"Yán(zhe) + N + VP","k":"Yán(zhe) + N + VP"},"ex":{"j":"「沿著」は川や道など物理的な線状の場所に沿って移動することを表す、地理的用法が中心。抽象的な流れに従う「順著」との違いに注意。","e":"沿(著) describes moving along a physical, linear place (a river, road, coast) — a geographic sense. Contrast with 順(著), which more often follows an abstract flow or cue.","k":"沿(著)는 강, 길, 해안 등 물리적으로 길게 이어진 장소를 따라 이동하는 것을 나타내는 지리적 용법이 중심이다. 추상적 흐름을 따르는 順(著)와의 차이에 유의."},"eg":[{"z":"黃昏的時候，我經常<em>沿著</em>河邊散步。","py":"Huánghūn de shíhòu, wǒ jīngcháng yánzhe hébiān sànbù.","j":"夕方になると、私はよく川沿いを散歩する。","e":"In the evening, I often take a walk along the river.","k":"해질 무렵이면 나는 자주 강가를 따라 산책한다."},{"z":"我們<em>沿著</em>海邊騎腳踏車，風景很漂亮。","py":"Wǒmen yánzhe hǎibiān qí jiǎotàchē, fēngjǐng hěn piàoliang.","j":"私たちは海沿いに自転車に乗った。景色がとても綺麗だった。","e":"We rode our bikes along the coast—the scenery was beautiful.","k":"우리는 해변을 따라 자전거를 탔는데 풍경이 매우 아름다웠다."}]},
{"id":"g5-401","cat":"特殊構文","t":"以......為......","g":{"j":"〜を〜とする/〜を〜として","e":"take A as B","k":"A를 B로 삼다"},"p":{"j":"A ＋ 以 ＋ X ＋ 為 ＋ Y","e":"A + 以 + X + 為 + Y","k":"A + 以 + X + 為 + Y"},"ex":{"j":"「以A為B」は「Aを以てBと為す」の意味で、書き言葉でよく使われる。Aを目標・基準・手段として示す。「為」はここではwéi(〜とする)と読み、wèi(〜のために)と間違えやすいので注意。","e":"\"Yǐ A wéi B\" means \"take A as B,\" common in formal/written Chinese to state a goal, standard, or means. Note 為 here is read wéi (to serve as), not wèi (for the sake of) — a common tone mistake.","k":"\"以A為B\"는 \"A를 B로 삼다\"라는 뜻으로 문어체에서 목표·기준·수단을 나타낼 때 쓴다. 여기서 為는 wéi(~로 삼다)로 읽으며 wèi(~을 위해)와 혼동하지 않도록 주의."},"eg":[{"z":"他<em>以取得律師資格為目標</em>。","py":"Tā yǐ qǔdé lǜshī zīgé wéi mùbiāo.","j":"彼は弁護士資格の取得を目標としている。","e":"His goal is to obtain a lawyer's qualification.","k":"그는 변호사 자격 취득을 목표로 삼고 있다."},{"z":"她<em>以成為一名醫生為目標</em>。","py":"Tā yǐ chéngwéi yì míng yīshēng wéi mùbiāo.","j":"彼女は医者になることを目標としている。","e":"Her goal is to become a doctor.","k":"그녀는 의사가 되는 것을 목표로 삼고 있다."}]},
{"id":"g5-402","cat":"介詞","t":"憑","g":{"j":"〜によって/〜を頼りに","e":"by means of / relying on","k":"~에 의지하여/~을 근거로"},"p":{"j":"主語 ＋ 憑 ＋ 能力/努力/證件 ＋ 動詞句","e":"Subject + 憑 + ability/effort/document + verb phrase","k":"주어 + 憑 + 능력/노력/증명서 + 동사구"},"ex":{"j":"「憑」は「〜に頼って/〜によって」という意味で、能力・努力・証拠などの根拠を示す。書き言葉寄りで、話し言葉では「靠」もよく使われる。「憑」は後に名詞(資格・能力・證件など)を伴うことが多い。","e":"\"Píng\" means \"by means of / relying on,\" introducing the basis (ability, effort, evidence, or a document) for an action. It's slightly more formal than \"靠,\" though both mean \"to rely on.\"","k":"\"憑\"은 \"~에 의지하여/~을 근거로\"라는 뜻으로 능력·노력·증거 등의 근거를 나타낸다. 문어체에 가까우며, 구어에서는 \"靠\"도 자주 쓰인다."},"eg":[{"z":"他<em>憑</em>自己的努力考上了全國最好的設計學院。","py":"Tā píng zìjǐ de nǔlì kǎoshàng le quánguó zuìhǎo de shèjì xuéyuàn.","j":"彼は自分の努力で、全国で一番良いデザイン学院に合格した。","e":"He got into the best design college in the country through his own effort.","k":"그는 자신의 노력으로 전국에서 가장 좋은 디자인 대학에 합격했다."},{"z":"她<em>憑</em>實力得到了這份工作。","py":"Tā píng shílì dédào le zhè fèn gōngzuò.","j":"彼女は実力でこの仕事を手に入れた。","e":"She got this job on her own merit.","k":"그녀는 실력으로 이 일자리를 얻었다."}]},
{"id":"g5-403","cat":"特殊構文","t":"視......而定","g":{"j":"〜次第だ/〜によって決まる","e":"depends on","k":"~에 따라 정해진다"},"p":{"j":"(主語)＋視＋條件/對象＋而定","e":"(Subject) + 視 + condition/factor + 而定","k":"(주어) + 視 + 조건/대상 + 而定"},"ex":{"j":"「視A而定」は「Aによって決まる/A次第だ」という意味の書き言葉的表現。後ろに理由節を続けず、それ自体で文を終える点に注意(「視…而定」で完結する)。","e":"\"Shì A ér dìng\" means \"it depends on A\" — a set written-style phrase that closes the sentence on its own, with no extra clause needed after 定.","k":"\"視A而定\"는 \"A에 따라 정해진다/A 나름이다\"라는 뜻의 문어체 표현으로, 문장을 그 자체로 마무리한다는 점에 유의한다."},"eg":[{"z":"房子的價格主要<em>視地點和大小而定</em>。","py":"Fángzi de jiàgé zhǔyào shì dìdiǎn hé dàxiǎo ér dìng.","j":"家の価格は主に立地と広さによって決まる。","e":"The price of a house mainly depends on its location and size.","k":"집값은 주로 위치와 크기에 따라 정해진다."},{"z":"能不能出去玩，<em>視天氣而定</em>。","py":"Néng bù néng chūqù wán, shì tiānqì ér dìng.","j":"遊びに行けるかどうかは天気次第だ。","e":"Whether we can go out and play depends on the weather.","k":"놀러 나갈 수 있는지는 날씨에 따라 정해진다."}]},
{"id":"g5-404","cat":"特殊構文","t":"經由......而來......","g":{"j":"〜を経て得られた","e":"come about via / derived through","k":"~을 통해 얻어진"},"p":{"j":"A ＋ 是 ＋ 經由 ＋ B ＋ 而來 ＋ 的","e":"A + 是 + 經由 + B + 而來 + 的","k":"A + 是 + 經由 + B + 而來 + 的"},"ex":{"j":"「經由A而來(的)」は「Aを経て得られた/生じた」という意味で、結果や成果の由来・過程を説明する書き言葉表現。単なる「經過」より「そのプロセスを経て生まれた」というニュアンスが強い。","e":"\"Jīngyóu A ér lái (de)\" explains that something came about via process A — a formal way to describe the origin behind a result, stronger than plain \"經過\" (to pass through).","k":"\"經由A而來(的)\"는 \"A를 거쳐 생겨난/얻어진\"이라는 뜻으로 결과물의 유래나 과정을 설명하는 문어체 표현이다."},"eg":[{"z":"這些數據是<em>經由統計而來</em>的。","py":"Zhèxiē shùjù shì jīngyóu tǒngjì ér lái de.","j":"これらのデータは統計を経て得られたものだ。","e":"These data were derived through statistics.","k":"이 데이터는 통계를 통해 얻어진 것이다."},{"z":"這個結論是<em>經由多次實驗而來</em>的。","py":"Zhège jiélùn shì jīngyóu duō cì shíyàn ér lái de.","j":"この結論は何度もの実験を経て得られたものだ。","e":"This conclusion was reached through many experiments.","k":"이 결론은 여러 차례의 실험을 통해 얻어진 것이다."}]},
{"id":"g5-405","cat":"比較","t":"A跟B......相當","g":{"j":"AはBとほぼ同じ/匹敵する","e":"A is about equal to / comparable with B","k":"A는 B와 비슷하다"},"p":{"j":"A ＋ 跟 ＋ B ＋ (在...方面) ＋ 相當","e":"A + 跟 + B + (在...方面) + 相當","k":"A + 跟 + B + (在...方面) + 相當"},"ex":{"j":"「A跟B相當」は「AとBがほぼ同程度である」ことを表す比較表現。「一樣」より曖昧で「だいたい同じくらい」というニュアンス。数量・程度・能力などを比べる時に使う。","e":"\"A gēn B xiāngdāng\" means \"A is roughly equal to / comparable with B\" — vaguer than \"一樣\" (exactly the same), used to compare degree, quantity, or ability.","k":"\"A跟B相當\"는 \"A와 B가 거의 비슷하다\"는 뜻의 비교 표현으로, \"一樣\"보다 느슨하게 \"대략 비슷함\"을 나타내며 정도·수량·능력 등을 비교할 때 쓴다."},"eg":[{"z":"坐在前面的那個男生，看起來大約<em>跟我年紀相當</em>。","py":"Zuòzài qiánmiàn de nàge nánshēng, kànqǐlái dàyuē gēn wǒ niánjì xiāngdāng.","j":"前に座っているあの男の子は、私と年齢がだいたい同じくらいに見える。","e":"The boy sitting in front looks to be about the same age as me.","k":"앞에 앉아 있는 그 남자애는 나와 나이가 비슷해 보인다."},{"z":"我弟弟的身高<em>跟我相當</em>。","py":"Wǒ dìdi de shēngāo gēn wǒ xiāngdāng.","j":"私の弟の身長は私とほぼ同じだ。","e":"My younger brother's height is about the same as mine.","k":"내 남동생의 키는 나와 비슷하다."}]},
{"id":"g5-406","cat":"比較","t":"比不上","g":{"j":"〜には及ばない、劣る","e":"not as good as; can't compare to","k":"~만 못하다"},"p":{"j":"A ＋ 比不上 ＋ B","e":"A + 比不上 + B","k":"A + 比不上 + B"},"ex":{"j":"「比得上」の否定形で「AはBに及ばない」という意味。比較の順序（A比不上B）を逆にしないよう注意。「不如」とほぼ同義だが、より話し言葉寄り。","e":"The negative form of 比得上, meaning A cannot match B. Word order is fixed as A+比不上+B — don't reverse it. Close in meaning to 不如, but more colloquial.","k":"'比得上'의 부정형으로 'A가 B에 미치지 못한다'는 뜻. 어순은 반드시 'A+比不上+B'로 고정되며 뒤바꾸면 안 된다. '不如'와 뜻이 비슷하지만 더 구어적이다."},"eg":[{"z":"買來的玩具雖然精緻，但<em>比不上</em>親自做的有價值。","py":"Mǎi lái de wánjù suīrán jīngzhì, dàn bǐbushàng qīnzì zuò de yǒu jiàzhí.","j":"買ってきたおもちゃは精巧だが、自分で作ったものの価値には及ばない。","e":"Although the toy you bought is exquisite, it doesn't compare to the value of something made by hand.","k":"사 온 장난감은 정교하지만, 직접 만든 것만큼 가치가 있지는 않다."},{"z":"這家餐廳的口味<em>比不上</em>我阿嬤煮的。","py":"Zhè jiā cāntīng de kǒuwèi bǐbushàng wǒ āma zhǔ de.","j":"このレストランの味は私の祖母が作るものには及ばない。","e":"This restaurant's flavor doesn't compare to what my grandma cooks.","k":"이 식당의 맛은 우리 할머니가 만든 것만 못하다."}]},
{"id":"g5-407","cat":"比較","t":"（A）與B相比","g":{"j":"AとBを比べると","e":"compared with B","k":"B와 비교하면"},"p":{"j":"（A） ＋ 與 ＋ B ＋ 相比","e":"(A) + 與 + B + 相比","k":"(A) + 與 + B + 相比"},"ex":{"j":"「與＋比較対象＋相比」で「〜と比べて」を表す。前の主語Aは省略されることが多く、比較後の変化・結果を後半に続ける。話し言葉の「跟...比起來」より書き言葉的。","e":"\"與 + comparison target + 相比\" means \"compared with...\". Subject A is often omitted since it's already stated; the result/change follows afterward. More formal/written than the colloquial 跟...比起來.","k":"'與+비교 대상+相比'는 '~와 비교하면'을 나타낸다. 주어 A는 이미 언급되었으면 생략되는 경우가 많고, 뒤에는 비교로 인한 변화나 결과가 온다. 구어체인 '跟...比起來'보다 문어적이다."},"eg":[{"z":"這座城市現在<em>與五年前相比</em>，繁榮了許多。","py":"Zhè zuò chéngshì xiànzài yǔ wǔ nián qián xiāngbǐ, fánróngle xǔduō.","j":"この都市は現在、五年前と比べて、大いに繁栄した。","e":"Compared to five years ago, this city has become much more prosperous now.","k":"이 도시는 현재 5년 전과 비교하면 훨씬 번영했다."},{"z":"這篇文章<em>與上次的相比</em>，進步了很多。","py":"Zhè piān wénzhāng yǔ shàng cì de xiāngbǐ, jìnbùle hěn duō.","j":"この文章は前回のと比べて、大いに進歩した。","e":"Compared to the previous one, this article has improved a lot.","k":"이 글은 지난번 것과 비교하면 많이 발전했다."}]},
{"id":"g5-408","cat":"接続","t":"於是","g":{"j":"そこで、それで(結果を導く)","e":"so; thereupon (introduces a resulting action)","k":"그래서(결과를 이끔)"},"p":{"j":"原因/状況 ＋ 於是 ＋ 結果(動作)","e":"cause/situation + 於是 + resulting action","k":"원인/상황 + 於是 + 결과(동작)"},"ex":{"j":"前文の状況を受けて、その結果として起こった動作を導く接続詞。「所以」と似るが、「於是」は時間的に続けて起きた動作性の結果に使われやすく、単純な因果の結論には「所以」の方が自然。","e":"A connector introducing the resulting action that followed from the preceding situation. Similar to 所以, but 於是 leans toward a sequential action that happened next, while 所以 fits a plain logical conclusion better.","k":"앞 문장의 상황에 따라 이어서 일어난 동작(결과)을 이끄는 접속사. '所以'와 비슷하지만 '於是'는 시간적으로 이어서 일어난 동작에 잘 쓰이고, 단순한 논리적 결론에는 '所以'가 더 자연스럽다."},"eg":[{"z":"抽煙有害身體健康，<em>於是</em>爸爸決定戒煙。","py":"Chōuyān yǒuhài shēntǐ jiànkāng, yúshì bàba juédìng jièyān.","j":"喫煙は健康に害があるので、そこでお父さんはタバコをやめることに決めた。","e":"Smoking is harmful to health, so Dad decided to quit smoking.","k":"흡연은 건강에 해롭다, 그래서 아빠는 담배를 끊기로 결심했다."},{"z":"他發現手機不見了，<em>於是</em>趕快回去找。","py":"Tā fāxiàn shǒujī bújiànle, yúshì gǎnkuài huíqù zhǎo.","j":"彼はスマホがなくなったことに気づき、そこで急いで戻って探しに行った。","e":"He realized his phone was missing, so he hurried back to look for it.","k":"그는 휴대폰이 없어진 것을 알아차리고, 그래서 서둘러 돌아가 찾았다."}]},
{"id":"g5-409","cat":"特殊構文","t":"（之）所以......，是因為......","g":{"j":"〜なのは〜だからだ(理由を強調)","e":"the reason...is because...","k":"~한 것은 ~때문이다"},"p":{"j":"（主語） ＋（之）所以＋結果，是因為＋原因","e":"(subject) + (之)所以 + result, 是因為 + reason","k":"(주어) + (之)所以 + 결과, 是因為 + 원인"},"ex":{"j":"結果を先に述べ、その理由を「是因為」で後から強調して説明する構文。「因為...所以...」（原因→結果の順）とは語順が逆になる点に注意。「之」は省略可能。","e":"States the result first with 之所以, then emphasizes the reason afterward with 是因為 — the reverse order of 因為...所以... (reason→result). 之 is optional and can be dropped.","k":"결과를 먼저 말하고 '是因為'로 이유를 강조해서 설명하는 구문. '因為...所以...'(원인→결과 순서)와는 어순이 반대이므로 주의. '之'는 생략 가능하다."},"eg":[{"z":"他<em>之所以</em>成功，<em>是因為</em>堅持和努力。","py":"Tā zhīsuǒyǐ chénggōng, shì yīnwèi jiānchí hé nǔlì.","j":"彼が成功したのは、堅持と努力のおかげである。","e":"The reason he succeeded is because of his persistence and effort.","k":"그가 성공한 것은 끈기와 노력 때문이다."},{"z":"她<em>之所以</em>遲到，<em>是因為</em>路上塞車。","py":"Tā zhīsuǒyǐ chídào, shì yīnwèi lùshàng sāichē.","j":"彼女が遅刻したのは、道が渋滞していたからだ。","e":"The reason she was late is because there was a traffic jam.","k":"그녀가 지각한 것은 길이 막혔기 때문이다."}]},
{"id":"g5-410","cat":"介詞","t":"隨著","g":{"j":"〜につれて、〜に伴って","e":"along with; as...changes","k":"~에 따라"},"p":{"j":"隨著 ＋ 名詞/子句，主語＋動作","e":"隨著 + noun/clause, subject + action","k":"隨著 + 명사/절, 주어 + 동작"},"ex":{"j":"前の変化・状況の進行に伴って、後半の結果が起こることを表す。後半には「開始」「逐漸」など変化を示す語がよく共起する。「因為」のような単純な因果ではなく、並行的な変化の関係を示す点が異なる。","e":"Expresses that the result in the second clause occurs alongside a preceding change or trend. Words like 開始/逐漸 (indicating gradual change) often co-occur. Unlike 因為 (simple causation), it marks a parallel, ongoing relationship of change.","k":"앞의 변화나 상황 진행에 따라 뒤의 결과가 일어남을 나타낸다. 뒷부분에는 '開始', '逐漸'처럼 변화를 나타내는 말이 자주 함께 쓰인다. 단순한 인과관계인 '因為'와 달리 병행적인 변화 관계를 나타낸다는 점이 다르다."},"eg":[{"z":"<em>隨著</em>時代的改變，許多價值觀開始受到挑戰。","py":"Suízhe shídài de gǎibiàn, xǔduō jiàzhíguān kāishǐ shòudào tiǎozhàn.","j":"時代の変化に伴い、多くの価値観が挑戦を受け始めている。","e":"With the changes of the times, many values have begun to be challenged.","k":"시대의 변화에 따라 많은 가치관이 도전을 받기 시작했다."},{"z":"<em>隨著</em>捷運通車，這一區變得越來越熱鬧。","py":"Suízhe jiéyùn tōngchē, zhè yī qū biànde yuè lái yuè rènào.","j":"MRT(捷運)が開通するにつれて、この地区はますます賑やかになった。","e":"With the opening of the MRT, this area has become more and more lively.","k":"지하철(捷運)이 개통됨에 따라 이 지역은 점점 더 번화해졌다."}]},
{"id":"g5-411","cat":"接続","t":"因（為）......而......","g":{"j":"〜によって〜する(原因と結果を1文でつなぐ書き言葉)","e":"because of A, B (formal, one-clause cause-result)","k":"~때문에 ~하다(원인과 결과를 한 문장으로 잇는 문어체)"},"p":{"j":"因（為）＋A(原因)＋而＋B(動作)","e":"因（為）+ A (cause) + 而 + B (action)","k":"因（為）+ A(원인) + 而 + B(동작)"},"ex":{"j":"「因（為）...而...」は原因Aによって結果の動作Bが起こることを一文で表す書き言葉的表現。話し言葉の「因為...所以...」との違いは、後半が独立した文ではなく動詞句である点。","e":"\"因(為)...而...\" links a cause (A) directly to a resulting action (B) within one clause, more formal/written than \"因為...所以...\", which joins two full clauses. The part after 而 must be a verb phrase, not a full sentence.","k":"\"因(為)...而...\"는 원인 A로 인해 결과 동작 B가 일어남을 한 문장 안에서 나타내는 문어체 표현이다. 구어체 \"因為...所以...\"와 달리 而 뒤에는 완전한 문장이 아니라 동사구가 온다."},"eg":[{"z":"政府<em>因人民的抗議而改變</em>這項政策。","py":"Zhèngfǔ yīn rénmín de kàngyì ér gǎibiàn zhè xiàng zhèngcè.","j":"政府は人民の抗議によってこの政策を変えた。","e":"The government changed this policy because of the people's protests.","k":"정부는 국민의 항의로 인해 이 정책을 바꿨다."},{"z":"他<em>因為身體不好而放棄了</em>這份工作。","py":"Tā yīnwèi shēntǐ bù hǎo ér fàngqì le zhè fèn gōngzuò.","j":"彼は体調が悪いため、この仕事をあきらめた。","e":"He gave up this job because his health wasn't good.","k":"그는 몸이 안 좋아서 이 일을 그만두었다."}]},
{"id":"g5-412","cat":"接続","t":"因而","g":{"j":"そのため、それによって(結果を導く接続詞)","e":"as a result, thus (formal result connector)","k":"그로 인해, 그래서(문어체 결과 접속사)"},"p":{"j":"[原因の文]，因而＋[結果の文]","e":"[Cause clause], 因而 + [Result clause]","k":"[원인 문장], 因而 + [결과 문장]"},"ex":{"j":"「因而」は書き言葉で原因から結果を導く接続詞。「所以」より硬い表現で、前の節の後に置く。「因為...而...」のような一文構造とは違い、独立した二つの節をつなぐ。","e":"\"因而\" is a formal written connector meaning \"as a result,\" placed after the cause clause. More literary than \"所以.\" Unlike \"因為...而...,\" it links two separate clauses, not a single clause.","k":"\"因而\"는 문어체에서 원인 뒤에 결과를 잇는 접속사로 \"所以\"보다 격식적이다. \"因為...而...\"와 달리 한 문장이 아니라 독립된 두 개의 절을 연결한다."},"eg":[{"z":"受到颱風影響，<em>因而</em>造成飛機停飛。","py":"Shòudào táifēng yǐngxiǎng, yīn'ér zàochéng fēijī tíngfēi.","j":"台風の影響を受け、そのため飛行機が欠航した。","e":"Affected by the typhoon, flights were consequently grounded.","k":"태풍의 영향을 받아 그로 인해 비행기가 결항되었다."},{"z":"這條路常常塞車，<em>因而</em>許多人選擇搭捷運上班。","py":"Zhè tiáo lù chángcháng sāichē, yīn'ér xǔduō rén xuǎnzé dā jiéyùn shàngbān.","j":"この道はよく渋滞するので、多くの人が捷運(MRT)通勤を選んでいる。","e":"This road is often congested, so many people choose to commute by MRT.","k":"이 길은 자주 막혀서 많은 사람들이 MRT(지하철)로 출근하는 것을 선택한다."}]},
{"id":"g5-413","cat":"接続","t":"為了A而B","g":{"j":"〜のために〜する(目的を表す)","e":"in order to A, B (purpose connector)","k":"~을 위해 ~하다(목적을 나타냄)"},"p":{"j":"為了＋A(目的)＋而＋B(動作)","e":"為了 + A (purpose) + 而 + B (action)","k":"為了 + A(목적) + 而 + B(동작)"},"ex":{"j":"「為了A而B」はAという目的のためにBという行動をすることを表す。原因を表す「因為A而B」と形が似ていて混同しやすいが、為了は目的、因為は理由を表す点が異なる。","e":"\"為了A而B\" expresses doing B for the purpose of achieving A. It looks similar to \"因為A而B\" but differs in meaning: 為了 marks purpose/goal, while 因為 marks cause/reason.","k":"\"為了A而B\"는 A라는 목적을 위해 B라는 행동을 함을 나타낸다. \"因為A而B\"와 형태가 비슷해 혼동하기 쉬우나, 為了는 목적을, 因為는 원인을 나타낸다는 점이 다르다."},"eg":[{"z":"他聽從醫生的建議，開始<em>為了健康而控制</em>飲食。","py":"Tā tīngcóng yīshēng de jiànyì, kāishǐ wèile jiànkāng ér kòngzhì yǐnshí.","j":"彼は医者の勧めに従い、健康のために食事を管理し始めた。","e":"He followed the doctor's advice and started controlling his diet for the sake of his health.","k":"그는 의사의 권유를 따라 건강을 위해 식습관을 관리하기 시작했다."},{"z":"她<em>為了考上理想的大學而</em>每天讀書到深夜。","py":"Tā wèile kǎoshàng lǐxiǎng de dàxué ér měitiān dúshū dào shēnyè.","j":"彼女は理想の大学に合格するために毎日夜遅くまで勉強している。","e":"She studies until late at night every day in order to get into her dream university.","k":"그녀는 원하는 대학에 합격하기 위해 매일 밤늦게까지 공부한다."}]},
{"id":"g5-414","cat":"副詞","t":"無須","g":{"j":"〜する必要がない(書き言葉)","e":"need not, there's no need to (formal)","k":"~할 필요가 없다(문어체)"},"p":{"j":"無須＋動詞(句)","e":"無須 + Verb (phrase)","k":"無須 + 동사(구)"},"ex":{"j":"「無須」は「不必/不需要」の書き言葉的な言い方で、後には動詞(句)が続く。名詞をそのまま続けることはできない点に注意。","e":"\"無須\" is a formal, written equivalent of \"不必/不需要,\" meaning \"there's no need to.\" It must be followed by a verb (phrase), not directly by a noun.","k":"\"無須\"는 \"不必/不需要\"의 문어체 표현으로 '~할 필요가 없다'는 뜻이며 뒤에는 동사(구)가 와야 한다. 명사를 바로 이어 쓸 수 없다는 점에 주의해야 한다."},"eg":[{"z":"政府蓋了一條新的道路後，居民<em>無須</em>再繞遠路。","py":"Zhèngfǔ gài le yī tiáo xīn de dàolù hòu, jūmín wúxū zài rào yuǎnlù.","j":"政府が新しい道路を作った後、住民はもう遠回りする必要がなくなった。","e":"After the government built a new road, residents no longer need to take a detour.","k":"정부가 새 도로를 만든 후, 주민들은 더 이상 멀리 돌아갈 필요가 없어졌다."},{"z":"現在網路購物很方便，<em>無須</em>出門就能買到日常用品。","py":"Xiànzài wǎnglù gòuwù hěn fāngbiàn, wúxū chūmén jiù néng mǎidào rìcháng yòngpǐn.","j":"今はネットショッピングが便利で、外出しなくても日用品を買うことができる。","e":"Nowadays online shopping is so convenient that you can buy daily necessities without even leaving home.","k":"요즘은 인터넷 쇼핑이 편리해서 외출하지 않아도 생필품을 살 수 있다."}]},
{"id":"g5-415","cat":"副詞","t":"不至於","g":{"j":"〜するほどではない(程度が及ばないことを表す)","e":"not to the extent of, won't go so far as to","k":"~할 정도까지는 아니다"},"p":{"j":"(雖然...)但＋不至於＋動詞(句)","e":"(雖然...) 但 + 不至於 + Verb (phrase)","k":"(雖然...) 但 + 不至於 + 동사(구)"},"ex":{"j":"「不至於」は「そこまでひどい程度には至らない」という意味で、単純な否定の「不會」より程度のニュアンスが強い。「雖然...但...」と組み合わせてよく使われる。","e":"\"不至於\" means the situation won't reach a serious extreme, emphasizing degree more than a simple negation like \"不會.\" It's often paired with \"雖然...但...\".","k":"\"不至於\"는 '그 정도까지 심각하지는 않다'는 뜻으로 단순 부정 \"不會\"보다 정도의 뉘앙스가 강하다. \"雖然...但...\"과 함께 자주 쓰인다."},"eg":[{"z":"臺北的冬天雖然濕冷，但還<em>不至於</em>下雪。","py":"Táiběi de dōngtiān suīrán shīlěng, dàn hái bú zhìyú xiàxuě.","j":"台北の冬は湿っていて寒いが、雪が降るほどではない。","e":"Taipei's winter is damp and cold, but not to the point of snowing.","k":"타이베이의 겨울은 습하고 춥지만 눈이 내릴 정도는 아니다."},{"z":"他雖然生氣，但應該<em>不至於</em>辭職。","py":"Tā suīrán shēngqì, dàn yīnggāi bú zhìyú cízhí.","j":"彼は怒っているが、辞職するほどではないはずだ。","e":"He's angry, but he probably won't go so far as to resign.","k":"그는 화가 났지만 사직할 정도까지는 아닐 것이다."}]},
{"id":"g5-416","cat":"否定","t":"絕不","g":{"j":"絶対に〜ない","e":"never, absolutely not","k":"절대로 ~하지 않다"},"p":{"j":"主語＋絕不＋動詞(強い否定)","e":"Subject + 絕不 + Verb","k":"주어 + 絕不 + 동사"},"ex":{"j":"「絕不」は話者の断固たる意志や確信を表す強い否定の副詞で、「不」より語気が強い。習慣を表す「從不」とは違い、「絕不」は意志・決意を表す点に注意。","e":"\"絕不\" is a strong negative adverb expressing firm resolve or certainty — stronger than plain \"不.\" Unlike \"從不\" (never, as a habit), \"絕不\" expresses will and determination, not routine.","k":"\"絕不\"는 화자의 단호한 의지나 확신을 나타내는 강한 부정 부사로 \"不\"보다 어기가 강하다. 습관을 뜻하는 \"從不\"와 달리 \"絕不\"는 의지·결심을 나타낸다는 점에 주의."},"eg":[{"z":"他的個性小心謹慎，沒有根據的話<em>絕不</em>亂說。","py":"Tā de gèxìng xiǎoxīn jǐnshèn, méiyǒu gēnjù dehuà juébú luàn shuō.","j":"彼は性格が慎重で、根拠のないことは絶対に言わない。","e":"He is cautious by nature and will never say things without basis.","k":"그는 성격이 신중해서 근거 없는 말은 절대로 하지 않는다."},{"z":"我<em>絕不</em>會把你的秘密告訴別人。","py":"Wǒ juébú huì bǎ nǐ de mìmì gàosù biérén.","j":"私は絶対にあなたの秘密を誰にも言わない。","e":"I will never tell anyone your secret.","k":"나는 절대로 네 비밀을 아무한테도 말하지 않을 거야."}]},
{"id":"g5-417","cat":"否定","t":"未曾","g":{"j":"今まで一度も〜ない(書き言葉)","e":"have never (yet); literary","k":"지금까지 한 번도 ~한 적이 없다(문어체)"},"p":{"j":"主語＋未曾＋動詞(＋過)","e":"Subject + 未曾 + Verb (+ 過)","k":"주어 + 未曾 + 동사(+過)"},"ex":{"j":"「未曾」は「從來沒有〜過」と同じ意味を表す書き言葉。口語の「沒有〜過」より硬く、文章や公式な場面で使われ、後ろに「過」を伴うことが多い。","e":"\"未曾\" is a literary way of saying \"have never (done something) before,\" equivalent to spoken \"從來沒有…過.\" It's more formal than casual speech and is often followed by \"過.\"","k":"\"未曾\"는 \"從來沒有~過\"와 같은 뜻의 문어체 표현으로 구어의 \"沒有~過\"보다 격식적이며, 뒤에 \"過\"가 자주 함께 쓰인다."},"eg":[{"z":"這篇文章<em>未曾</em>發表過。","py":"Zhè piān wénzhāng wèicéng fābiǎoguò.","j":"この文章はまだ発表されたことがない。","e":"This article has never been published before.","k":"이 글은 아직 발표된 적이 없다."},{"z":"他<em>未曾</em>出過國。","py":"Tā wèicéng chūguò guó.","j":"彼は今まで一度も海外に出たことがない。","e":"He has never been abroad before.","k":"그는 지금까지 한 번도 해외에 나가 본 적이 없다."}]},
{"id":"g5-418","cat":"否定","t":"不得","g":{"j":"〜してはならない(規則・法律上の禁止)","e":"must not, not allowed to (rules/law)","k":"~해서는 안 된다(규칙·법률상 금지)"},"p":{"j":"主語＋不得＋動詞","e":"Subject + 不得 + Verb","k":"주어 + 不得 + 동사"},"ex":{"j":"「不得」は規則や法律などで「〜してはならない」という禁止を表す書き言葉で、話し言葉の「不可以」より正式・硬い言い方。規定文や契約書によく使われる。","e":"\"不得\" is a formal, written way to express prohibition (\"must not\"), used in rules, laws, and contracts. It is more formal than spoken \"不可以.\"","k":"\"不得\"는 규칙이나 법률 등에서 \"~해서는 안 된다\"는 금지를 나타내는 문어체 표현으로, 구어의 \"不可以\"보다 격식적이며 규정문이나 계약서에 자주 쓰인다."},"eg":[{"z":"這家公司規定員工每天工作時間<em>不得</em>超過八小時。","py":"Zhè jiā gōngsī guīdìng yuángōng měitiān gōngzuò shíjiān bùdé chāoguò bā xiǎoshí.","j":"この会社の規定では、社員の一日の勤務時間は8時間を超えてはならない。","e":"This company's rules state that employees' daily working hours must not exceed eight hours.","k":"이 회사 규정에 따르면 직원의 하루 근무 시간은 8시간을 초과해서는 안 된다."},{"z":"圖書館規定，借的書<em>不得</em>超過十本。","py":"Túshūguǎn guīdìng, jiè de shū bùdé chāoguò shí běn.","j":"図書館の規則では、借りられる本は10冊を超えてはいけない。","e":"The library rule states that borrowed books must not exceed ten.","k":"도서관 규정에 따르면 빌리는 책은 10권을 초과할 수 없다."}]},
{"id":"g5-419","cat":"否定","t":"無法","g":{"j":"〜する方法がない、〜できない","e":"unable to, have no way to","k":"~할 방법이 없다, ~할 수 없다"},"p":{"j":"主語＋無法＋動詞","e":"Subject + 無法 + Verb","k":"주어 + 無法 + 동사"},"ex":{"j":"「無法」は客観的な状況や能力の欠如により「〜する方法・手段がない」ことを表す。「不能」よりやや書き言葉的で、原因や制約が強調される場面でよく使われる。","e":"\"無法\" expresses that there is objectively no way to do something, due to circumstances or lack of ability. It is slightly more formal than \"不能\" and often emphasizes an external cause or constraint.","k":"\"無法\"는 객관적인 상황이나 능력 부족으로 \"~할 방법이 없다\"는 뜻을 나타낸다. \"不能\"보다 약간 문어체적이며 외부 원인이나 제약을 강조할 때 자주 쓰인다."},"eg":[{"z":"王美美是一個很愛乾淨的人，<em>無法</em>忍受一點髒亂。","py":"Wáng Měiměi shì yí ge hěn ài gānjìng de rén, wúfǎ rěnshòu yìdiǎn zāngluàn.","j":"王美美はとてもきれい好きな人で、少しの汚れや乱れも我慢できない。","e":"Wang Meimei loves cleanliness and cannot stand even a little mess.","k":"왕메이메이는 아주 깔끔한 것을 좋아하는 사람이라 조금의 지저분함도 참지 못한다."},{"z":"因為下大雨，飛機<em>無法</em>準時起飛。","py":"Yīnwèi xià dàyǔ, fēijī wúfǎ zhǔnshí qǐfēi.","j":"大雨のため、飛行機は時間通りに離陸できなかった。","e":"Because of the heavy rain, the plane was unable to take off on time.","k":"폭우 때문에 비행기가 제시간에 이륙할 수 없었다."}]},
{"id":"g5-420","cat":"接続","t":"以及","g":{"j":"〜および、そして(名詞を並べる書き言葉)","e":"and, as well as (connecting nouns, formal)","k":"~및, 그리고(명사를 나열하는 문어체)"},"p":{"j":"A、B，以及C","e":"A, B, as well as C","k":"A, B, 以及 C"},"ex":{"j":"「以及」は名詞(句)を並べる書き言葉の接続詞で、通常リストの最後の項目の前に置く。「和」「跟」より書き言葉的で、公式な文章や列挙に適する。","e":"\"以及\" is a formal written conjunction that connects nouns, typically placed before the last item in a list. It is more literary than \"和\" or \"跟\" and suits formal writing or enumerations.","k":"\"以及\"는 명사(구)를 나열할 때 쓰는 문어체 접속사로, 보통 목록의 마지막 항목 앞에 놓인다. \"和\"나 \"跟\"보다 문어체적이며 공식적인 글이나 나열에 적합하다."},"eg":[{"z":"我把旅行中遇到的人、有趣的事，<em>以及</em>看到的美景說給大家聽。","py":"Wǒ bǎ lǚxíng zhōng yùdào de rén, yǒuqù de shì, yǐjí kàndào de měijǐng shuō gěi dàjiā tīng.","j":"私は旅行中に出会った人、面白かったこと、そして見た美しい景色をみんなに話した。","e":"I told everyone about the people I met during the trip, the interesting things that happened, as well as the beautiful scenery I saw.","k":"나는 여행 중에 만난 사람들, 재미있었던 일들, 그리고 본 아름다운 풍경을 모두에게 이야기해 주었다."},{"z":"這次會議邀請了老師、家長，<em>以及</em>學生代表一起參加。","py":"Zhè cì huìyì yāoqǐngle lǎoshī, jiāzhǎng, yǐjí xuéshēng dàibiǎo yìqǐ cānjiā.","j":"今回の会議には先生、保護者、そして学生代表が招かれて一緒に参加した。","e":"This meeting invited teachers, parents, as well as student representatives to attend together.","k":"이번 회의에는 선생님, 학부모, 그리고 학생 대표가 초대되어 함께 참석했다."}]},
{"id":"g5-421","cat":"接続","t":"一來......二來......","g":{"j":"理由を2つ並べる(まず1つ、次に1つ)","e":"listing two reasons (for one thing... for another)","k":"이유를 두 가지 나열함 (우선...또한...)"},"p":{"j":"一來 ＋ 理由1，二來 ＋ 理由2","e":"yìlái + reason 1, èrlái + reason 2","k":"一來 + 이유1, 二來 + 이유2"},"ex":{"j":"書き言葉寄りの表現で、原因や理由を2つ並べて説明する。話し言葉では「一方面…一方面…」のほうがよく使われる点に注意。","e":"A somewhat formal way to list two parallel reasons or causes. In casual speech, 一方面...一方面... is more common than 一來...二來.","k":"이유나 원인을 두 가지로 나열할 때 쓰는 다소 격식적인 표현. 회화체에서는 一方面…一方面…을 더 많이 쓴다는 점에 유의."},"eg":[{"z":"這裡<em>一來</em>沒電話，<em>二來</em>沒網路，聯絡很不方便。","py":"Zhè lǐ yìlái méi diànhuà, èrlái méi wǎnglù, liánluò hěn bù fāngbiàn.","j":"ここは、まず電話がなく、次にネットもないので、連絡がとても不便だ。","e":"This place has no phone for one thing, and no internet for another, so it's very inconvenient to get in touch.","k":"이곳은 우선 전화도 없고 인터넷도 없어서 연락하기가 매우 불편하다."},{"z":"學中文<em>一來</em>可以交朋友，<em>二來</em>可以了解台灣文化。","py":"Xué Zhōngwén yìlái kěyǐ jiāo péngyǒu, èrlái kěyǐ liǎojiě Táiwān wénhuà.","j":"中国語を学ぶと、まず友達ができるし、次に台湾の文化も理解できる。","e":"Learning Chinese lets you make friends for one thing, and understand Taiwanese culture for another.","k":"중국어를 배우면 우선 친구를 사귈 수 있고, 또한 대만 문화도 이해할 수 있다."}]},
{"id":"g5-422","cat":"接続","t":"既A，也B","g":{"j":"AでもありBでもある(両方とも当てはまる)","e":"both A and B are true","k":"A이기도 하고 B이기도 하다"},"p":{"j":"既 ＋ A，也 ＋ B","e":"jì + A, yě + B","k":"既 + A, 也 + B"},"ex":{"j":"AとBが同時に成り立つことを示す、やや書き言葉的な表現。「不但…而且…」と似ているが、既…也…はAとBを対等に扱い、程度の強調は弱い。","e":"Shows that A and B are both true at the same time; somewhat formal. Similar to 不但...而且..., but 既...也... treats A and B as equal, without implying B is stronger than A.","k":"A와 B가 동시에 성립함을 나타내는 다소 문어적 표현. 不但…而且…와 비슷하지만 既…也…는 A와 B를 대등하게 다루며 정도의 강조는 약하다."},"eg":[{"z":"來臺灣<em>既</em>可以學中文，<em>也</em>可以享受美食。","py":"Lái Táiwān jì kěyǐ xué Zhōngwén, yě kěyǐ xiǎngshòu měishí.","j":"台湾に来れば、中国語を学ぶこともできるし、美食を楽しむこともできる。","e":"Coming to Taiwan lets you both learn Chinese and enjoy great food.","k":"대만에 오면 중국어도 배울 수 있고 맛있는 음식도 즐길 수 있다."},{"z":"這份工作<em>既</em>輕鬆，<em>也</em>很有意義。","py":"Zhè fèn gōngzuò jì qīngsōng, yě hěn yǒu yìyì.","j":"この仕事は楽でもあり、とてもやりがいもある。","e":"This job is both relaxed and very meaningful.","k":"이 일은 편하기도 하고 의미도 매우 있다."}]},
{"id":"g5-423","cat":"否定","t":"（請）勿","g":{"j":"〜しないでください(掲示・注意書き)","e":"please do not (signs/notices)","k":"~하지 마십시오 (안내문·표지판)"},"p":{"j":"(請) ＋ 勿 ＋ 動詞","e":"(qǐng) + wù + verb","k":"(請) + 勿 + 동사"},"ex":{"j":"公共の場の掲示や注意書きに使われる書き言葉の禁止表現。会話では使わず「不要」「別」を使う。「請勿」の形が最もよく見られる。","e":"A formal, written prohibition used on public signs and notices, not in everyday speech (use 不要/別 there instead). The set phrase 請勿 is the most common form.","k":"공공장소의 안내문·표지판에 쓰이는 문어체 금지 표현. 회화에서는 쓰지 않고 不要/別를 쓴다. 請勿라는 형태로 가장 많이 쓰인다."},"eg":[{"z":"請<em>勿</em>在公共區域吸煙！","py":"Qǐng wù zài gōnggòng qūyù xīyān!","j":"公共エリアでの喫煙はご遠慮ください!","e":"Please do not smoke in the public area!","k":"공공구역에서는 흡연을 삼가 주십시오!"},{"z":"請<em>勿</em>在圖書館內大聲說話。","py":"Qǐng wù zài túshūguǎn nèi dàshēng shuōhuà.","j":"図書館内では大きな声で話さないでください。","e":"Please do not talk loudly inside the library.","k":"도서관 안에서는 큰 소리로 이야기하지 마십시오."}]},
{"id":"g5-424","cat":"特殊構文","t":"使得","g":{"j":"〜という結果になる、〜させる(結果を導く)","e":"cause/result in (introduces a resulting state)","k":"~하게 되다, ~라는 결과를 초래하다"},"p":{"j":"原因句 ＋ 使得 ＋ 結果句","e":"cause clause + shǐde + result clause","k":"원인절 + 使得 + 결과절"},"ex":{"j":"書き言葉で、前の原因が後ろの結果や状態を引き起こすことを表す。似た働きの「使」より節と節をつなぐ性質が強く、後ろに具体的な指示や依頼は続かない。","e":"A formal, written expression showing that a preceding cause leads to a following result or state. More clause-connecting than 使, and cannot be followed by a command or request.","k":"앞의 원인이 뒤의 결과나 상태를 초래함을 나타내는 문어체 표현. 使보다 절과 절을 연결하는 성격이 강하며, 뒤에 구체적인 지시나 요청은 올 수 없다."},"eg":[{"z":"這位作家花了兩年的時間修改，<em>使得</em>這部小說更加完整。","py":"Zhè wèi zuòjiā huāle liǎng nián de shíjiān xiūgǎi, shǐde zhè bù xiǎoshuō gèngjiā wánzhěng.","j":"この作家は2年の時間をかけて修正し、この小説をより完全なものにした。","e":"This writer spent two years revising it, making the novel even more complete.","k":"이 작가는 2년의 시간을 들여 수정하여 이 소설을 더욱 완성도 있게 만들었다."},{"z":"長期的努力<em>使得</em>他終於成功了。","py":"Chángqí de nǔlì shǐde tā zhōngyú chénggōng le.","j":"長期にわたる努力が、彼をついに成功させた。","e":"His long-term effort finally led him to success.","k":"장기간의 노력이 마침내 그를 성공하게 만들었다."}]},
{"id":"g5-425","cat":"特殊構文","t":"使","g":{"j":"〜させる(使役動詞、やや書き言葉)","e":"to make/cause (someone to do something)","k":"~하게 만들다 (사역동사, 다소 문어체)"},"p":{"j":"主語 ＋ 使 ＋ 対象 ＋ 動詞/形容詞","e":"subject + shǐ + object + verb/adjective","k":"주어 + 使 + 대상 + 동사/형용사"},"ex":{"j":"「讓」と同じ使役の意味を持つが、より書き言葉的でフォーマル。無生物や抽象的な事柄が主語になることが多く、口語では「讓」のほうが自然。","e":"A causative verb similar in meaning to 讓, but more formal/written. The subject is often something inanimate or abstract; in casual speech 讓 is more natural.","k":"讓와 같은 사역의 의미지만 더 문어적이고 격식적이다. 무생물이나 추상적인 것이 주어가 되는 경우가 많으며, 회화에서는 讓가 더 자연스럽다."},"eg":[{"z":"早上喝一杯咖啡能<em>使</em>他頭腦更加清醒。","py":"Zǎoshang hē yìbēi kāfēi néng shǐ tā tóunǎo gèngjiā qīngxǐng.","j":"朝コーヒーを1杯飲むと、彼の頭をより冴えさせることができる。","e":"Drinking a cup of coffee in the morning can make his mind clearer.","k":"아침에 커피 한 잔을 마시면 그의 머리를 더욱 맑게 할 수 있다."},{"z":"老師的鼓勵<em>使</em>我更有信心。","py":"Lǎoshī de gǔlì shǐ wǒ gèng yǒu xìnxīn.","j":"先生の励ましが、私をより自信を持たせてくれた。","e":"The teacher's encouragement made me more confident.","k":"선생님의 격려가 나를 더 자신감 있게 만들었다."}]},
{"id":"g5-426","cat":"特殊構文","t":"令","g":{"j":"「~させる」(令+人+動詞・形容詞)","e":"to cause/make (someone feel or do something)","k":"~하게 하다(令+사람+동사/형용사)"},"p":{"j":"A ＋ 令 ＋ B ＋ 感受/動作","e":"A + 令 + B + feeling/action","k":"A + 令 + B + 느낌/행동"},"ex":{"j":"「令」は書き言葉的な使役表現で「讓/使」とほぼ同じ意味だが、より正式・硬い文体で使われる。後には必ず対象(人)＋感情・状態を表す語句が続く。話し言葉では「讓」の方が自然。","e":"\"令\" is a formal, written causative verb similar to 讓/使, meaning \"to make someone feel/become.\" It must be followed by a person plus an emotional or resultant state. In casual speech, 讓 sounds more natural.","k":"\"令\"은 문어체 사역 표현으로 \"讓/使\"와 비슷하지만 더 격식적이다. 반드시 대상(사람)+감정·상태 표현이 뒤따라야 한다. 구어에서는 \"讓\"이 더 자연스럽다."},"eg":[{"z":"這間餐廳的氣氛和服務，<em>令人印象深刻</em>。","py":"Zhè jiān cāntīng de qìfēn hàn fúwù, lìng rén yìnxiàng shēnkè.","j":"このレストランの雰囲気とサービスは、人に深い印象を与える。","e":"This restaurant's atmosphere and service leave a deep impression on people.","k":"이 식당의 분위기와 서비스는 사람들에게 깊은 인상을 남긴다."},{"z":"這部電影的結局，<em>令觀眾感到十分驚訝</em>。","py":"Zhè bù diànyǐng de jiéjú, lìng guānzhòng gǎndào shífēn jīngyà.","j":"この映画の結末は、観客をとても驚かせた。","e":"The ending of this movie left the audience utterly astonished.","k":"이 영화의 결말은 관객을 매우 놀라게 했다."}]},
{"id":"g5-427","cat":"接続","t":"（在）......之餘","g":{"j":"「~するかたわら/~する合間に」","e":"besides/in addition to (doing) ~, in the margin of ~","k":"~하는 틈틈이/~하는 한편"},"p":{"j":"(在)＋VP1(活動)＋之餘＋VP2(別のこと)","e":"(在) + VP1(main activity) + 之餘 + VP2(additional action)","k":"(在) + VP1(활동) + 之餘 + VP2(추가 행동)"},"ex":{"j":"「之餘」は主な行動の「合間・余った時間」に別のことをすることを表す。「之後」(〜した後)と違い、時間的な前後関係ではなく「〜する傍らで」という意味。前の「在」は省略可。","e":"\"之餘\" expresses doing something extra in the margin/spare time of a main activity. Unlike 之後 (after), it's not about time sequence but about doing something alongside the main action. The leading 在 is often omissible.","k":"\"之餘\"는 주된 행동을 하는 틈틈이(여유 시간에) 다른 일을 하는 것을 나타낸다. \"之後\"(~한 후)와 달리 시간 순서가 아니라 \"~하는 한편\"이라는 의미다. 앞의 \"在\"는 생략 가능하다."},"eg":[{"z":"他<em>在工作之餘</em>，還不忘充實自己的專業知識。","py":"Tā zài gōngzuò zhīyú, hái bú wàng chōngshí zìjǐ de zhuānyè zhīshì.","j":"彼は仕事の合間に、自分の専門知識を高めることも忘れない。","e":"Besides his work, he doesn't forget to enrich his professional knowledge.","k":"그는 일하는 틈틈이 자신의 전문 지식을 쌓는 것도 잊지 않는다."},{"z":"她<em>在照顧孩子之餘</em>，也堅持每天運動。","py":"Tā zài zhàogù háizi zhīyú, yě jiānchí měitiān yùndòng.","j":"彼女は子育てのかたわら、毎日運動することも欠かさない。","e":"Besides taking care of the children, she also keeps exercising every day.","k":"그녀는 아이를 돌보는 틈틈이 매일 운동도 꾸준히 한다."}]},
{"id":"g5-428","cat":"副詞","t":"一口氣","g":{"j":"「一気に、休まずに」","e":"in one go, without stopping or pausing","k":"단숨에, 쉬지 않고"},"p":{"j":"主語＋一口氣＋動詞(+完/了)＋(数量)","e":"Subject + 一口氣 + Verb(+完/了) + (quantity)","k":"주어 + 一口氣 + 동사(+完/了) + (수량)"},"ex":{"j":"「一口氣」は動詞の前に置き、途中で休まず一気に動作を完了することを表す副詞句。運動量や作業量が多い場合によく使われる。動詞の後ろに置く誤りに注意。","e":"\"一口氣\" is an adverbial placed before the verb, meaning an action is completed continuously without stopping. It's often used with strenuous or lengthy tasks (running, drinking, finishing work). A common mistake is placing it after the verb.","k":"\"一口氣\"는 동사 앞에 놓여 중간에 멈추지 않고 단숨에 동작을 끝냄을 나타내는 부사구다. 운동량이나 작업량이 많을 때 자주 쓰인다. 동사 뒤에 놓는 실수에 주의해야 한다."},"eg":[{"z":"他<em>一口氣</em>跑了五千公尺。","py":"Tā yìkǒuqì pǎo le wǔqiān gōngchǐ.","j":"彼は一気に5000メートルを走った。","e":"He ran five thousand meters in one go.","k":"그는 단숨에 5천 미터를 뛰었다."},{"z":"她<em>一口氣</em>喝完了一整瓶水。","py":"Tā yìkǒuqì hē wán le yì zhěng píng shuǐ.","j":"彼女は一気にペットボトル一本分の水を飲み干した。","e":"She drank an entire bottle of water in one gulp.","k":"그녀는 단숨에 물 한 병을 다 마셨다."}]},
{"id":"g5-429","cat":"副詞","t":"早晚","g":{"j":"「遅かれ早かれ、いつかは」","e":"sooner or later, eventually","k":"조만간, 언젠가는"},"p":{"j":"早晚＋會＋動詞句","e":"早晚 + 會 + VP","k":"早晚 + 會 + 동사구"},"ex":{"j":"「早晚」はここでは「朝晩」の意味ではなく、「遅かれ早かれ、必ずいつか」という副詞。「會」と組み合わせて使い、文末に「的」をつけて強調することが多い。「遲早」とほぼ同義で置き換え可能。","e":"Here \"早晚\" doesn't mean \"morning and evening\" but functions as an adverb meaning \"sooner or later, inevitably.\" It's typically paired with 會 before the verb, often ending with 的 for emphasis. It's interchangeable with the synonym 遲早.","k":"여기서 \"早晚\"은 \"아침저녁\"이 아니라 \"조만간, 언젠가는 반드시\"라는 부사이다. 보통 동사 앞에 \"會\"와 함께 쓰이고 문장 끝에 \"的\"를 붙여 강조하는 경우가 많다. 동의어 \"遲早\"와 바꿔 쓸 수 있다."},"eg":[{"z":"我們還是把車子壞掉的事告訴爸爸吧，他<em>早晚</em>會知道的。","py":"Wǒmen háishì bǎ chēzi huàidiào de shì gàosù bàba ba, tā zǎowǎn huì zhīdào de.","j":"やっぱり車が壊れたことをお父さんに言おうよ、彼は遅かれ早かれ知ることになるんだから。","e":"Let's just tell Dad the car broke down—he'll find out sooner or later.","k":"그냥 차 고장 난 걸 아빠한테 말씀드리자. 아빠는 조만간 알게 되실 거야."},{"z":"你現在不承認也沒用，<em>早晚</em>會被大家發現的。","py":"Nǐ xiànzài bù chéngrèn yě méiyòng, zǎowǎn huì bèi dàjiā fāxiàn de.","j":"今認めなくても無駄だよ、遅かれ早かれみんなに見つかるんだから。","e":"It's no use denying it now—everyone will find out sooner or later.","k":"지금 인정하지 않아도 소용없어, 조만간 다들 알게 될 거야."}]},
{"id":"g5-430","cat":"接続","t":"若","g":{"j":"「もし〜ならば」(書き言葉の「如果」)","e":"if (a more formal/written equivalent of 如果)","k":"만약 ~라면(문어체 \"如果\")"},"p":{"j":"若＋条件節、＋結果節","e":"若 + condition clause, + result clause","k":"若 + 조건절, + 결과절"},"ex":{"j":"「若」は「如果」の書き言葉版で、ニュースや正式な文章でよく使われ、日常会話ではあまり使わない(会話では「如果」「要是」が自然)。「就」や「的話」を伴わなくても文法的に正しい。","e":"\"若\" is the written/formal counterpart of 如果, common in news reports and formal writing but rare in daily conversation (where 如果/要是 sound more natural). It's grammatically complete without 就 or 的話, though they may follow for emphasis.","k":"\"若\"는 \"如果\"의 문어체 표현으로 뉴스나 격식 있는 글에서 자주 쓰이며 일상 대화에서는 \"如果/要是\"가 더 자연스럽다. \"就\"나 \"的話\" 없이도 문법적으로 완전하다."},"eg":[{"z":"<em>若</em>成本增加，價格恐怕也將提高。","py":"Ruò chéngběn zēngjiā, jiàgé kǒngpà yě jiāng tígāo.","j":"もしコストが増えれば、価格もおそらく上がるだろう。","e":"If costs increase, prices will probably rise as well.","k":"만약 원가가 오르면 가격도 아마 오를 것이다."},{"z":"<em>若</em>明天下雨，運動會就會延期。","py":"Ruò míngtiān xiàyǔ, yùndònghuì jiù huì yánqí.","j":"もし明日雨が降ったら、運動会は延期になるだろう。","e":"If it rains tomorrow, the sports day will be postponed.","k":"만약 내일 비가 오면 운동회는 연기될 것이다."}]},
{"id":"g5-431","cat":"接続","t":"要不是","g":{"j":"〜がなかったら(反事実の仮定)","e":"if it weren't for...","k":"~가 아니었다면"},"p":{"j":"要不是＋A，就＋B(事実に反する仮定と、その結果)","e":"要不是 + A, (就) + B","k":"要不是 + A, (就) + B"},"ex":{"j":"「要不是」は事実に反する仮定を表し、「もしAがなかったら」という意味。後半にはAがなければ起きていたはずの結果を述べる。「如果不是」と似るが、より口語的で安堵や後悔のニュアンスを伴う。","e":"'要不是' expresses a counterfactual: 'if it weren't for X, Y would have happened.' Often paired with 就. Similar to 如果不是 but more colloquial, often implying relief or regret about what almost happened.","k":"'要不是'는 사실과 반대되는 가정을 나타내며 'A가 아니었다면 B했을 것이다'라는 뜻이다. 뒤에는 주로 A가 없었을 때 벌어졌을 결과가 온다. '如果不是'와 비슷하지만 더 구어적이며 안도나 아쉬움의 뉘앙스가 있다."},"eg":[{"z":"<em>要不是</em>你的幫忙，這件事可能就沒辦法進行得這麼順利。","py":"Yàobúshì nǐ de bāngmáng, zhè jiàn shì kěnéng jiù méi bànfǎ jìnxíng de zhème shùnlì.","j":"あなたが手伝ってくれなかったら、この件はこんなに順調には進められなかったかもしれない。","e":"If it weren't for your help, this might not have gone so smoothly.","k":"네가 도와주지 않았더라면, 이 일은 이렇게 순조롭게 진행되지 못했을지도 몰라."},{"z":"<em>要不是</em>你提醒我，我早就忘記今天要開會了。","py":"Yàobúshì nǐ tíxǐng wǒ, wǒ zǎo jiù wàngjì jīntiān yào kāihuì le.","j":"あなたが私に注意してくれなかったら、私はとっくに今日会議があることを忘れていただろう。","e":"If you hadn't reminded me, I would have already forgotten that there's a meeting today.","k":"네가 알려주지 않았더라면, 나는 벌써 오늘 회의가 있는 걸 잊어버렸을 거야."}]},
{"id":"g5-432","cat":"接続","t":"萬一","g":{"j":"万一〜したら","e":"in case / what if (something unlikely happens)","k":"만일 ~하면"},"p":{"j":"萬一＋A(望ましくない事態)，就＋B(対応策)","e":"萬一 + A (undesirable event), (就) + B (response)","k":"萬一 + A(바람직하지 않은 일), (就) + B(대응)"},"ex":{"j":"「萬一」は「もしも(望ましくなく、確率の低い事態が)起きたら」という意味で、悪い可能性への備えを述べるときに使う。「如果」より起こる可能性が低いというニュアンスが強い。","e":"'萬一' means 'in the unlikely case that (something undesirable) happens,' used to talk about precautions for a low-probability bad event. Compared to plain 如果, it stresses the event is unlikely and often unwanted.","k":"'萬一'는 '혹시라도 (바람직하지 않은 일이) 일어나면'이라는 뜻으로, 낮은 확률의 나쁜 상황에 대비할 때 쓴다. '如果'보다 일어날 가능성이 낮다는 뉘앙스가 강하다."},"eg":[{"z":"如果島上有家醫院，<em>萬一</em>發生車禍可以立即處理。","py":"Rúguǒ dǎo shàng yǒu jiā yīyuàn, wànyī fāshēng chēhuò kěyǐ lìjí chǔlǐ.","j":"もし島に病院が一軒あれば、万一交通事故が起きてもすぐに対応できる。","e":"If there were a hospital on the island, in case a car accident happened, it could be dealt with immediately.","k":"만약 섬에 병원이 하나 있다면, 만일 교통사고가 나도 즉시 처리할 수 있다."},{"z":"你出門記得帶傘，<em>萬一</em>下雨就不會淋濕了。","py":"Nǐ chūmén jìde dài sǎn, wànyī xiàyǔ jiù bú huì línshī le.","j":"出かけるとき傘を持っていくのを忘れないで。万一雨が降ってもぬれないから。","e":"Remember to bring an umbrella when you go out, in case it rains, so you won't get wet.","k":"나갈 때 우산 챙기는 거 잊지 마. 만일 비가 오면 안 젖을 거야."}]},
{"id":"g5-433","cat":"接続","t":"一旦","g":{"j":"いったん〜したら","e":"once ... (then)","k":"일단 ~하면"},"p":{"j":"一旦＋A(動作/変化)，就＋B(その後に続く、通常戻せない結果)","e":"一旦 + A (an action/change), (就) + B (a resulting, often hard-to-reverse outcome)","k":"一旦 + A(동작/변화), (就) + B(그에 따른, 되돌리기 어려운 결과)"},"ex":{"j":"「一旦」は「あるきっかけが起きたら、その後は」という意味で、後にしばしば取り返しのつかない結果が続く。「萬一」と違い、話し手はその事が起きる可能性が低いとは限らない。","e":"'一旦' means 'once X happens, then...', usually followed by a consequence that is hard to reverse. Unlike 萬一, it doesn't imply the event is unlikely — it can be about something certain or common.","k":"'一旦'은 '일단 어떤 일이 일어나면 그 다음에는'이라는 뜻으로, 뒤에 되돌리기 어려운 결과가 온다. '萬一'과 달리 그 일이 일어날 가능성이 낮다는 뜻은 없다."},"eg":[{"z":"環境<em>一旦</em>破壞了，就很難再恢復。","py":"Huánjìng yīdàn pòhuài le, jiù hěn nán zài huīfù.","j":"環境はいったん破壊されると、再び回復するのは難しい。","e":"Once the environment is destroyed, it's very hard to restore it.","k":"환경은 일단 파괴되면 다시 회복하기 매우 어렵다."},{"z":"這種病<em>一旦</em>發現，就要馬上治療。","py":"Zhè zhǒng bìng yīdàn fāxiàn, jiù yào mǎshàng zhìliáo.","j":"この病気は一旦発見したら、すぐに治療しなければならない。","e":"Once this disease is discovered, it must be treated immediately.","k":"이 병은 일단 발견되면 바로 치료해야 한다."}]},
{"id":"g5-434","cat":"特殊構文","t":"沒有......就沒有......","g":{"j":"AがなければBもない","e":"without A, there would be no B","k":"A가 없으면 B도 없다"},"p":{"j":"沒有＋A，就沒有＋B(AがBの成立に必要不可欠であることを強調)","e":"沒有 + A, 就沒有 + B (emphasizing A is essential for B)","k":"沒有 + A, 就沒有 + B(A가 B의 필수 조건임을 강조)"},"ex":{"j":"「沒有A，就沒有B」はAがBの必要条件であることを強調する構文で、Aの功績や重要性を讃える文脈でよく使われる。単に否定文を二つ並べたのではなく、因果・貢献関係を示す点に注意。","e":"'沒有A，就沒有B' emphasizes that A is a necessary condition for B, often used to praise someone's contribution or importance. It's not just two negative statements — it highlights a cause-and-contribution relationship.","k":"'沒有A，就沒有B'는 A가 B의 필수 조건임을 강조하는 구문으로, 누군가의 공로나 중요성을 칭찬할 때 자주 쓴다. 단순한 부정문 나열이 아니라 인과·기여 관계를 나타낸다는 점에 유의해야 한다."},"eg":[{"z":"<em>沒有</em>他的指導，<em>就沒有</em>這麼有創意的點子。","py":"Méiyǒu tā de zhǐdǎo, jiù méiyǒu zhème yǒu chuàngyì de diǎnzi.","j":"彼の指導がなければ、こんなに独創的なアイデアもなかっただろう。","e":"Without his guidance, there wouldn't be such a creative idea.","k":"그의 지도가 없었다면, 이렇게 창의적인 아이디어도 없었을 것이다."},{"z":"<em>沒有</em>農夫辛苦耕種，<em>就沒有</em>我們每天吃的白米飯。","py":"Méiyǒu nóngfū xīnkǔ gēngzhòng, jiù méiyǒu wǒmen měitiān chī de báimǐfàn.","j":"農夫が苦労して耕さなければ、私たちが毎日食べる白いご飯もない。","e":"Without farmers working hard to grow crops, there would be no rice for us to eat every day.","k":"농부들이 힘들게 농사를 짓지 않았다면, 우리가 매일 먹는 쌀밥도 없을 것이다."}]},
{"id":"g5-435","cat":"接続","t":"儘管......（還/但是）......","g":{"j":"〜にもかかわらず(それでも)〜","e":"even though / despite ..., (still) ...","k":"~에도 불구하고 (그래도) ~"},"p":{"j":"儘管＋A(譲歩となる事実)，還是/但是＋B(Aに影響されない結果)","e":"儘管 + A (a concessive fact), 還是/但是 + B (a result unaffected by A)","k":"儘管 + A(양보하는 사실), 還是/但是 + B(A의 영향을 받지 않는 결과)"},"ex":{"j":"「儘管」は「雖然」と似て譲歩を表すが、後半に「還是/但是」を伴い、Aという事実があっても結果Bは変わらないことを強調する、やや書き言葉寄りの表現。","e":"'儘管' is similar to 雖然 in expressing concession, but pairs with 還是/但是 to stress that result B holds true regardless of fact A. It sounds slightly more formal/written than 雖然.","k":"'儘管'은 '雖然'처럼 양보를 나타내지만 뒤에 '還是/但是'와 함께 쓰여 A라는 사실에도 불구하고 결과 B는 변하지 않음을 강조하며, '雖然'보다 다소 격식 있고 문어적인 느낌이다."},"eg":[{"z":"<em>儘管</em>不常見面，<em>但是</em>我們每次聚會都聊得很開心。","py":"Jǐnguǎn bù cháng jiànmiàn, dànshì wǒmen měi cì jùhuì dōu liáo de hěn kāixīn.","j":"あまり頻繁には会わないけれど、集まるたびにいつも楽しく話している。","e":"Even though we don't see each other often, we always have a great time chatting whenever we get together.","k":"자주 만나지는 않지만, 모일 때마다 항상 즐겁게 이야기한다."},{"z":"<em>儘管</em>外面下著大雨，他<em>還是</em>準時到公司上班。","py":"Jǐnguǎn wàimiàn xià zhe dàyǔ, tā háishì zhǔnshí dào gōngsī shàngbān.","j":"外は大雨が降っているにもかかわらず、彼は時間どおりに会社に出勤した。","e":"Even though it's pouring rain outside, he still got to the office on time.","k":"밖에 큰비가 내리고 있는데도, 그는 제시간에 회사에 출근했다."}]},
{"id":"g5-436","cat":"介詞","t":"將","g":{"j":"「將」で目的語を動詞の前に出す(書き言葉の「把」)","e":"to move the object before the verb (formal equivalent of 把)","k":"목적어를 동사 앞으로 이동시키는 문어체 \"把\""},"p":{"j":"主語＋將＋目的語＋動詞(+補語)","e":"Subject + 將 + Object + Verb (+ Complement)","k":"주어 + 將 + 목적어 + 동사(+보어)"},"ex":{"j":"「將」は書き言葉で「把」とほぼ同じ働きをし、目的語を動詞の前に置いて処置・変化の結果を強調する。話し言葉では「把」の方が普通で、「將」は文章語や正式な場面で使われる。","e":"\"將\" functions like the more colloquial \"把,\" moving the object before the verb to emphasize what happens to it. It's typical of written or formal Chinese; in speech, 把 is far more common.","k":"\"將\"은 문어체에서 \"把\"와 거의 같은 역할을 하며, 목적어를 동사 앞에 두어 결과를 강조한다. 구어에서는 \"把\"를 더 많이 쓰고 \"將\"은 격식체나 문어에 주로 쓰인다."},"eg":[{"z":"老師也必須不斷學習，才能<em>將新知識帶給學生</em>。","py":"Lǎoshī yě bìxū búduàn xuéxí, cái néng jiāng xīn zhīshì dàigěi xuéshēng.","j":"先生も絶えず学び続けてこそ、新しい知識を学生に伝えることができる。","e":"Teachers must also keep learning constantly in order to pass new knowledge on to students.","k":"선생님도 끊임없이 배워야만 새로운 지식을 학생들에게 전달할 수 있다."},{"z":"公司決定<em>將這個消息告訴所有員工</em>。","py":"Gōngsī juédìng jiāng zhège xiāoxí gàosù suǒyǒu yuángōng.","j":"会社はこのニュースを全社員に伝えることに決めた。","e":"The company decided to tell all the employees this news.","k":"회사는 이 소식을 모든 직원에게 알리기로 결정했다."}]},
{"id":"g5-437","cat":"補語","t":"Vs得要命","g":{"j":"「〜得要命」で程度が極端に高いことを表す(すごく〜だ)","e":"\"Vs得要命\" expresses an extreme degree — \"incredibly/terribly ~\"","k":"\"〜得要命\"으로 정도가 극단적으로 심함을 나타냄(엄청 ~하다)"},"p":{"j":"形容詞(状態動詞)＋得要命","e":"Stative Verb/Adjective + 得要命","k":"형용사(상태동사) + 得要命"},"ex":{"j":"「得要命」は「得很」よりずっと強い口語的な誇張表現で、「死ぬほど〜」に近いニュアンス。状態動詞(形容詞)にしか使えず、動作動詞には使わない。","e":"\"得要命\" is a colloquial exaggeration much stronger than \"得很,\" close to \"to death\" in English. It attaches only to stative verbs/adjectives, not action verbs.","k":"\"得要命\"은 \"得很\"보다 훨씬 강한 구어체 과장 표현으로 \"죽을 만큼 ~하다\"에 가깝다. 상태동사(형용사)에만 쓰이고 동작동사에는 쓰지 않는다."},"eg":[{"z":"就算出太陽，天氣還是<em>冷得要命</em>。","py":"Jiùsuàn chū tàiyáng, tiānqì háishì lěng de yàomìng.","j":"たとえ晴れても、天気はやっぱりものすごく寒い。","e":"Even if the sun comes out, the weather is still freezing cold.","k":"해가 나도 날씨는 여전히 엄청 춥다."},{"z":"考試前，大家都<em>緊張得要命</em>。","py":"Kǎoshì qián, dàjiā dōu jǐnzhāng de yàomìng.","j":"試験の前は、みんなものすごく緊張している。","e":"Before the exam, everyone was incredibly nervous.","k":"시험 전에는 다들 엄청 긴장한다."}]},
{"id":"g5-438","cat":"接続","t":"不料","g":{"j":"「不料」で予想外の展開を表す(思いがけず〜)","e":"\"不料\" introduces an unexpected turn of events (\"unexpectedly\")","k":"\"不料\"로 예상 밖의 전개를 나타냄(뜻밖에도)"},"p":{"j":"(前文)，不料＋(予想外の出来事)","e":"(Previous clause), 不料 + (unexpected event)","k":"(앞 문장), 不料 + (예상 밖의 일)"},"ex":{"j":"「不料」は文頭・節頭に置き、直前の状況から予想できない意外な結果が起きたことを示す書き言葉的な接続詞。「沒想到」と意味は近いが、「不料」の方がやや硬い書き言葉。","e":"\"不料\" sits at the start of a clause to signal that something unexpected happened, contrary to what the earlier situation would suggest. It's close in meaning to \"沒想到\" but reads as more formal/written.","k":"\"不料\"는 절 앞에 놓여 앞 상황에서 예상할 수 없었던 뜻밖의 결과가 일어났음을 나타내는 다소 문어적인 접속사다. \"沒想到\"와 뜻이 비슷하지만 \"不料\"가 더 격식체에 가깝다."},"eg":[{"z":"他們已經提早半小時出門，<em>不料</em>路上塞車，結果還是遲到了。","py":"Tāmen yǐjīng tízǎo bàn xiǎoshí chūmén, búliào lùshàng sāichē, jiéguǒ háishì chídào le.","j":"彼らは30分早く家を出たのに、思いがけず道が渋滞していて、結局遅刻してしまった。","e":"They had already left half an hour early, but unexpectedly there was a traffic jam, and they still ended up being late.","k":"그들은 이미 30분 일찍 집을 나섰지만, 뜻밖에도 길이 막혀서 결국 지각하고 말았다."},{"z":"他本來想搭捷運上班，<em>不料</em>捷運突然停駛，害他遲到了。","py":"Tā běnlái xiǎng dā jiéyùn shàngbān, búliào jiéyùn túrán tíngshǐ, hài tā chídào le.","j":"彼はもともと捷運(MRT)で通勤するつもりだったが、思いがけずMRTが突然運行を停止し、遅刻することになった。","e":"He originally planned to take the MRT to work, but unexpectedly the MRT suddenly stopped running, making him late.","k":"그는 원래 MRT를 타고 출근하려 했지만, 뜻밖에도 MRT가 갑자기 운행을 멈춰서 지각하고 말았다."}]},
{"id":"g5-439","cat":"特殊構文","t":"誰叫......","g":{"j":"「誰叫〜」で「自業自得だ/〜のせいだ」と責める気持ちを表す","e":"\"誰叫...\" expresses blame — \"it's your own fault for...\" / \"well, who told you to...\"","k":"\"誰叫〜\"로 \"누가 그러래/네 탓이다\"라는 책망의 뉘앙스를 나타냄"},"p":{"j":"誰叫＋主語＋(不)＋動詞句，(結果は自業自得)","e":"誰叫 + Subject + (不) + Verb Phrase, (self-inflicted result follows)","k":"誰叫 + 주어 + (不) + 동사구, (자업자득의 결과)"},"ex":{"j":"「誰叫」は文字通り「誰が〜させたのか」という疑問ではなく、「自分でそうしたのだから当然だ」と相手を責める・皮肉る口語表現。後半にはその結果としての悪い状況が続く。","e":"\"誰叫\" doesn't literally ask \"who made you...\" — it's a colloquial way of blaming someone, meaning \"well, that's what you get for...\". A negative consequence follows in the second clause.","k":"\"誰叫\"는 문자 그대로 \"누가 시켰냐\"는 질문이 아니라, \"네가 그렇게 했으니 당연하다\"며 상대를 탓하는 구어체 표현이다. 뒤에는 그로 인한 나쁜 결과가 이어진다."},"eg":[{"z":"<em>誰叫你不早點來</em>，食物全都被吃光了。","py":"Shéi jiào nǐ bù zǎodiǎn lái, shíwù quándōu bèi chīguāng le.","j":"早く来ないからだよ、食べ物はもう全部食べられちゃったんだから。","e":"Well, that's what you get for not coming earlier — all the food's been eaten up.","k":"네가 일찍 안 와서 그런 거야, 음식은 다 먹혀버렸잖아."},{"z":"<em>誰叫你不聽我的話</em>，現在後悔也沒用了。","py":"Shéi jiào nǐ bù tīng wǒ de huà, xiànzài hòuhuǐ yě méiyòng le.","j":"私の言うことを聞かないからだよ、今さら後悔しても仕方ない。","e":"Well, that's what you get for not listening to me — it's no use regretting it now.","k":"내 말을 안 들어서 그런 거야, 이제 와서 후회해도 소용없어."}]},
{"id":"g5-440","cat":"特殊構文","t":"有什麼好V（O）/SV的","g":{"j":"「有什麼好〜的」で「〜する必要がない/〜するほどのことではない」と反語的に否定する","e":"\"有什麼好V(O)/SV的\" rhetorically dismisses something as \"not worth ~ing\" / \"nothing to ~ about\"","k":"\"有什麼好〜的\"로 \"〜할 필요 없다/〜할 만한 게 아니다\"라는 반어적 부정을 나타냄"},"p":{"j":"(主語)＋還有什麼好＋動詞(＋目的語)／形容詞＋的","e":"(Subject) + 有什麼好 + Verb (+ Object) / Adjective + 的","k":"(주어) + 有什麼好 + 동사(+목적어)/형용사 + 的"},"ex":{"j":"これは反語文で、表面上は疑問文の形をしているが実際は「〜する必要はまったくない」という強い否定を表す。「有什麼好」の後には動詞(＋目的語)か形容詞が来て、最後は必ず「的」で終わる。","e":"This is a rhetorical question — grammatically a question, but it actually means a strong \"there's no need to ~ at all.\" A verb (+object) or adjective follows \"有什麼好,\" and the sentence always ends in 的.","k":"이것은 반어문으로, 형식은 의문문이지만 실제로는 \"전혀 〜할 필요가 없다\"는 강한 부정을 나타낸다. \"有什麼好\" 뒤에는 동사(+목적어)나 형용사가 오고 문장은 항상 \"的\"로 끝난다."},"eg":[{"z":"結果都已經確定了，<em>還有什麼好討論的</em>！","py":"Jiéguǒ dōu yǐjīng quèdìng le, hái yǒu shénme hǎo tǎolùn de!","j":"結果はもう決まっているのに、今さら議論する必要なんてないよ!","e":"The result is already decided — what's there left to discuss!","k":"결과는 이미 정해졌는데, 이제 와서 뭘 토론할 게 있어!"},{"z":"東西都準備好了，<em>還有什麼好擔心的</em>？","py":"Dōngxī dōu zhǔnbèi hǎo le, hái yǒu shénme hǎo dānxīn de?","j":"物はもう全部準備できているのに、何を心配することがあるの?","e":"Everything's already prepared — what is there to worry about?","k":"물건은 이미 다 준비됐는데, 뭘 걱정할 게 있어?"}]},
{"id":"g5-441","cat":"副詞","t":"畢竟","g":{"j":"結局は、やはり(根本的な理由を示す)","e":"after all","k":"결국, 어쨌든"},"p":{"j":"A ＋畢竟＋ B(強調根本原因/事實)","e":"A + 畢竟 + B (states the underlying reason/fact)","k":"A ＋畢竟＋ B(근본적인 이유나 사실을 강조)"},"ex":{"j":"「畢竟」は物事の背後にある不変の根本的な理由や事実を指摘し、「どうであれ、この事実は考慮すべきだ」という譲歩的なニュアンスを持つ。後半は多くの場合、そこから導かれる妥当な結論になる。疑問文で使う「究竟」(いったい)とは混同しないこと。","e":"\"Bìjìng\" points out an unchanging underlying fact or reason, often with a concessive nuance (\"no matter what, this fact must be considered\"), followed by a reasonable conclusion drawn from it. Don't confuse it with \"jiūjìng\" (used in questions, meaning \"actually/in the end\").","k":"\"畢竟\"는 어떤 일 이면의 변하지 않는 근본적인 이유나 사실을 짚어내며, \"아무리 그래도 이 사실은 고려해야 한다\"는 양보의 뉘앙스를 띤다. 의문문에 쓰이는 \"究竟\"(도대체)과 혼동하지 말 것."},"eg":[{"z":"他<em>畢竟</em>是個孩子，喜歡玩是正常的。","py":"Tā bìjìng shì ge háizi, xǐhuān wán shì zhèngcháng de.","j":"彼はやはり子供なのだから、遊ぶのが好きなのは当たり前だ。","e":"After all, he's just a child, so it's normal that he likes to play.","k":"그는 어쨌든 아이니까, 노는 것을 좋아하는 건 당연하다."},{"z":"他<em>畢竟</em>年紀大了，爬山爬得比較慢。","py":"Tā bìjìng niánjì dà le, páshān pá de bǐjiào màn.","j":"彼はやはり年を取っているので、山登りの速度が比較的遅い。","e":"After all, he's getting older, so he climbs mountains more slowly.","k":"그는 어쨌든 나이가 들어서, 등산 속도가 비교적 느리다."}]},
{"id":"g5-442","cat":"副詞","t":"難免","g":{"j":"避けられない、どうしても〜になる","e":"inevitably, unavoidably","k":"피하기 어렵다, 어쩔 수 없이"},"p":{"j":"(即使)…，難免＋會/有…(不理想的結果無法避免)","e":"(Even if) ..., 難免 + will/have ... (an undesirable result is unavoidable)","k":"(即使)…，難免＋會/有… (바람직하지 않은 결과를 피할 수 없음)"},"ex":{"j":"「難免」は望ましくない結果が起こるのを避けられないという意味で、後ろに動詞句(常に會/有＋ネガティブな内容)を伴う。「不免」とほぼ同義だが、「難免」のほうが口語での使用頻度が高い。単独で述語にならず、必ず後ろに動作や状態が続く。","e":"\"Nánmiǎn\" means an undesirable outcome can't be avoided, usually followed by 會/有 + something negative. It's close to \"bùmiǎn\" but more commonly used in speech. It cannot stand alone as a predicate — a verb phrase must follow.","k":"\"難免\"는 바람직하지 않은 결과를 피할 수 없다는 뜻으로, 보통 뒤에 會/有 + 부정적 내용이 온다. \"不免\"과 비슷하지만 회화에서 더 자주 쓰인다. 단독으로 서술어가 될 수 없고 반드시 뒤에 동사구가 와야 한다."},"eg":[{"z":"即使是新車，<em>難免</em>也會有些小毛病。","py":"Jíshǐ shì xīn chē, nánmiǎn yě huì yǒu xiē xiǎo máobìng.","j":"新車であっても、多少の不具合があるのは避けられない。","e":"Even a new car will inevitably have some minor problems.","k":"새 차라도 어쩔 수 없이 사소한 결함이 좀 있기 마련이다."},{"z":"剛開始學開車，<em>難免</em>會緊張。","py":"Gāng kāishǐ xué kāichē, nánmiǎn huì jǐnzhāng.","j":"運転を習い始めたばかりのころは、緊張してしまうのも無理はない。","e":"When you've just started learning to drive, it's inevitable to feel nervous.","k":"운전을 막 배우기 시작했을 때는 어쩔 수 없이 긴장하게 된다."}]},
{"id":"g5-443","cat":"特殊構文","t":"別看","g":{"j":"〜のように見えても(実は違う)","e":"don't judge by appearances; despite how it seems","k":"겉보기와는 달리, ~해 보여도"},"p":{"j":"別看＋A(表面現象)，(其實/還是)＋B(實際情況)","e":"別看 + A (apparent situation), (but actually/still) + B (the real situation)","k":"別看＋A(겉모습)，(실제로는/그래도)＋B(실제 상황)"},"ex":{"j":"「別看」は文頭に置き、「表面上は〜に見えるが、実際/結果は違う」という対比を導く。後半には「其實」「還是」「卻」などがよく現れる。「雖然」が単なる事実の譲歩であるのに対し、「別看」は見た目・印象と実際とのギャップを強調する口語的表現。","e":"\"Biékàn\" opens a sentence to contrast appearance with reality (\"it may look like X, but actually/still Y\"), often followed by 其實/還是/卻. Unlike \"雖然\" (a plain concessive fact), \"別看\" specifically highlights a gap between appearance/impression and reality, and is more colloquial.","k":"\"別看\"는 문두에 놓여 \"겉보기엔 ~해도 실제로는/그래도 다르다\"는 대조를 이끌며, 뒤에 其實/還是/卻가 자주 온다. 단순한 사실 양보인 \"雖然\"과 달리, \"別看\"는 겉모습과 실제 사이의 차이를 강조하는 구어적 표현이다."},"eg":[{"z":"<em>別看</em>他工作忙碌，他還是會抽出時間去運動。","py":"Bié kàn tā gōngzuò mánglù, tā háishì huì chōuchū shíjiān qù yùndòng.","j":"彼は仕事が忙しそうに見えても、それでも運動する時間を作る。","e":"Don't be fooled by how busy he looks with work — he still makes time to exercise.","k":"그는 일이 바빠 보여도, 그래도 운동할 시간을 짜낸다."},{"z":"<em>別看</em>這家店小，生意好得很。","py":"Bié kàn zhè jiā diàn xiǎo, shēngyì hǎo de hěn.","j":"この店は小さく見えるけれど、商売はとても繁盛している。","e":"Don't be fooled by how small this shop looks — business is really booming.","k":"이 가게가 작아 보여도, 장사가 아주 잘 된다."}]},
{"id":"g5-444","cat":"特殊構文","t":"無所謂","g":{"j":"どうでもいい、区別/関係がない","e":"it doesn't matter; makes no difference","k":"상관없다, 개의치 않다"},"p":{"j":"A ＋無所謂＋ B(對A而言，B這種區別/在意不存在)","e":"A + 無所謂 + B (for A, the distinction/concern of B doesn't exist)","k":"A ＋無所謂＋ B (A에게 B라는 구별/개의함이 존재하지 않음)"},"ex":{"j":"「無所謂」は「〜とは関係ない/どうでもいい」という意味で、名詞句や對/跟…(來說)を伴い、区別や重要性がないことを表す。単独で「都可以、沒關係」という返答としても使われる口語表現。謝罪への応答が中心の「沒關係」と違い、「無所謂」はより広く「気にしない、こだわらない」態度を表す。","e":"\"Wúsuǒwèi\" means \"it doesn't matter / makes no difference,\" often followed by a noun phrase or 對/跟…(來說), indicating no real distinction or importance. As a standalone reply it means \"either is fine, I don't mind.\" Unlike \"沒關係\" (mainly a response to an apology), \"無所謂\" more broadly expresses an attitude of not caring.","k":"\"無所謂\"는 \"상관없다/개의치 않다\"는 뜻으로 명사구나 對/跟…(來說)와 함께 쓰여 구별이나 중요성이 없음을 나타낸다. 단독 대답으로 \"아무거나 상관없다\"는 뜻도 된다. 사과에 대한 응답 중심인 \"沒關係\"와 달리, \"無所謂\"는 더 넓게 신경 쓰지 않는 태도를 나타낸다."},"eg":[{"z":"這個問題的答案<em>無所謂</em>對或錯，只是每個人看法不同而已。","py":"Zhège wèntí de dá'àn wúsuǒwèi duì huò cuò, zhǐshì měi ge rén kànfǎ bùtóng éryǐ.","j":"この問題の答えには正しいも間違いもなく、ただ人によって見方が違うだけだ。","e":"There's no right or wrong answer to this question — everyone just sees it differently.","k":"이 문제의 답에는 옳고 그름이 없고, 그저 사람마다 견해가 다를 뿐이다."},{"z":"去哪裡吃飯我<em>無所謂</em>，你決定就好。","py":"Qù nǎlǐ chīfàn wǒ wúsuǒwèi, nǐ juédìng jiù hǎo.","j":"どこでご飯を食べるかは私はどうでもいいので、あなたが決めてください。","e":"I don't mind where we eat — you decide.","k":"어디서 밥을 먹든 나는 상관없으니 네가 정해."}]},
{"id":"g5-445","cat":"副詞","t":"動不動就","g":{"j":"すぐ〜する、ちょっとしたことで〜する","e":"at the drop of a hat; tends to easily (do something undesirable)","k":"툭하면, 걸핏하면"},"p":{"j":"(A)＋動不動就＋B(容易且頻繁地做出B，常帶負面語氣)","e":"(A) + 動不動就 + B (easily and frequently does B, usually negative)","k":"(A)＋動不動就＋B (쉽게 자주 B를 함, 대개 부정적 어감)"},"ex":{"j":"「動不動就」はある行動や状態が些細なきっかけで頻繁に起こることを表し、話し手の不満や驚きのニュアンスを伴うことが多い。後ろには動詞句が続き(名詞は不可)、似た「常常」は単に頻度を述べるだけで否定的含意はないが、「動不動就」は「ちょっとしたことですぐ〜する」という批判的なニュアンスが強い。","e":"\"Dòngbúdòng jiù\" describes an action or state that happens frequently over trivial triggers, usually carrying the speaker's complaint or surprise, and must be followed by a verb phrase (not a noun). Unlike \"常常\" (just states frequency, neutral), \"動不動就\" carries a critical, \"over the slightest thing\" nuance.","k":"\"動不動就\"는 사소한 계기로 어떤 행동이나 상태가 자주 발생함을 나타내며, 화자의 불만이나 놀라움의 뉘앙스를 동반한다. 뒤에는 반드시 동사구가 와야 하며(명사는 불가), 단순히 빈도만 말하는 \"常常\"과 달리 \"動不動就\"는 \"걸핏하면\"이라는 비판적 어감이 강하다."},"eg":[{"z":"他最近的情緒很不穩定，<em>動不動就</em>哭。","py":"Tā zuìjìn de qíngxù hěn bù wěndìng, dòngbúdòng jiù kū.","j":"彼は最近情緒が不安定で、ちょっとしたことですぐ泣く。","e":"He's been emotionally unstable lately — he cries at the drop of a hat.","k":"그는 요즘 감정이 매우 불안정해서, 툭하면 운다."},{"z":"這台電腦<em>動不動就</em>當機，讓人很困擾。","py":"Zhè tái diànnǎo dòngbúdòng jiù dāngjī, ràng rén hěn kùnrǎo.","j":"このパソコンはすぐフリーズしてしまい、とても困っている。","e":"This computer keeps crashing at the slightest thing, which is really annoying.","k":"이 컴퓨터는 걸핏하면 다운돼서 정말 골치 아프다."}]},
{"id":"g5-446","cat":"副詞","t":"明明","g":{"j":"〜のに(事実と矛盾する不満)","e":"clearly...(yet); expressing contradiction","k":"분명히 ~한데도(모순·불만)"},"p":{"j":"明明 ＋ 事實，卻/還 ＋ 矛盾する行動","e":"Míngmíng + fact, (què/hái) + contradictory action","k":"明明 + 사실, (卻/還) + 모순된 행동"},"ex":{"j":"「明明」は話し手が確認済みの事実を強調し、後半にそれと矛盾する現象や不満を続ける。「卻」「還」と共起しやすい。単なる「其實」と違い、必ず対比・不満のニュアンスを含む点に注意。","e":"\"Míngmíng\" emphasizes a fact the speaker is certain of, followed by a contrasting or contradictory result, often paired with \"卻/還\". Unlike neutral \"其實\", it always carries a tone of complaint or surprise.","k":"\"明明\"은 화자가 확신하는 사실을 강조한 뒤 그와 모순되는 결과를 이어서 말할 때 쓰며 \"卻/還\"와 자주 함께 쓰인다. 단순한 사실 서술인 \"其實\"와 달리 항상 불만·놀람의 뉘앙스를 담는다."},"eg":[{"z":"這裡<em>明明</em>寫著禁止帶寵物，你怎麼還把小狗帶進來了呢。","py":"Zhè lǐ míngmíng xiězhe jìnzhǐ dài chǒngwù, nǐ zěnme hái bǎ xiǎogǒu dài jìnlái le ne.","j":"ここに「ペット持ち込み禁止」とはっきり書いてあるのに、どうして子犬を連れて入って来たんですか。","e":"It clearly says here that pets are prohibited, so why did you bring the puppy in?","k":"여기에는 분명히 반려동물 출입 금지라고 쓰여 있는데, 왜 강아지를 데리고 들어온 거예요?"},{"z":"他<em>明明</em>知道我在忙，還一直打電話給我。","py":"Tā míngmíng zhīdào wǒ zài máng, hái yìzhí dǎ diànhuà gěi wǒ.","j":"私が忙しいのを知っているくせに、彼はずっと電話をかけてくる。","e":"He clearly knows I'm busy, but he keeps calling me.","k":"그는 내가 바쁜 걸 분명히 알면서도 계속 전화를 건다."}]},
{"id":"g5-447","cat":"副詞","t":"好在","g":{"j":"幸いにも・助かったことに","e":"fortunately, luckily","k":"다행히"},"p":{"j":"好在 ＋ 幸運な事情，文","e":"Hǎozài + fortunate circumstance, clause","k":"好在 + 다행스러운 상황, 문장"},"ex":{"j":"「好在」は文頭または主語の前に置き、悪い結果を免れた幸運な条件を述べる。後には「不然」「否則」で悪い結果を仮定することが多い。「幸虧」とほぼ同義だが「好在」の方が口語的。","e":"\"Hǎozài\" appears at the start of a clause to state a fortunate condition that averted a bad outcome, often followed by \"不然/否則\" for the hypothetical negative result. It's nearly synonymous with \"幸虧\" but more colloquial.","k":"\"好在\"는 문두에 놓여 나쁜 결과를 피하게 한 다행스러운 조건을 말하며, 뒤에 \"不然/否則\"로 가정된 나쁜 결과를 덧붙이는 경우가 많다. \"幸虧\"와 거의 같은 뜻이지만 더 구어적이다."},"eg":[{"z":"<em>好在</em>這次還不是正式演出，大家可以再重新練習一遍。","py":"Hǎozài zhè cì hái bú shì zhèngshì yǎnchū, dàjiā kěyǐ zài chóngxīn liànxí yí biàn.","j":"幸い今回はまだ本番の公演ではないので、みんなもう一度練習し直せる。","e":"Fortunately, this isn't the official performance yet, so everyone can practice once more.","k":"다행히 이번은 아직 정식 공연이 아니라서, 다들 다시 한 번 더 연습할 수 있다."},{"z":"<em>好在</em>我有帶雨傘，不然一定會被淋濕。","py":"Hǎozài wǒ yǒu dài yǔsǎn, bùrán yídìng huì bèi línshī.","j":"幸い傘を持っていたので、そうでなければずぶ濡れになっていただろう。","e":"Luckily I brought an umbrella, otherwise I would have gotten soaked.","k":"다행히 우산을 가지고 있어서 그렇지 않았으면 흠뻑 젖었을 것이다."}]},
{"id":"g5-448","cat":"特殊構文","t":"所+V+的（N）","g":{"j":"「〜するところの(もの)」動作の対象を名詞化する","e":"nominalizes the object of a verb: \"what (subject) V-s\"","k":"동작의 대상을 명사화 \"~한/~하는 것\""},"p":{"j":"N1 ＋ 所 ＋ V ＋ 的 (＋ N2)","e":"N1 + suǒ + V + de (+ N2)","k":"N1 + 所 + V + 的 (+ N2)"},"ex":{"j":"「所」は書きことば的で、動詞と「的」の間に置いて動作の受け手(目的語)を名詞化する。「所」を省いても文法的には成立するが、書面語ではより硬い印象を与える。「N1 V 的 N2」との違いは「所」があると文語的・客観的な響きになる点。","e":"\"Suǒ\" is a written-style marker placed before the verb (with \"的\" after) to nominalize the object of the action. Omitting \"所\" is still grammatical but sounds more colloquial; adding it gives a more formal, written register.","k":"\"所\"는 문어체 표현으로 동사 앞에 놓여 \"的\"와 함께 동작의 대상(목적어)을 명사화한다. \"所\"를 생략해도 문법적으로 맞지만 더 구어적으로 들리며, \"所\"를 쓰면 더 격식 있고 객관적인 느낌을 준다."},"eg":[{"z":"一般來說 ，語言學家<em>所關注的</em>是語言規則的問題。","py":"Yìbān lái shuō, yǔyán xuéjiā suǒ guānzhù de shì yǔyán guīzé de wèntí.","j":"一般的に言えば、言語学者が注目しているのは言語規則の問題である。","e":"Generally speaking, what linguists focus on is the issue of language rules.","k":"일반적으로 말하면, 언어학자들이 주목하는 것은 언어 규칙의 문제이다."},{"z":"這家店<em>所賣的</em>都是台灣本地生產的水果。","py":"Zhè jiā diàn suǒ mài de dōu shì Táiwān běndì shēngchǎn de shuǐguǒ.","j":"この店が売っているのはすべて台灣現地産の果物だ。","e":"What this shop sells is all fruit produced locally in Taiwan.","k":"이 가게가 파는 것은 모두 대만 현지에서 생산된 과일이다."}]},
{"id":"g5-449","cat":"副詞","t":"無論如何","g":{"j":"何としても・どんなことがあっても","e":"no matter what, in any case","k":"어떻게든, 무슨 일이 있어도"},"p":{"j":"無論如何，主語＋都＋V","e":"Wúlùn rúhé, subject + dōu + V","k":"無論如何, 주어 + 都 + V"},"ex":{"j":"「無論如何」は文頭に置き、あらゆる条件を排除して結論が変わらないことを強調する決まり文句。後の節には必ず「都」を伴うのが典型。「無論＋疑問詞」より固定化されており分解できない。","e":"\"Wúlùn rúhé\" is a fixed phrase placed at the start of a sentence to stress that the conclusion holds regardless of any condition, typically followed by \"都\" in the next clause. Unlike \"無論 + question word\" patterns, it's a fixed idiom that can't be broken apart.","k":"\"無論如何\"는 문두에 놓여 어떤 조건이든 결론이 바뀌지 않음을 강조하는 고정 표현으로, 뒤 절에 보통 \"都\"가 온다. \"無論+의문사\" 패턴과 달리 분해할 수 없는 굳어진 관용구다."},"eg":[{"z":"這場會議很重要，<em>無論如何</em>你都要參加。","py":"Zhè chǎng huìyì hěn zhòngyào, wúlùn rúhé nǐ dōu yào cānjiā.","j":"この会議はとても重要なので、何としてもあなたは参加しなければならない。","e":"This meeting is very important, so no matter what, you must attend.","k":"이 회의는 매우 중요하니, 어떻게든 당신은 참석해야 한다."},{"z":"<em>無論如何</em>，我都會準時到機場接你。","py":"Wúlùn rúhé, wǒ dōu huì zhǔnshí dào jīchǎng jiē nǐ.","j":"何があっても、私は必ず時間通りに空港まで迎えに行きます。","e":"No matter what, I will get to the airport on time to pick you up.","k":"어떤 일이 있어도, 저는 반드시 제시간에 공항으로 마중 나가겠습니다."}]},
{"id":"g5-450","cat":"副詞","t":"一般而言","g":{"j":"一般的に言うと(概括的な傾向)","e":"generally speaking (stating a general tendency)","k":"일반적으로 말하면"},"p":{"j":"一般而言，文","e":"Yìbān éryán, clause","k":"一般而言, 문장"},"ex":{"j":"「一般而言」は文頭に置き、例外を除いた大まかな傾向・原則を述べる書きことば的表現。「一般來說」とほぼ同義で入れ替え可能だが、「一般而言」の方がやや正式でレポートや論説文に多い。","e":"\"Yìbān éryán\" opens a sentence to state a general tendency or principle, allowing for exceptions; it's a more formal, written-style synonym of \"一般來說\", common in reports and essays.","k":"\"一般而言\"는 문두에 놓여 예외를 인정하면서 대체적인 경향이나 원칙을 말하는 문어체 표현으로, \"一般來說\"와 거의 같은 뜻이지만 더 격식 있어 보고서나 논설문에 자주 쓰인다."},"eg":[{"z":"<em>一般而言</em>，薪水越高，越容易吸引到人才。","py":"Yìbān éryán, xīnshuǐ yuè gāo, yuè róngyì xīyǐn dào réncái.","j":"一般的に言えば、給料が高いほど人材を引き寄せやすい。","e":"Generally speaking, the higher the salary, the easier it is to attract talent.","k":"일반적으로 말하면, 급여가 높을수록 인재를 끌어들이기 쉽다."},{"z":"<em>一般而言</em>，台灣的冬天不會下雪。","py":"Yìbān éryán, Táiwān de dōngtiān bú huì xià xuě.","j":"一般的に言って、台灣の冬は雪が降らない。","e":"Generally speaking, it doesn't snow in winter in Taiwan.","k":"일반적으로 말하면, 대만의 겨울에는 눈이 내리지 않는다."}]},
{"id":"g5-451","cat":"副詞","t":"這下子","g":{"j":"これで、この結果","e":"now, as a result of this","k":"이제야, 이렇게 되어"},"p":{"j":"(原因の文)，這下子，(結果の文)","e":"(cause clause), 這下子, (resulting clause)","k":"(원인 문장)，這下子，(결과 문장)"},"ex":{"j":"「這下子」は状況の変化を受けて「これでようやく〜」という結果・成り行きを表す口語表現。原因を述べる文の後に置き、話し言葉でよく使われる。","e":"\"這下子\" marks a resulting change in situation, meaning \"now/this time (as a result)\". It's colloquial and placed after the cause clause to introduce the consequence.","k":"「這下子」는 앞선 상황의 결과로 「이제야, 이렇게 되어」라는 의미를 나타내는 구어체 표현이다. 원인을 말한 뒤 결과를 이어서 말할 때 쓴다."},"eg":[{"z":"他找到了一份不錯的工作，<em>這下子</em>，總算可以把貸款還完了。","py":"Tā zhǎodào le yí fèn búcuò de gōngzuò, zhèxiàzi, zǒngsuàn kěyǐ bǎ dàikuǎn huán wán le.","j":"彼はいい仕事を見つけた。これでようやくローンを返し終えることができる。","e":"He found a good job — now he can finally finish paying off the loan.","k":"그는 괜찮은 일자리를 찾았다. 이제야 드디어 대출을 다 갚을 수 있게 되었다."},{"z":"他終於把護照找到了，<em>這下子</em>，我們總算可以準時出發了。","py":"Tā zhōngyú bǎ hùzhào zhǎodào le, zhèxiàzi, wǒmen zǒngsuàn kěyǐ zhǔnshí chūfā le.","j":"彼はやっとパスポートを見つけた。これで私たちはようやく予定通り出発できる。","e":"He finally found his passport — now we can finally leave on time.","k":"그가 드디어 여권을 찾았다. 이제야 우리는 제시간에 출발할 수 있게 되었다."}]},
{"id":"g5-452","cat":"副詞","t":"主要（的）是","g":{"j":"主に〜だ","e":"mainly, the main reason is","k":"주로 ~이다"},"p":{"j":"(主題) ＋ 主要（的）是 ＋ (最も重要な理由・内容)","e":"(topic) + 主要（的）是 + (the main reason/content)","k":"(주제) ＋ 主要（的）是 ＋ (가장 중요한 이유/내용)"},"ex":{"j":"「主要（的）是」は複数ある理由の中で最も重要な理由や要点を強調する表現。「的」は省略可能で意味は変わらない。話の要点を絞るときに使う。","e":"\"主要（的）是\" highlights the main reason or point among several possible ones, roughly \"mainly / the main thing is\". The 的 is optional and doesn't change the meaning.","k":"「主要（的）是」는 여러 이유 중 가장 중요한 것을 강조할 때 쓰는 표현으로 「주로 ~이다」라는 뜻이다. 的는 생략 가능하며 의미 차이가 없다."},"eg":[{"z":"今天請大家來開會，<em>主要是</em>想了解大家對這個問題的看法。","py":"Jīntiān qǐng dàjiā lái kāihuì, zhǔyào shì xiǎng liǎojiě dàjiā duì zhège wèntí de kànfǎ.","j":"今日皆さんに会議に来てもらったのは、主にこの問題についての皆さんの意見を知りたいからです。","e":"The main reason I invited everyone to this meeting today is that I want to understand everyone's views on this issue.","k":"오늘 여러분을 회의에 모신 것은 주로 이 문제에 대한 여러분의 의견을 알고 싶어서입니다."},{"z":"這家店賣的東西很多，但<em>主要是</em>賣咖啡跟甜點。","py":"Zhè jiā diàn mài de dōngxi hěn duō, dàn zhǔyào shì mài kāfēi gēn tiándiǎn.","j":"この店は色々な物を売っているが、主にコーヒーとデザートを売っている。","e":"This shop sells a lot of things, but mainly coffee and desserts.","k":"이 가게는 여러 가지를 팔지만 주로 커피와 디저트를 판다."}]},
{"id":"g5-453","cat":"副詞","t":"基本上","g":{"j":"基本的には、大体","e":"basically, in general","k":"기본적으로"},"p":{"j":"基本上，＋ (全体的な状況の説明)","e":"基本上, + (statement of the overall situation)","k":"基本上，＋ (전반적인 상황 설명)"},"ex":{"j":"「基本上」は全体的な状況や原則を述べる際に使う副詞で、「大部分はそうだが例外もありうる」というニュアンスを含む。文頭に置くことが多い。","e":"\"基本上\" means \"basically/in general,\" used to state an overall situation while implying minor exceptions may exist. It's usually placed at the start of a sentence.","k":"「基本上」는 「기본적으로, 대체로」라는 뜻으로 전반적인 상황이나 원칙을 말할 때 쓰며, 예외가 있을 수 있음을 암시한다. 보통 문장 맨 앞에 온다."},"eg":[{"z":"<em>基本上</em>，這些軟體都是免費的，如果想要有更多功能才需要付錢。","py":"Jīběnshàng, zhèxiē ruǎntǐ dōu shì miǎnfèi de, rúguǒ xiǎngyào yǒu gèngduō gōngnéng cái xūyào fùqián.","j":"基本的にこれらのソフトはすべて無料で、もっと多くの機能が欲しい場合だけお金を払う必要がある。","e":"Basically, these apps are all free; you only need to pay if you want more features.","k":"기본적으로 이 소프트웨어들은 모두 무료이며, 더 많은 기능을 원할 때만 돈을 낼 필요가 있다."},{"z":"<em>基本上</em>，這個計畫已經完成了，只剩下最後的檢查。","py":"Jīběnshàng, zhège jìhuà yǐjīng wánchéng le, zhǐ shèngxià zuìhòu de jiǎnchá.","j":"基本的にこの計画はもう完成していて、あとは最後の確認だけが残っている。","e":"Basically, this project is already finished; only the final check remains.","k":"기본적으로 이 계획은 이미 완성되었고 마지막 점검만 남아 있다."}]},
{"id":"g5-454","cat":"接続","t":"可見","g":{"j":"〜ことがわかる、それでわかるように","e":"it can be seen that, this shows","k":"~을 알 수 있다"},"p":{"j":"(事実・現象)，可見 ＋ (そこから導かれる結論)","e":"(fact/phenomenon), 可見 + (conclusion drawn from it)","k":"(사실/현상)，可見 ＋ (거기서 도출된 결론)"},"ex":{"j":"「可見」は前述の事実や現象から論理的に導かれる結論を示す接続詞で、「〜から見て、〜ことがわかる」という意味。話し言葉の「看起來」より書き言葉的でフォーマル。","e":"\"可見\" introduces a logical conclusion drawn from a preceding fact, meaning \"this shows / it can be seen that\". It's more formal and written than colloquial equivalents like \"看起來\".","k":"「可見」는 앞서 말한 사실이나 현상으로부터 논리적으로 이끌어낸 결론을 나타내는 접속 표현으로 「~을 알 수 있다」라는 뜻이며, 구어체 「看起來」보다 문어체에 가깝다."},"eg":[{"z":"這本雜誌一個月可以賣出五萬多本，<em>可見</em>很受市場歡迎。","py":"Zhè běn zázhì yí gè yuè kěyǐ màichū wǔwàn duō běn, kějiàn hěn shòu shìchǎng huānyíng.","j":"この雑誌は一か月で五万部以上売れる。これは市場でとても人気があることがわかる。","e":"This magazine sells over fifty thousand copies a month, which shows it's very popular in the market.","k":"이 잡지는 한 달에 오만 부 넘게 팔린다. 이는 시장에서 매우 인기가 있다는 것을 보여준다."},{"z":"他每天都認真練習，<em>可見</em>他真的很想進步。","py":"Tā měitiān dōu rènzhēn liànxí, kějiàn tā zhēn de hěn xiǎng jìnbù.","j":"彼は毎日真剣に練習している。これは彼が本当に上達したいと思っていることがわかる。","e":"He practices seriously every day, which shows he really wants to improve.","k":"그는 매일 열심히 연습한다. 이는 그가 정말로 실력을 늘리고 싶어 한다는 것을 보여준다."}]},
{"id":"g5-455","cat":"接続","t":"（可是）話說回來","g":{"j":"話を戻すと、とはいえ","e":"but then again, having said that","k":"그런데 다시 말하자면"},"p":{"j":"(前の内容)，（可是）話說回來，＋ (視点を戻した内容)","e":"(previous statement), （可是）話說回來, + (a return to another perspective)","k":"(앞의 내용)，（可是）話說回來，＋ (관점을 되돌린 내용)"},"ex":{"j":"「話說回來」は前の話から少し視点を戻して、別の側面や補足を述べる転換の表現。「可是」を前に付けると逆接のニュアンスが強まる。「不過」より話し言葉的。","e":"\"話說回來\" shifts back to another angle after a preceding statement, similar to \"but then again / having said that\". Adding \"可是\" before it strengthens the contrastive nuance. It's more colloquial than \"不過\".","k":"「話說回來」는 앞의 이야기에서 관점을 다시 돌려 다른 측면이나 보충 설명을 말할 때 쓰는 전환 표현이다. 앞에 「可是」를 붙이면 역접의 뉘앙스가 강해지며, 「不過」보다 구어체적이다."},"eg":[{"z":"人與人相處的確是一件困難的事情，<em>可是話說回來</em>，只要真誠就可以交到好朋友。","py":"Rén yǔ rén xiāngchǔ díquè shì yí jiàn kùnnán de shìqíng, kěshì huàshuōhuílái, zhǐyào zhēnchéng jiù kěyǐ jiāo dào hǎo péngyǒu.","j":"人と人との付き合いは確かに難しいことだ。でも話を戻すと、誠実でありさえすればいい友達を作ることができる。","e":"Getting along with people is indeed difficult. But then again, as long as you're sincere, you can make good friends.","k":"사람과 사람이 어울리는 것은 확실히 어려운 일이다. 하지만 다시 말하자면, 진실하기만 하면 좋은 친구를 사귈 수 있다."},{"z":"這次考試考得不太理想，<em>可是話說回來</em>，至少我學到了怎麼安排時間。","py":"Zhè cì kǎoshì kǎo de bú tài lǐxiǎng, kěshì huàshuōhuílái, zhìshǎo wǒ xuédào le zěnme ānpái shíjiān.","j":"今回の試験の結果はあまり理想的ではなかった。でも話を戻すと、少なくとも時間の使い方を学ぶことができた。","e":"This exam didn't go very well. But then again, at least I learned how to manage my time.","k":"이번 시험은 그다지 만족스럽지 않았다. 하지만 다시 말하자면, 적어도 시간을 어떻게 관리하는지 배웠다."}]},
{"id":"g5-456","cat":"接続","t":"反之","g":{"j":"それとは反対に","e":"on the contrary; conversely","k":"그와 반대로"},"p":{"j":"句子A，反之，句子B(BはAと反対の内容)","e":"Clause A, fǎnzhī, Clause B (B states the opposite of A)","k":"문장A，反之，문장B(B는 A와 반대되는 내용)"},"ex":{"j":"「反之」は前の内容と正反対の事柄を導く書き言葉の接続詞で、必ず句頭に置きコンマで区切る。似た「相反地」より硬い言い方で、口語では「相反地」「不然」の方がよく使われる。","e":"\"Fǎnzhī\" introduces a statement opposite to what precedes it; it's a formal written connector placed at the start of a clause, followed by a comma. It's more formal than \"相反地,\" which is more common in speech.","k":"反之는 앞 내용과 반대되는 내용을 이끄는 문어체 접속사로, 문두에 쓰고 쉼표를 붙인다. 相反地보다 더 격식체이며, 구어에서는 相反地나 不然을 더 자주 쓴다."},"eg":[{"z":"睡前過度運動容易睡不好，<em>反之</em>，聽點音樂可以幫助睡眠","py":"Shuìqián guòdù yùndòng róngyì shuìbùhǎo, fǎnzhī, tīng diǎn yīnyuè kěyǐ bāngzhù shuìmián.","j":"寝る前に激しい運動をすると眠りにくくなる。逆に、音楽を少し聴くと睡眠を助けてくれる。","e":"Exercising too intensely before bed makes it hard to sleep; conversely, listening to some music can help you sleep.","k":"자기 전에 과도한 운동을 하면 잠들기 어렵다. 반대로, 음악을 좀 들으면 수면에 도움이 된다."},{"z":"天氣好的時候大家都想出門走走，<em>反之</em>，下雨天大家比較想待在家裡。","py":"Tiānqì hǎo de shíhòu dàjiā dōu xiǎng chūmén zǒuzou, fǎnzhī, xiàyǔtiān dàjiā bǐjiào xiǎng dāi zài jiālǐ.","j":"天気がいい時はみんな出かけたがるが、逆に、雨の日はみんな家にいたがる。","e":"When the weather is nice, everyone wants to go out; conversely, on rainy days people would rather stay home.","k":"날씨가 좋을 때는 다들 나가고 싶어 하지만, 반대로, 비 오는 날에는 다들 집에 있고 싶어 한다."}]},
{"id":"g5-457","cat":"接続","t":"換句話說","g":{"j":"言い換えれば","e":"in other words","k":"다시 말해서"},"p":{"j":"句子A，換句話說，句子B(BはAの言い換え)","e":"Statement A, huàn jù huà shuō, Statement B (B rephrases A)","k":"문장A，換句話說，문장B(B는 A를 바꿔 말한 것)"},"ex":{"j":"前の内容を分かりやすい言葉で言い直すときに使う書き言葉の接続詞。「也就是說」と似ているが、「換句話說」は表現を変えて説明し直すニュアンスが強く、「也就是說」は結論をまとめる意味合いが強い。","e":"Used to restate the preceding idea in different, clearer words; it's a formal connector. Similar to \"也就是說,\" but \"換句話說\" emphasizes rephrasing while \"也就是說\" emphasizes drawing a conclusion.","k":"앞 내용을 다른 말로 쉽게 풀어 말할 때 쓰는 문어체 접속사이다. 也就是說와 비슷하지만 換句話說는 표현을 바꿔 다시 설명하는 뉘앙스가 강하다."},"eg":[{"z":"出生率降低了，<em>換句話說</em>，就是孩子越來越少了。","py":"Chūshēnglǜ jiàngdī le, huànjùhuàshuō, jiùshì háizi yuèláiyuè shǎo le.","j":"出生率が下がった。言い換えれば、子どもがどんどん少なくなっているということだ。","e":"The birth rate has dropped; in other words, there are fewer and fewer children.","k":"출산율이 낮아졌다. 다시 말해서, 아이가 점점 줄어들고 있다는 것이다."},{"z":"他每天都加班到很晚，<em>換句話說</em>，他幾乎沒有自己的時間。","py":"Tā měitiān dōu jiābān dào hěn wǎn, huànjùhuàshuō, tā jīhū méiyǒu zìjǐ de shíjiān.","j":"彼は毎日遅くまで残業している。言い換えれば、彼にはほとんど自分の時間がないということだ。","e":"He works overtime until very late every day; in other words, he has almost no time of his own.","k":"그는 매일 늦게까지 야근한다. 다시 말해서, 그에게는 자신만의 시간이 거의 없다는 것이다."}]},
{"id":"g5-458","cat":"接続","t":"除此之外","g":{"j":"それ以外に、この他に","e":"besides this; in addition","k":"이 밖에도"},"p":{"j":"敘述A(和B)，除此之外，還/更＋C(追加内容)","e":"Statement A (and B), chúcǐzhīwài, additional point C","k":"서술A(와 B)，除此之外，추가 내용C"},"ex":{"j":"前に挙げた事柄に加えてさらに情報を追加するときに使う。「而且」より書き言葉的で、列挙した内容の最後にもう一点付け加える働きが強い。","e":"Adds one more point on top of what was already mentioned; more formal than \"而且,\" and typically used to add a final point after a list.","k":"앞서 언급한 내용에 한 가지를 더 추가할 때 쓰며, 而且보다 문어적이고 나열한 내용 뒤에 마지막으로 덧붙일 때 자주 쓰인다."},"eg":[{"z":"他不但是個成功的企業家，也是個學者，<em>除此之外</em>，更是個好父親。","py":"Tā búdàn shì ge chénggōng de qìyèjiā, yě shì ge xuézhě, chúcǐzhīwài, gèng shì ge hǎo fùqīn.","j":"彼は成功した実業家であるだけでなく、学者でもある。それに加えて、良い父親でもある。","e":"He is not only a successful entrepreneur but also a scholar; besides that, he is a good father too.","k":"그는 성공한 기업가일 뿐만 아니라 학자이기도 하다. 게다가 좋은 아버지이기도 하다."},{"z":"這家餐廳的菜好吃又便宜，<em>除此之外</em>，服務態度也非常親切。","py":"Zhè jiā cāntīng de cài hǎochī yòu piányí, chúcǐzhīwài, fúwù tàidù yě fēicháng qīnqiè.","j":"このレストランは料理がおいしくて安い。それに加えて、サービスもとても親切だ。","e":"The food at this restaurant is delicious and cheap; on top of that, the service is also very friendly.","k":"이 식당은 음식이 맛있고 저렴하다. 게다가 서비스도 매우 친절하다."}]},
{"id":"g5-459","cat":"副詞","t":"相對地","g":{"j":"それに応じて、相対的に","e":"correspondingly; relatively","k":"상대적으로"},"p":{"j":"A(変化)，相對地，B也隨之變化","e":"A changes, xiāngduì de, B changes correspondingly","k":"A(변화)，相對地，B도 그에 따라 변화"},"ex":{"j":"前の変化に応じてもう一方も比例して変化することを表す副詞。「越來越」のような程度の強調ではなく、二つの事柄の連動関係を示す点がポイント。","e":"An adverb showing that one thing changes in proportion to a preceding change; unlike \"越來越\" (which emphasizes increasing degree), it highlights the correlation between two changes.","k":"앞의 변화에 따라 다른 쪽도 비례하여 변화함을 나타내는 부사이다. 정도를 강조하는 越來越와 달리 두 가지 사항의 연동 관계를 나타내는 점이 핵심이다."},"eg":[{"z":"公司的規模越來越大，<em>相對地</em>需要的空間也變大了。","py":"Gōngsī de guīmó yuèláiyuè dà, xiāngduìde xūyào de kōngjiān yě biàndà le.","j":"会社の規模がどんどん大きくなり、それに伴って必要なスペースも大きくなった。","e":"The company has grown larger and larger, and correspondingly, the space it needs has also increased.","k":"회사의 규모가 점점 커지면서 그에 따라 필요한 공간도 커졌다."},{"z":"收入增加了，<em>相對地</em>要繳的稅也變多了。","py":"Shōurù zēngjiā le, xiāngduìde yào jiǎo de shuì yě biànduō le.","j":"収入が増えると、それに応じて納める税金も多くなった。","e":"Income has increased, and correspondingly, the taxes owed have also increased.","k":"수입이 늘어나자, 그에 따라 내야 할 세금도 많아졌다."}]},
{"id":"g5-460","cat":"副詞","t":"事實上","g":{"j":"実際は、事実上","e":"in fact; actually","k":"사실상"},"p":{"j":"一般的な考え/表面的な說法，事實上，真實情況B","e":"Common belief/appearance, shìshí shàng, actual fact B","k":"일반적인 생각，事實上，실제 상황B"},"ex":{"j":"表面的な認識や一般論を否定し、実際の事実を述べるときに使う書き言葉の副詞。「其實」と意味は近いが、「事實上」の方がやや硬く、統計や客観的事実を伴う論説文でよく使われる。","e":"Used to state the actual fact, contrasting it with a common assumption or appearance; similar to \"其實\" but more formal, often used in essays with objective facts or data.","k":"표면적인 인식이나 일반론을 부정하고 실제 사실을 말할 때 쓰는 문어체 부사이다. 其實와 비슷하지만 더 격식적이며 객관적 사실이나 통계를 다룰 때 자주 쓰인다."},"eg":[{"z":"一般人認為運動一定可以減肥，<em>事實上</em>，飲食控制才是最重要的。","py":"Yìbānrén rènwéi yùndòng yídìng kěyǐ jiǎnféi, shìshíshàng, yǐnshí kòngzhì cái shì zuì zhòngyào de.","j":"一般の人は運動すれば必ず痩せられると思っているが、実際は食事管理こそが一番重要だ。","e":"Most people think exercise will definitely help you lose weight, but in fact, controlling your diet is the most important thing.","k":"일반 사람들은 운동을 하면 반드시 살을 뺄 수 있다고 생각하지만, 사실상 식단 조절이야말로 가장 중요하다."},{"z":"大家都以為他很有錢，<em>事實上</em>他每個月都在存錢過日子。","py":"Dàjiā dōu yǐwéi tā hěn yǒuqián, shìshíshàng tā měige yuè dōu zài cún qián guò rìzi.","j":"みんな彼はお金持ちだと思っているが、実際は彼は毎月コツコツ貯金しながら生活している。","e":"Everyone thinks he's rich, but in fact, he saves money every month just to get by.","k":"다들 그가 부자라고 생각하지만, 사실상 그는 매달 돈을 모으며 생활하고 있다."}]},
{"id":"g5-461","cat":"接続","t":"總之","g":{"j":"「要するに、とにかく」","e":"in short, anyway (to sum up)","k":"요컨대, 아무튼"},"p":{"j":"內容 ＋ 總之 ＋ 結論","e":"[content], 總之, [conclusion]","k":"내용 + 總之 + 결론"},"ex":{"j":"「總之」は話や状況をまとめて結論を導く言い方。前に述べた複雑な内容をひとまとめにする際に使う。「反正」(結局どうでもいい)との違いに注意:「總之」は要約・結論志向で、投げやりな意味はない。","e":"\"總之\" wraps up a complex situation into one conclusion, similar to \"in short/anyway.\" Don't confuse it with \"反正\" (whatever happens, dismissive) — 總之 leads to a summary, not indifference.","k":"\"總之\"는 앞의 복잡한 내용을 정리해 결론으로 이어주는 표현이다. \"어차피\"라는 뜻의 \"反正\"과 달리 무관심이 아니라 요약·결론을 나타낸다."},"eg":[{"z":"不管會碰到什麼困難、結果如何，<em>總之</em>，先踏出第一步再說。","py":"Bùguǎn huì pèngdào shénme kùnnán, jiéguǒ rúhé, zǒngzhī, xiān tàchū dì-yī-bù zài shuō.","j":"どんな困難にぶつかっても、結果がどうであれ、とにかく、まず第一歩を踏み出してから考えよう。","e":"No matter what difficulties you run into or how it turns out, anyway, just take the first step first.","k":"어떤 어려움에 부딪히든, 결과가 어떻든, 아무튼 일단 첫걸음을 내딛고 보자."},{"z":"不管你相不相信，<em>總之</em>，這件事是真的。","py":"Bùguǎn nǐ xiāng bù xiāngxìn, zǒngzhī, zhè jiàn shì shì zhēn de.","j":"あなたが信じようと信じまいと、とにかく、これは本当のことだ。","e":"Whether you believe it or not, anyway, this is true.","k":"네가 믿든 안 믿든, 아무튼 이건 사실이다."}]},
{"id":"g5-462","cat":"接続","t":"由此可知/看來/可見","g":{"j":"「これによって〜とわかる/見える」","e":"from this it can be known/seen that...","k":"이로써 ~을 알 수 있다"},"p":{"j":"根據 ＋ 由此可知/看來/可見 ＋ 結論","e":"[evidence], 由此可知/看來/可見, [inference]","k":"근거 + 由此可知/看來/可見 + 추론"},"ex":{"j":"前の内容を根拠として結論を導く表現。「可知」は知識的推論、「看來」はやや推測的、「可見」は証拠が明白な場合に使う。書き言葉的でビジネスや論説文によく登場する。","e":"Used to draw a logical conclusion from evidence just given (\"from this we can see/know that...\"). 可知 is more definite, 看來 more tentative, 可見 stresses visible proof. Common in written/formal Chinese.","k":"앞에서 제시한 근거로부터 결론을 이끌어낼 때 쓴다. \"可知\"는 확정적, \"看來\"는 다소 추측적, \"可見\"은 증거가 뚜렷할 때 쓰인다. 격식체·논설문에 자주 등장한다."},"eg":[{"z":"就算再忙，他還是會去當志工，<em>由此可知/看來/可見</em>，他是一個熱心的人。","py":"Jiùsuàn zài máng, tā háishì huì qù dāng zhìgōng, yóucǐkězhī/kànlái/kějiàn, tā shì yí ge rèxīn de rén.","j":"どんなに忙しくても、彼はやはりボランティアに行く。これによって、彼が親切な人だとわかる。","e":"Even when he's very busy, he still goes to volunteer — from this we can see that he's a warm-hearted person.","k":"아무리 바빠도 그는 여전히 자원봉사를 하러 간다. 이로써 그가 열정적인 사람이라는 것을 알 수 있다."},{"z":"他每天都提早到公司，<em>由此可知</em>，他是一個很認真的人。","py":"Tā měitiān dōu tízǎo dào gōngsī, yóucǐkězhī, tā shì yí ge hěn rènzhēn de rén.","j":"彼は毎日会社に早めに着く。これによって、彼がとても真面目な人だとわかる。","e":"He arrives at the office early every day — from this we can tell he's a very diligent person.","k":"그는 매일 회사에 일찍 도착한다. 이로써 그가 매우 성실한 사람이라는 것을 알 수 있다."}]},
{"id":"g5-463","cat":"接続","t":"總而言之","g":{"j":"「要するに、総じて言えば」","e":"all in all, in conclusion","k":"요컨대, 결론적으로 말하면"},"p":{"j":"說明 ＋ 總而言之 ＋ 總結","e":"[long explanation], 總而言之, [summary]","k":"설명 + 總而言之 + 총정리"},"ex":{"j":"「總而言之」は「總之」よりやや改まった言い方で、長い説明の締めくくりに使う。「簡言之」(要するに、簡潔に言うと)は内容を短くまとめる点を強調するのに対し、こちらは結論全体をまとめる。","e":"A more formal version of 總之, used to close a lengthy explanation (\"all in all/in conclusion\"). Unlike 簡言之, which stresses brevity, 總而言之 focuses on wrapping up everything said.","k":"\"總之\"보다 격식적인 표현으로 긴 설명을 마무리할 때 쓴다. 간결함을 강조하는 \"簡言之\"와 달리, 앞서 말한 모든 내용을 총정리하는 느낌이다."},"eg":[{"z":"今天說了那麼多，<em>總而言之</em>，就是要幫助各位增加財富管理的觀念。","py":"Jīntiān shuōle nàme duō, zǒng'éryánzhī, jiùshì yào bāngzhù gèwèi zēngjiā cáifù guǎnlǐ de guānniàn.","j":"今日はたくさん話したが、要するに、皆さんの財産管理の考え方を高めるためだ。","e":"I've said a lot today, but all in all, it's just to help everyone build up their concept of wealth management.","k":"오늘 많은 이야기를 했지만, 요컨대 여러분의 재무 관리 개념을 높이기 위한 것이다."},{"z":"這部電影有好笑的地方，也有感人的地方，<em>總而言之</em>，很值得一看。","py":"Zhè bù diànyǐng yǒu hǎoxiào de dìfāng, yě yǒu gǎnrén de dìfāng, zǒng'éryánzhī, hěn zhíde yí kàn.","j":"この映画には面白いところもあれば、感動的なところもある。要するに、見る価値が十分にある。","e":"This movie has funny parts and moving parts — all in all, it's well worth watching.","k":"이 영화는 재미있는 부분도 있고 감동적인 부분도 있다. 요컨대 볼 만한 가치가 충분하다."}]},
{"id":"g5-464","cat":"接続","t":"簡言之","g":{"j":"「簡単に言うと、要するに」","e":"in brief, simply put","k":"간단히 말하면"},"p":{"j":"詳細說明 ＋ 簡言之 ＋ 簡短結論","e":"[detailed explanation], 簡言之, [short conclusion]","k":"자세한 설명 + 簡言之 + 짧은 결론"},"ex":{"j":"複雑な説明を短くまとめて言い直すときに使う「要するに」。必ず前に詳しい説明があってから使う点に注意。前置きなしにいきなり文頭で使うのは誤り。","e":"Means \"in short/simply put\" — used to restate a detailed explanation in one short sentence. It must follow the detailed content; don't open with it before explaining anything.","k":"복잡한 설명을 짧게 정리해 다시 말할 때 쓰는 \"요컨대\"의 의미이다. 반드시 앞에 자세한 설명이 있어야 하며, 설명 없이 문두에 갑자기 쓰면 안 된다."},"eg":[{"z":"<em>簡言之</em>，心情好，抵抗力就強。","py":"Jiǎnyánzhī, xīnqíng hǎo, dǐkànglì jiù qiáng.","j":"簡単に言うと、気分が良ければ、抵抗力も強くなる。","e":"Simply put, when you're in a good mood, your immunity gets stronger.","k":"간단히 말하면, 기분이 좋으면 저항력도 강해진다."},{"z":"這個計畫有很多細節，<em>簡言之</em>，就是要提高效率。","py":"Zhège jìhuà yǒu hěnduō xìjié, jiǎnyánzhī, jiùshì yào tígāo xiàolǜ.","j":"この計画には多くの細かい点があるが、簡単に言うと、効率を上げるためのものだ。","e":"This plan has a lot of details, but simply put, it's meant to improve efficiency.","k":"이 계획에는 세부 사항이 많지만, 간단히 말하면 효율을 높이기 위한 것이다."}]},
{"id":"g5-465","cat":"接続","t":"如此一來","g":{"j":"「そうすれば、その結果」","e":"this way, as a result","k":"이렇게 하면, 그 결과"},"p":{"j":"前提行動/變化 ＋ 如此一來 ＋ 結果","e":"[action/change], 如此一來, [result]","k":"전제 행동/변화 + 如此一來 + 결과"},"ex":{"j":"前で述べた変化や行動を受けて「このようにすれば/その結果」と結果を述べる表現。「因此」(それゆえ)より、前の具体的な状況を指す「如此」(このように)を含む点が特徴。前に具体的な変化の描写が必要。","e":"Means \"this way/as a result,\" pointing back to a change or action just described and stating its consequence. Unlike the more neutral \"因此\" (therefore), it explicitly refers to \"this situation\" (如此), so it needs a concrete prior change to point to.","k":"앞서 언급한 변화나 행동을 받아 \"이렇게 하면/그 결과\"라는 결과를 나타낸다. \"因此\"(그러므로)와 달리 \"如此\"(이렇게)로 앞의 구체적 상황을 직접 가리키므로, 앞에 구체적인 변화 묘사가 필요하다."},"eg":[{"z":"現在經濟逐漸好轉，<em>如此一來</em>，工作機會就會增加。","py":"Xiànzài jīngjì zhújiàn hǎozhuǎn, rúcǐyìlái, gōngzuò jīhuì jiù huì zēngjiā.","j":"今、経済は徐々に好転している。そうすれば、就業の機会も増えるだろう。","e":"The economy is gradually improving now — as a result, job opportunities will increase.","k":"지금 경제가 점차 호전되고 있다. 이렇게 되면 일자리 기회도 늘어날 것이다."},{"z":"政府調降了油價，<em>如此一來</em>，交通成本就降低了。","py":"Zhèngfǔ tiáojiàng le yóujià, rúcǐyìlái, jiāotōng chéngběn jiù jiàngdī le.","j":"政府が石油価格を引き下げた。その結果、交通コストが下がった。","e":"The government lowered oil prices — as a result, transportation costs went down.","k":"정부가 유가를 인하했다. 그 결과 교통비가 낮아졌다."}]},
{"id":"g5-466","cat":"介詞","t":"從......的角度來+V","g":{"j":"〜の視点から〜する","e":"to do something from the perspective of...","k":"~의 관점에서 ~하다"},"p":{"j":"從＋NP＋的角度來＋V","e":"從＋NP＋的角度來＋V","k":"從＋NP＋的角度來＋V"},"ex":{"j":"「從」の後に立場や人を置き、「來」は後ろの動作へつなぐ働きをする。「從...方面來看」と混同しやすいが、「角度」は具体的な視点そのものを指す点が違う。","e":"Marks the standpoint an action is taken from, with \"來\" linking to the verb. Learners often drop \"的角度\" and just say \"從NP來V\", which sounds incomplete or unnatural.","k":"행동을 취하는 입장이나 관점을 나타내며 \"來\"가 뒤의 동사와 연결된다. \"從...方面\"과 혼동하기 쉽지만 \"角度\"는 구체적인 시각 자체를 가리킨다는 점이 다르다."},"eg":[{"z":"<em>從使用者的角度來設計</em>商品，不但實用也能增加購買的人數。","py":"Cóng shǐyòngzhě de jiǎodù lái shèjì shāngpǐn, búdàn shíyòng yě néng zēngjiā gòumǎi de rénshù.","j":"使用者の視点から商品を設計すれば、実用的なだけでなく購入者数も増やせる。","e":"Designing products from the user's perspective is not only practical but also increases the number of buyers.","k":"사용자의 관점에서 상품을 설계하면 실용적일 뿐만 아니라 구매자 수도 늘릴 수 있다."},{"z":"<em>從老師的角度來看</em>，這個問題並不難。","py":"Cóng lǎoshī de jiǎodù lái kàn, zhège wèntí bìng bù nán.","j":"先生の視点から見ると、この問題はそれほど難しくない。","e":"From the teacher's perspective, this problem isn't difficult at all.","k":"선생님의 관점에서 보면 이 문제는 전혀 어렵지 않다."}]},
{"id":"g5-467","cat":"接続","t":"至於","g":{"j":"〜については(話題転換)","e":"as for / as to (shifting to a new topic)","k":"~에 관해서는(화제 전환)"},"p":{"j":"句子，至於＋話題(＋子句)","e":"Clause, zhìyú + new/related topic (+ clause)","k":"문장，至於＋화제(＋절)"},"ex":{"j":"前の話題から関連する別の話題や未確定の事柄へ移すときに使う。「關於」は単に話題を導入するだけだが、「至於」は前文と対比しながら別の側面へ移る含みがある。","e":"Shifts from the previous topic to a related but separate or undecided point. Unlike \"關於\", which simply introduces a topic, \"至於\" carries a sense of contrast with what was just said.","k":"앞의 화제에서 관련은 있지만 별개이거나 아직 정해지지 않은 화제로 전환할 때 쓴다. \"關於\"는 단순히 화제를 도입하지만 \"至於\"는 앞 내용과 대비되는 뉘앙스가 있다."},"eg":[{"z":"開會的時間必須延期，<em>至於</em>延到什麼時候會再通知。","py":"Kāihuì de shíjiān bìxū yánqí, zhìyú yán dào shénme shíhòu huì zài tōngzhī.","j":"会議の時間は延期しなければならない。いつまで延びるかについては、改めて通知する。","e":"The meeting time has to be postponed; as for when it will be rescheduled to, we'll notify you again.","k":"회의 시간은 연기해야 한다. 언제까지 연기될지에 대해서는 다시 통지하겠다."},{"z":"這次旅行大家都同意去日本，<em>至於</em>要去哪個城市還沒決定。","py":"Zhè cì lǚxíng dàjiā dōu tóngyì qù Rìběn, zhìyú yào qù nǎge chéngshì hái méi juédìng.","j":"今回の旅行はみんな日本に行くことに賛成したが、どの都市に行くかについてはまだ決まっていない。","e":"Everyone agreed to go to Japan for this trip; as for which city to visit, it hasn't been decided yet.","k":"이번 여행은 모두 일본에 가기로 동의했지만, 어느 도시로 갈지에 대해서는 아직 정해지지 않았다."}]},
{"id":"g5-468","cat":"特殊構文","t":"所謂......是指/就是......","g":{"j":"いわゆる〜とは〜である(定義)","e":"\"so-called X\" is/refers to Y (giving a definition)","k":"이른바 ~란 ~이다(정의)"},"p":{"j":"所謂＋X＋是指/就是＋Y","e":"Suǒwèi + X + shì zhǐ / jiùshì + Y","k":"所謂＋X＋是指/就是＋Y"},"ex":{"j":"ある言葉や概念を取り上げて定義・説明するときに使う、やや書きことば寄りの表現。「是指」はより説明的、「就是」はより断定的なニュアンスになる。","e":"Used to define or explain a term or concept; somewhat formal in register. \"是指\" sounds more explanatory, while \"就是\" reads as a more direct equivalence.","k":"어떤 말이나 개념을 들어 정의·설명할 때 쓰는 다소 문어적인 표현. \"是指\"는 설명적인 느낌이, \"就是\"는 단정적인 느낌이 강하다."},"eg":[{"z":"<em>所謂公平就是每個人都有一樣的機會</em>。","py":"Suǒwèi gōngpíng jiùshì měi gè rén dōu yǒu yíyàng de jīhuì.","j":"いわゆる公平とは、誰もが同じ機会を持つことである。","e":"So-called fairness means that everyone has the same opportunity.","k":"이른바 공평이란 모든 사람이 똑같은 기회를 갖는 것이다."},{"z":"<em>所謂成功就是指達成自己設定的目標</em>。","py":"Suǒwèi chénggōng jiùshì zhǐ dáchéng zìjǐ shèdìng de mùbiāo.","j":"いわゆる成功とは、自分が定めた目標を達成することを指す。","e":"So-called success refers to achieving the goals you've set for yourself.","k":"이른바 성공이란 자신이 정한 목표를 달성하는 것을 가리킨다."}]},
{"id":"g5-469","cat":"介詞","t":"在......（之）下","g":{"j":"〜のもとで、〜という状況の中で","e":"under (a condition/influence of)...","k":"~하에서, ~라는 상황 속에서"},"p":{"j":"在＋NP(＋之)下","e":"zài + NP (+ zhī) xià","k":"在＋NP(＋之)下"},"ex":{"j":"ある状況・条件・影響のもとで結果が生じることを表す。「之」は書きことばでやや硬い言い方で、話しことばでは省略されることが多い。","e":"Expresses that a result occurs under a certain condition, influence, or circumstance. \"之\" is optional and formal, and is usually dropped in everyday speech.","k":"어떤 상황·조건·영향 아래에서 결과가 생김을 나타낸다. \"之\"는 문어적이고 다소 격식 있는 표현으로, 구어에서는 흔히 생략된다."},"eg":[{"z":"<em>在比賽的壓力下</em>，他表現得沒有預期的好。","py":"Zài bǐsài de yālì xià, tā biǎoxiàn de méiyǒu yùqí de hǎo.","j":"試合のプレッシャーの下で、彼は期待されたほど良い成績を出せなかった。","e":"Under the pressure of the competition, he didn't perform as well as expected.","k":"경기의 압박 속에서 그는 기대만큼 좋은 성적을 내지 못했다."},{"z":"<em>在老師的幫助下</em>，他終於考上了理想的大學。","py":"Zài lǎoshī de bāngzhù xià, tā zhōngyú kǎoshàng le lǐxiǎng de dàxué.","j":"先生の助けのもとで、彼はついに理想の大学に合格した。","e":"With the teacher's help, he finally got into his dream university.","k":"선생님의 도움으로 그는 마침내 원하던 대학에 합격했다."}]},
{"id":"g5-470","cat":"介詞","t":"對（於）......而言","g":{"j":"〜にとって(立場・観点)","e":"as far as ... is concerned / for...","k":"~에게 있어서(입장·관점)"},"p":{"j":"對（於）＋NP＋而言","e":"duì(yú) + NP + ér yán","k":"對（於）＋NP＋而言"},"ex":{"j":"ある人や立場から見た評価・意見を述べるときに使う。「對...來說」と意味は近いが、「而言」の方がやや書きことば的でフォーマルな場面に多い。","e":"Introduces an opinion or evaluation from a particular person's standpoint. Close in meaning to \"對...來說\", but \"而言\" is more formal and written in register.","k":"특정한 사람이나 입장에서 본 평가·의견을 말할 때 쓴다. \"對...來說\"와 뜻은 비슷하지만 \"而言\"이 더 문어적이고 격식 있는 표현이다."},"eg":[{"z":"<em>對於公司的員工而言</em>，加薪是一種很大的鼓勵。","py":"Duìyú gōngsī de yuángōng ér yán, jiāxīn shì yì zhǒng hěn dà de gǔlì.","j":"会社の従業員にとって、昇給は大きな励みとなる。","e":"For the company's employees, a raise is a great encouragement.","k":"회사 직원들에게 있어 임금 인상은 큰 격려가 된다."},{"z":"<em>對學生而言</em>，健康比成績更重要。","py":"Duì xuéshēng ér yán, jiànkāng bǐ chéngjī gèng zhòngyào.","j":"学生にとって、健康は成績よりも重要だ。","e":"For students, health is more important than grades.","k":"학생에게 있어 건강이 성적보다 더 중요하다."}]},
{"id":"g5-471","cat":"特殊構文","t":"（在）......（之）中","g":{"j":"〜の中で","e":"among/within...","k":"~중에서"},"p":{"j":"（在）＋範囲＋（之）中","e":"(zài) + range + (zhī) zhōng","k":"(在) + 범위 + (之) 中"},"ex":{"j":"「在……中」は範囲を示し、その範囲内での比較・選択を表す。「最」「比較」などと共起しやすい。「在」「之」は省略可。似た「其中」は代名詞的で後に名詞を続けられない点に注意。","e":"'(Zài)...(zhī)zhōng' marks a range within which a comparison or choice is made, often paired with 最 or 比較. 在/之 are optional. Unlike 其中 (a pronoun, cannot take a following noun), this pattern directly follows a noun phrase.","k":"'(在)...(之)中'은 범위를 나타내며 그 안에서 비교나 선택을 표현한다. 在/之는 생략 가능. 대명사인 其中과 달리 뒤에 명사구가 올 수 있다는 점이 다르다."},"eg":[{"z":"<em>在臺灣各種美食中</em>，他最喜歡小籠包。","py":"Zài Táiwān gèzhǒng měishí zhōng, tā zuì xǐhuān xiǎolóngbāo.","j":"台灣の様々なグルメの中で、彼は小籠包が一番好きだ。","e":"Among the various foods in Taiwan, he likes xiaolongbao the most.","k":"대만의 다양한 음식 중에서 그는 샤오롱바오를 제일 좋아한다."},{"z":"<em>在班上的學生中</em>，小明的成績最好。","py":"Zài bānshàng de xuéshēng zhōng, Xiǎomíng de chéngjī zuì hǎo.","j":"クラスの学生の中で、シャオミンの成績が一番いい。","e":"Among the students in the class, Xiaoming has the best grades.","k":"반 학생들 중에서 샤오밍의 성적이 제일 좋다."}]},
{"id":"g5-472","cat":"特殊構文","t":"就......而言","g":{"j":"〜について言えば","e":"as for.../in terms of...","k":"~에 대해 말하자면"},"p":{"j":"就＋話題／立場＋而言","e":"jiù + topic/standpoint + éryán","k":"就 + 주제/입장 + 而言"},"ex":{"j":"「就……而言」は話題や立場を提示し、その観点からの評価・判断を述べる書きことば的表現。「就……來說」とほぼ同義だが「而言」の方がやや正式。話題語には具体的な事柄や人の立場が入る。","e":"'Jiù...éryán' introduces a topic or standpoint before giving a judgment from that angle; it's a more formal, written equivalent of 就……來說. The clause following 而言 must be a full comment, not just a noun.","k":"'就……而言'는 화제나 입장을 제시한 뒤 그 관점에서의 평가를 말하는 문어체 표현으로, '就……來說'보다 격식적이다. 而言 뒤에는 완전한 평가문이 와야 한다."},"eg":[{"z":"<em>就經濟發展而言</em>，今年的平均薪資比去年成長百分之三。","py":"Jiù jīngjì fāzhǎn éryán, jīnnián de píngjūn xīnzī bǐ qùnián chéngzhǎng bǎifēnzhī sān.","j":"経済発展について言えば、今年の平均給与は去年より3パーセント増加した。","e":"In terms of economic development, this year's average salary increased by three percent compared to last year.","k":"경제 발전에 관해 말하자면, 올해 평균 임금이 작년보다 3퍼센트 증가했다."},{"z":"<em>就學生的立場而言</em>，考試壓力真的很大。","py":"Jiù xuésheng de lìcháng éryán, kǎoshì yālì zhēnde hěn dà.","j":"学生の立場から言えば、試験のプレッシャーは本当に大きい。","e":"From the students' perspective, exam pressure is really huge.","k":"학생의 입장에서 말하자면, 시험 스트레스가 정말 크다."}]},
{"id":"g5-473","cat":"介詞","t":"在......上","g":{"j":"〜の面で／〜において","e":"in terms of/in the area of...","k":"~면에서/~상으로"},"p":{"j":"在＋抽象的な範疇＋上","e":"zài + abstract domain + shàng","k":"在 + 추상적 범주 + 上"},"ex":{"j":"「在……上」は具体的な場所ではなく、抽象的な側面や分野(國際、品質、心理など)を示すのに使う。同じ「在……上」でも場所を表す「在桌子上」とは意味が異なるので混同しないこと。","e":"'Zài...shàng' marks an abstract domain or aspect (e.g., 國際上, 品質上), distinct from its literal spatial use meaning 'on top of' (在桌子上). Learners often confuse the abstract and literal senses.","k":"'在……上'은 국제, 품질처럼 추상적인 측면이나 분야를 나타낸다. '在桌子上'처럼 실제 장소를 뜻하는 용법과 혼동하지 않도록 주의해야 한다."},"eg":[{"z":"這位有名的導演拍攝了一部電影，<em>在國際上</em>得到了很好的評價。","py":"Zhè wèi yǒumíng de dǎoyǎn pāishè le yí bù diànyǐng, zài guójì shàng dédào le hěn hǎo de píngjià.","j":"この有名な監督は一本の映画を撮り、国際的に高い評価を得た。","e":"This famous director made a film that received high acclaim internationally.","k":"이 유명한 감독은 영화 한 편을 찍었는데, 국제적으로 좋은 평가를 받았다."},{"z":"這個產品<em>在品質上</em>非常有保障。","py":"Zhège chǎnpǐn zài pǐnzhí shàng fēicháng yǒu bǎozhàng.","j":"この製品は品質の面で非常に保証されている。","e":"This product is very well guaranteed in terms of quality.","k":"이 제품은 품질 면에서 매우 보장되어 있다."}]},
{"id":"g5-474","cat":"特殊構文","t":"以......為主","g":{"j":"〜を主とする","e":"mainly consists of/is based on...","k":"~을 위주로 하다"},"p":{"j":"以＋対象＋為主","e":"yǐ + object + wéi zhǔ","k":"以 + 대상 + 為主"},"ex":{"j":"「以……為主」はある事物の中で最も重要・中心的な部分を示す。「主要」は形容詞・副詞として使うのに対し、「以……為主」は「主とする対象」を文中に明示する構文である点が異なる。","e":"'Yǐ...wéi zhǔ' states that something is the main/central component, placing the object right after 以. Unlike the adjective/adverb 主要, this pattern is a fixed construction naming the primary element explicitly.","k":"'以……為主'는 어떤 것 중에서 가장 중심이 되는 부분을 나타낸다. 형용사/부사인 '主要'와 달리, 중심이 되는 대상을 문장 안에 직접 명시하는 구문이라는 점이 다르다."},"eg":[{"z":"這個國家的經濟是<em>以農業為主</em>。","py":"Zhège guójiā de jīngjì shì yǐ nóngyè wéi zhǔ.","j":"この国の経済は農業を主としている。","e":"This country's economy is mainly based on agriculture.","k":"이 나라의 경제는 농업을 위주로 한다."},{"z":"我們公司的產品<em>以手機配件為主</em>。","py":"Wǒmen gōngsī de chǎnpǐn yǐ shǒujī pèijiàn wéi zhǔ.","j":"私たちの会社の製品はスマートフォンのアクセサリーが主だ。","e":"Our company's products are mainly phone accessories.","k":"우리 회사 제품은 휴대폰 액세서리가 위주다."}]},
{"id":"g5-475","cat":"疑問","t":"是否","g":{"j":"〜かどうか","e":"whether or not...","k":"~인지 아닌지"},"p":{"j":"是否＋動詞句(間接疑問文で使う)","e":"shìfǒu + VP (used in indirect questions)","k":"是否 + 동사구(간접의문문)"},"ex":{"j":"「是否」は書きことば的な「〜かどうか」で、間接疑問文の中で使う。話しことばの「有沒有」「V不V」と違い、文末に「嗎」を付けない。文中(檢查、知道などの後)で使うのが典型。","e":"'Shìfǒu' is the formal written equivalent of 'whether or not,' used inside indirect questions (after verbs like 檢查, 知道). Unlike the colloquial 有沒有 or V-not-V forms, it never takes a sentence-final 嗎.","k":"'是否'는 문어체로 '~인지 아닌지'를 뜻하며 간접의문문 안에서 쓰인다. 구어체인 '有沒有'나 'V不V'와 달리 문장 끝에 '嗎'를 붙이지 않는다."},"eg":[{"z":"每次外出，我一定會檢查<em>是否</em>帶了皮包跟鑰匙。","py":"Měi cì wàichū, wǒ yídìng huì jiǎnchá shìfǒu dàile píbāo gēn yàoshi.","j":"毎回外出するとき、私は必ず財布と鍵を持ったかどうか確認する。","e":"Every time I go out, I always check whether I have my wallet and keys.","k":"매번 외출할 때, 나는 반드시 지갑과 열쇠를 챙겼는지 확인한다."},{"z":"老師想知道學生<em>是否</em>都聽懂了。","py":"Lǎoshī xiǎng zhīdào xuéshēng shìfǒu dōu tīngdǒng le.","j":"先生は学生がみんな理解したかどうか知りたがっている。","e":"The teacher wants to know whether all the students understood.","k":"선생님은 학생들이 다 이해했는지 알고 싶어한다."}]},
{"id":"g5-476","cat":"疑問","t":"如何","g":{"j":"〜はどうですか(提案)","e":"How about ...? (making a suggestion)","k":"~하는 게 어때요? (제안)"},"p":{"j":"動作句／內容 ＋ 如何？","e":"Statement/proposal + rúhé?","k":"제안 내용 + 如何？"},"ex":{"j":"文末の「如何？」は提案や意見を尋ねる用法で、「怎麼樣？」よりやや書き言葉的・丁寧な響きがある。疑問詞「如何」(どのように、例:如何做)と混同しないよう注意。","e":"Sentence-final 如何? asks for agreement on a suggestion, similar to 怎麼樣? but more formal/polite. Don't confuse with 如何 meaning 'how' (如何做 = how to do it).","k":"문장 끝의 如何？는 제안에 대한 의견을 묻는 표현으로 怎麼樣？보다 다소 문어적이고 정중하다. '어떻게'라는 뜻의 의문사 如何(如何做 등)와 혼동하지 않도록 주의."},"eg":[{"z":"我們把聚會的時間定在明天下午<em>如何</em>？","py":"Wǒmen bǎ jùhuì de shíjiān dìng zài míngtiān xiàwǔ rúhé?","j":"私たちは集まりの時間を明日の午後に決めるのはどうですか？","e":"How about we set the gathering time for tomorrow afternoon?","k":"우리 모임 시간을 내일 오후로 정하는 게 어때요?"},{"z":"我們把畢業旅行的地點改在花蓮<em>如何</em>？","py":"Wǒmen bǎ bìyè lǚxíng de dìdiǎn gǎi zài Huālián rúhé?","j":"私たちは卒業旅行の場所を花蓮に変えるのはどうですか？","e":"How about we change the graduation trip location to Hualien?","k":"우리 졸업여행 장소를 화롄으로 바꾸는 게 어때요?"}]},
{"id":"g5-477","cat":"接続","t":"（更）何況","g":{"j":"まして〜は言うまでもない","e":"let alone; not to mention","k":"하물며 ~는 말할 것도 없다"},"p":{"j":"A，更何況 B","e":"A, gèng hékuàng B","k":"A，更何況 B"},"ex":{"j":"「更何況」は前文の内容を根拠に、さらに極端な例を挙げて「それならなおさら〜だ」と強調する。「更」があることで単独の「何況」より強調が強まる。「更別說…了」とほぼ同義だが、「更何況」は後ろに主語+述語の節が続くことが多い。","e":"更何況 uses the prior statement as a basis to raise an even more extreme example ('all the more so'). Adding 更 makes the emphasis stronger than plain 何況. Close in meaning to 更別說...了, but 更何況 is usually followed by a full subject+predicate clause.","k":"更何況는 앞 문장을 근거로 더 극단적인 예를 들어 '하물며 더욱더 그렇다'를 강조한다. 更가 붙어 단순 何況보다 강조가 세다. 更別說...了와 뜻이 비슷하지만 更何況 뒤에는 주어+술어로 이루어진 절이 오는 경우가 많다."},"eg":[{"z":"比賽前一定會緊張，<em>更何況</em>是第一次參加比賽的選手。","py":"Bǐsài qián yídìng huì jǐnzhāng, gèng hékuàng shì dì-yī cì cānjiā bǐsài de xuǎnshǒu.","j":"試合前は誰でも緊張するものだが、まして初めて試合に出る選手ならなおさらだ。","e":"One is bound to feel nervous before a competition, let alone a contestant competing for the first time.","k":"시합 전에는 누구나 긴장하기 마련인데, 하물며 처음 시합에 참가하는 선수는 말할 것도 없다."},{"z":"他平常走路就會喘，<em>更何況</em>是跑步。","py":"Tā píngcháng zǒulù jiù huì chuǎn, gèng hékuàng shì pǎobù.","j":"彼は普段歩くだけでも息が切れるのに、まして走るのはなおさらだ。","e":"He gets out of breath just from walking normally, let alone running.","k":"그는 평소에 걷기만 해도 숨이 차는데, 하물며 뛰는 것은 말할 것도 없다."}]},
{"id":"g5-478","cat":"接続","t":"不說......還......","g":{"j":"〜は言うまでもなく、さらに〜","e":"not only..., but also (even more so)...","k":"~은 말할 것도 없고 게다가 ~"},"p":{"j":"A ＋ 不說，還 ＋ B","e":"A + bù shuō, hái + B","k":"A + 不說，還 + B"},"ex":{"j":"ここでの「不說」は「言うまでもなく」という意味の決まった言い方で、「話さない」という意味ではない。前後の主語は共通で、「還」でさらに一段上の事実を追加する。「不僅…還…」に近いが、「不說」はより話し言葉的。","e":"不說 here is a fixed phrase meaning 'not to mention,' not a negation of 'to speak.' The subject is shared across both clauses; 還 adds an even more impressive fact. Close to 不僅...還..., but 不說 sounds more colloquial.","k":"여기서 不說는 '말할 것도 없이'라는 뜻의 고정 표현이며 '말하지 않다'는 의미가 아니다. 앞뒤 주어는 동일하고 還로 한 단계 더한 사실을 덧붙인다. 不僅…還…와 비슷하지만 不說가 더 구어적이다."},"eg":[{"z":"他寫作能力好<em>不說</em>，<em>還</em>得過演講比賽第一名。","py":"Tā xiězuò nénglì hǎo bù shuō, hái déguò yǎnjiǎng bǐsài dì-yī míng.","j":"彼は文章力が良いだけでなく、スピーチコンテストで優勝したこともある。","e":"Not only is his writing ability good, he's even won first place in a speech contest.","k":"그는 글쓰기 실력이 좋을 뿐만 아니라 스피치 대회에서 1등을 한 적도 있다."},{"z":"這家餐廳位置方便<em>不說</em>，<em>還</em>很便宜。","py":"Zhè jiā cāntīng wèizhì fāngbiàn bù shuō, hái hěn piányí.","j":"このレストランは場所が便利なだけでなく、値段もとても安い。","e":"This restaurant is not only conveniently located, it's also very cheap.","k":"이 식당은 위치가 편리할 뿐만 아니라 가격도 아주 싸다."}]},
{"id":"g5-479","cat":"接続","t":"更別說......了","g":{"j":"まして〜は言うまでもない(文末に「了」)","e":"let alone... (sentence ends with 了)","k":"하물며 ~는 말할 것도 없다 (문장 끝에 了)"},"p":{"j":"A，更別說 B 了","e":"A, gèng biéshuō B le","k":"A，更別說 B 了"},"ex":{"j":"「更別說」は前文より明らかに極端な例を挙げ、文末に「了」を伴うのが特徴。名詞だけが続くことも多い(例:更別說夜晚了)。「更何況」は後ろに完全な節(主語+述語)が来やすい点で異なる。文末の「了」を忘れないこと。","e":"更別說 raises an even more extreme/obvious example and characteristically ends with sentence-final 了; it can be followed by just a noun (e.g. 更別說夜晚了). It differs from 更何況, which usually takes a full clause (subject+predicate) after it. Don't forget the final 了.","k":"更別說는 앞 문장보다 더 극단적이고 명백한 예를 들며 문장 끝에 了를 동반하는 것이 특징이다. 명사만 이어지는 경우도 많다(예: 更別說夜晚了). 更何況는 보통 완전한 절(주어+술어)이 뒤따른다는 점에서 다르다. 문장 끝의 了를 빠뜨리지 않도록 주의."},"eg":[{"z":"山上的天氣非常寒冷，白天也才五度，<em>更別說</em>夜晚<em>了</em>。","py":"Shānshàng de tiānqì fēicháng hánlěng, báitiān yě cái wǔ dù, gèng biéshuō yèwǎn le.","j":"山の上の天気はとても寒く、昼間でもわずか5度しかないのだから、まして夜はなおさらだ。","e":"The weather in the mountains is extremely cold — even in the daytime it's only five degrees, let alone at night.","k":"산 위의 날씨는 매우 추워서 낮에도 겨우 5도밖에 안 되는데, 하물며 밤은 말할 것도 없다."},{"z":"他連中文都聽不懂，<em>更別說</em>看中文報紙<em>了</em>。","py":"Tā lián Zhōngwén dōu tīng bù dǒng, gèng biéshuō kàn Zhōngwén bàozhǐ le.","j":"彼は中国語を聞いてもわからないのだから、まして中国語の新聞を読むのはなおさら無理だ。","e":"He can't even understand spoken Chinese, let alone read a Chinese newspaper.","k":"그는 중국어를 들어도 못 알아듣는데, 하물며 중국어 신문을 읽는 것은 말할 것도 없다."}]},
{"id":"g5-480","cat":"接続","t":"別說......（連）......也......","g":{"j":"〜は言うまでもなく、〜さえも","e":"not to mention..., even... too","k":"~은 말할 것도 없고 ~조차도"},"p":{"j":"別說 A，（連）B 也 C","e":"Biéshuō A, (lián) B yě C","k":"別說 A，（連）B 也 C"},"ex":{"j":"「別說A，(連)B也C」はAとBという2つの対象を比較し、Aが当然そうであるのは言うまでもなく、Bさえも同じ(C)だと強調する構文。文末に「了」は不要な点が「更別說…了」と異なる。「連」は省略可能だが「也」は省略できない。","e":"別說 A, (連) B 也 C compares two subjects A and B, stressing that if even A is obviously so, B — an even more surprising case — is the same. Unlike 更別說...了, no sentence-final 了 is needed. 連 is optional but 也 is required.","k":"別說 A, (連) B 也 C는 A와 B 두 대상을 비교하여 A가 당연히 그러한 것은 말할 것도 없고 B조차도 마찬가지(C)임을 강조하는 구문이다. 更別說...了와 달리 문장 끝에 了가 필요 없다. 連은 생략 가능하지만 也는 생략할 수 없다."},"eg":[{"z":"<em>別說</em>學生不認識這個字，老師<em>也</em>不認識。","py":"Biéshuō xuéshēng bú rènshì zhège zì, lǎoshī yě bú rènshì.","j":"学生がこの字を知らないのは言うまでもなく、先生でさえ知らない。","e":"Not to mention students not recognizing this character, even the teacher doesn't recognize it.","k":"학생이 이 글자를 모르는 것은 말할 것도 없고, 선생님조차도 모른다."},{"z":"<em>別說</em>外國人聽不懂台語，連很多年輕人<em>也</em>聽不懂。","py":"Biéshuō wàiguórén tīng bù dǒng Táiyǔ, lián hěn duō niánqīngrén yě tīng bù dǒng.","j":"外国人が台湾語を聞き取れないのは言うまでもなく、多くの若者でさえ聞き取れない。","e":"Not to mention foreigners not understanding Taiwanese, even many young people can't understand it either.","k":"외국인이 대만어를 못 알아듣는 것은 말할 것도 없고, 많은 젊은이들조차 못 알아듣는다."}]},
{"id":"g5-481","cat":"接続","t":"此外","g":{"j":"さらに、その他に","e":"in addition, besides","k":"게다가, 그 외에"},"p":{"j":"文。＋此外，＋文。","e":"Sentence. + 此外, + additional sentence.","k":"문장。＋此外，＋문장。"},"ex":{"j":"「此外」は文頭に置き、前文に情報を追加する書き言葉的な接続語。「另外」と似るが此外はやや正式で、前の内容の延長・補足を示す。話し言葉では「另外」の方が多い。","e":"此外 starts a new sentence to add supplementary information, common in formal/written Chinese. Similar to 另外 but more formal; don't confuse it with 除了...以外 which means 'except for'.","k":"此外는 문장 앞에 놓여 앞 내용에 정보를 추가하는 격식체 접속어이다. 另外와 비슷하지만 더 격식적이며, 除了...以外(제외)와 혼동하지 말 것."},"eg":[{"z":"<em>此外</em>，生日當天還有贈品。","py":"Cǐwài, shēngrì dàngtiān hái yǒu zèngpǐn.","j":"さらに、誕生日当日にはプレゼントもあります。","e":"Besides, there's also a gift on your birthday.","k":"게다가 생일 당일에는 선물도 있습니다."},{"z":"這家店的咖啡很好喝，<em>此外</em>，服務也很親切。","py":"Zhè jiā diàn de kāfēi hěn hǎohē, cǐwài, fúwù yě hěn qīnqiè.","j":"このお店のコーヒーはとても美味しい。さらに、サービスもとても親切だ。","e":"This shop's coffee is delicious. Besides, the service is also very friendly.","k":"이 가게의 커피는 정말 맛있다. 게다가 서비스도 아주 친절하다."}]},
{"id":"g5-482","cat":"接続","t":"非但......還......","g":{"j":"〜どころか、むしろ〜","e":"not only... but (even/instead)...","k":"~뿐만 아니라 오히려~"},"p":{"j":"主語＋非但＋否定的な内容，還＋さらに悪い/意外な結果。","e":"Subject + 非但 + negative situation, 還 + a worse or unexpected outcome.","k":"주어＋非但＋부정적 상황，還＋더 심하거나 예상외의 결과。"},"ex":{"j":"「非但...還...」は予想に反して悪化・逆転する意味合いが強く、「不但...而且...」より書き言葉的でネガティブな文脈に多い。前半が否定文になりやすい点に注意。","e":"非但...還... stresses an unexpected reversal, usually toward something worse, and is more formal than 不但...而且...; it commonly pairs with a negated first clause, so don't force it into a positive-accumulation context.","k":"非但...還...는 예상과 반대로 더 나빠지는 뉘앙스가 강하며 不但...而且...보다 문어체적이다. 앞 절이 부정문이 되는 경우가 많음에 주의."},"eg":[{"z":"新產品的銷售量<em>非但</em>沒有增加，<em>還</em>減少了百分之三十。","py":"Xīn chǎnpǐn de xiāoshòuliàng fēidàn méiyǒu zēngjiā, hái jiǎnshǎole bǎifēnzhī sānshí.","j":"新製品の売上は増えないどころか、30%も減少した。","e":"The new product's sales not only failed to increase, but even dropped by 30%.","k":"신제품의 판매량은 증가하지 않았을 뿐만 아니라 오히려 30% 감소했다."},{"z":"他<em>非但</em>沒有道歉，<em>還</em>罵了對方。","py":"Tā fēidàn méiyǒu dàoqiàn, hái màle duìfāng.","j":"彼は謝らないどころか、相手を罵った。","e":"He not only didn't apologize, he even scolded the other person.","k":"그는 사과하지 않았을 뿐만 아니라 오히려 상대방을 욕했다."}]},
{"id":"g5-483","cat":"特殊構文","t":"小自......大至......","g":{"j":"小さくは〜から、大きくは〜まで","e":"ranging from (the smallest) to (the largest)","k":"작게는~부터 크게는~까지"},"p":{"j":"小自＋小さい事物，大至＋大きい事物，都/皆＋共通の述語。","e":"小自 + small item, 大至 + large item, 都/皆 + shared statement.","k":"小自＋작은 것，大至＋큰 것，都/皆＋공통 서술。"},"ex":{"j":"「小自...大至...」は範囲の両極端(小さい方〜大きい方)を並べて「すべて」を強調する書き言葉表現。順序(小→大)を逆にしないこと、日常会話ではあまり使わない。","e":"小自...大至... lists the smallest and largest ends of a scope to stress 'everything included'; it's a formal/written pattern. Keep the small-to-large order and avoid it in casual speech.","k":"小自...大至...는 작은 것에서 큰 것까지 범위의 양 끝을 나열해 '모두'를 강조하는 문어체 표현이다. 순서(작음→큼)를 바꾸지 말고 일상 회화에서는 잘 쓰지 않는다."},"eg":[{"z":"我們公司<em>小自</em>買筆，<em>大至</em>投資計畫都由總經理親自決定。","py":"Wǒmen gōngsī xiǎozì mǎi bǐ, dàzhì tóuzī jìhuà dōu yóu zǒngjīnglǐ qīnzì juédìng.","j":"私たちの会社では、小さくはペンの購入から、大きくは投資計画まで、すべて社長自らが決定する。","e":"In our company, everything from buying pens to investment plans is decided personally by the president.","k":"우리 회사는 작게는 펜 구매부터 크게는 투자 계획까지 모두 사장이 직접 결정한다."},{"z":"這次的活動<em>小自</em>海報設計，<em>大至</em>場地租借，都由她一個人負責。","py":"Zhè cì de huódòng xiǎozì hǎibào shèjì, dàzhì chǎngdì zūjiè, dōu yóu tā yí gè rén fùzé.","j":"今回のイベントは、小さくはポスターデザインから、大きくは会場の手配まで、すべて彼女一人が担当している。","e":"For this event, everything from poster design to venue rental is handled by her alone.","k":"이번 행사는 작게는 포스터 디자인부터 크게는 장소 대여까지 모두 그녀 혼자 담당하고 있다."}]},
{"id":"g5-484","cat":"接続","t":"正如","g":{"j":"〜の通り、まさに〜のように","e":"just as, exactly as","k":"바로 ~처럼, ~대로"},"p":{"j":"正如＋子句(所說/所想的)，後面接結果。","e":"正如 + clause (what was said/thought), followed by the result.","k":"正如＋절(말한/생각한 대로)，뒤에 결과。"},"ex":{"j":"「正如」は前に述べた予想や発言の通りであることを示す書き言葉。「所＋動詞＋的」の形と一緒に使われることが多く、口語の「就像」より硬い表現。","e":"正如 confirms that reality matches an earlier statement or expectation; formal register, often followed by 所+V+的. It's more written than the colloquial 就像 — avoid it in casual chat.","k":"正如는 앞서 언급한 예상이나 말과 실제가 일치함을 나타내는 문어체 표현이다. 所+동사+的 구조와 자주 쓰이고, 구어체 就像보다 격식적이다."},"eg":[{"z":"<em>正如</em>我們所猜想的，商品在一天之內全都賣光了。","py":"Zhèngrú wǒmen suǒ cāixiǎng de, shāngpǐn zài yì tiān zhī nèi quán dōu màiguāng le.","j":"私たちが推測していた通り、商品は一日以内に全部売り切れた。","e":"Just as we had guessed, the merchandise completely sold out within one day.","k":"우리가 예상했던 대로 상품은 하루 만에 전부 매진되었다."},{"z":"<em>正如</em>老師說的，這次考試的題目真的不難。","py":"Zhèngrú lǎoshī shuō de, zhè cì kǎoshì de tímù zhēnde bù nán.","j":"先生が言った通り、今回の試験問題は本当に難しくなかった。","e":"Just as the teacher said, the questions on this exam really weren't difficult.","k":"선생님이 말씀하신 대로 이번 시험 문제는 정말 어렵지 않았다."}]},
{"id":"g5-485","cat":"特殊構文","t":"（V）自","g":{"j":"〜に由来する、〜から出ている","e":"to originate from, to come from","k":"~에서 비롯되다, ~에서 나오다"},"p":{"j":"V(出/源/來/取など)＋自＋出所。","e":"V (出/源/來/取, etc.) + 自 + source.","k":"V(出/源/來/取 등)＋自＋출처。"},"ex":{"j":"「(V)自」は出自・源自・來自・取自のように動詞に直結し「〜から」を表す書き言葉の型。「從」は動詞の前に置く介詞なので語順が逆になる点に注意。","e":"(V)自 attaches directly after verbs like 出/源/來/取 to mean 'from,' forming formal compounds such as 出自, 源自, 來自. Unlike the preposition 從, which precedes the source before the verb, so don't mix up the word order.","k":"(V)自는 出/源/來/取 등의 동사 뒤에 바로 붙어 '~에서'를 나타내는 문어체 형식이다(出自, 源自, 來自 등). 동사 앞에 오는 전치사 從과 어순이 반대이므로 혼동하지 말 것."},"eg":[{"z":"這部電影的靈感<em>出自</em>紅樓夢。","py":"Zhè bù diànyǐng de línggǎn chūzì Hóng Lóu Mèng.","j":"この映画のインスピレーションは『紅楼夢』に由来する。","e":"This movie's inspiration comes from Dream of the Red Chamber.","k":"이 영화의 영감은 『홍루몽』에서 비롯되었다."},{"z":"這個成語<em>源自</em>一個古代的故事。","py":"Zhège chéngyǔ yuánzì yí gè gǔdài de gùshì.","j":"この成語は古代のある物語に由来する。","e":"This idiom originates from an ancient story.","k":"이 성어는 고대의 한 이야기에서 유래했다."}]},
{"id":"g5-486","cat":"介詞","t":"（V）於","g":{"j":"「〜において/〜から」を表す書き言葉の動詞＋於","e":"formal written 'V + 於' indicating origin, time, or place","k":"'~에서/~로부터'를 나타내는 문어체 동사+於"},"p":{"j":"Ａ＋動詞＋於＋Ｂ(時間/地點/出處)","e":"A + V + 於 + B (time/place/origin)","k":"A+동사+於+B(시간/장소/출처)"},"ex":{"j":"「於」は書き言葉で「在」「從」の代わりに使われ、畢業於・生於・位於など決まった動詞とだけ結びつく。口語では「從...畢業」「在...出生」のように言う方が自然。","e":"\"於\" is a formal/written substitute for 在/從, fixed to specific verbs like 畢業於, 生於, 位於; it's not freely combinable with any verb. Spoken Chinese prefers 在/從 constructions instead.","k":"\"於\"는 문어체에서 \"在/從\" 대신 쓰이며 畢業於·生於·位於처럼 정해진 동사와만 결합한다. 구어체에서는 \"在...出生\"처럼 말하는 것이 더 자연스럽다."},"eg":[{"z":"李明華<em>畢業於</em>中文系。","py":"Lǐ Mínghuá bìyè yú Zhōngwén xì.","j":"李明華は中国語学科を卒業した。","e":"Li Minghua graduated from the Chinese department.","k":"리밍화는 중문과를 졸업했다."},{"z":"他<em>生於</em>一九九零年。","py":"Tā shēng yú yī jiǔ jiǔ líng nián.","j":"彼は1990年生まれだ。","e":"He was born in 1990.","k":"그는 1990년에 태어났다."}]},
{"id":"g5-487","cat":"介詞","t":"至","g":{"j":"「〜まで」を表す書き言葉の範囲表現","e":"formal written 'to/until' for ranges","k":"'~까지'를 나타내는 문어체 범위 표현"},"p":{"j":"Ａ＋至＋Ｂ(範囲の終点)","e":"A + 至 + B (endpoint of a range)","k":"A+至+B(범위의 끝점)"},"ex":{"j":"「至」は「到」の書き言葉版で、数字・時間・場所の範囲の終点を示す。「從...至...」の形でよく使うが、「到了」のように後ろに「了」を付けられない点が「到」と違う。","e":"\"至\" is the written form of 到, marking the endpoint of a range (numbers, time, place), often in \"從...至...\". Unlike 到, it cannot take aspect markers like 了 after it.","k":"\"至\"는 \"到\"의 문어체 표현으로 숫자·시간·장소 범위의 끝을 나타낸다. \"從...至...\" 형태로 자주 쓰이며, \"到了\"처럼 뒤에 \"了\"를 붙일 수 없다는 점이 \"到\"와 다르다."},"eg":[{"z":"本公司徵求行銷人員，薪水三萬五千<em>至</em>四萬。","py":"Běn gōngsī zhēngqiú xíngxiāo rényuán, xīnshuǐ sān wàn wǔ qiān zhì sì wàn.","j":"本社ではマーケティング担当者を募集しています。給料は3万5千から4万です。","e":"Our company is recruiting marketing staff; the salary is from 35,000 to 40,000.","k":"저희 회사는 마케팅 담당자를 모집합니다. 급여는 3만 5천에서 4만입니다."},{"z":"營業時間從早上九點<em>至</em>晚上九點。","py":"Yíngyè shíjiān cóng zǎoshang jiǔ diǎn zhì wǎnshang jiǔ diǎn.","j":"営業時間は朝9時から夜9時までです。","e":"Business hours are from 9 a.m. to 9 p.m.","k":"영업시간은 아침 9시부터 밤 9시까지입니다."}]},
{"id":"g5-488","cat":"特殊構文","t":"以......為例","g":{"j":"「〜を例にとると」","e":"\"taking ... as an example\"","k":"'~을 예로 들면'"},"p":{"j":"以＋Ｎ＋為例","e":"以 + N + 為例","k":"以+N+為例"},"ex":{"j":"前に述べた一般的な内容を具体例で説明するときに使う。「以Ａ為例」は「Ａを例にとると」の意味で、後ろに具体的な説明が続く。","e":"Used to introduce a concrete example that illustrates a general statement made earlier; \"以A為例\" means \"taking A as an example,\" followed by specific details.","k":"앞서 말한 일반적인 내용을 구체적인 예로 설명할 때 쓴다. \"以A為例\"는 \"A를 예로 들면\"이라는 뜻으로, 뒤에 구체적인 설명이 이어진다."},"eg":[{"z":"臺北的交通很方便，<em>以捷運為例</em>，附近的景點都到得了。","py":"Táiběi de jiāotōng hěn fāngbiàn, yǐ jiéyùn wéi lì, fùjìn de jǐngdiǎn dōu dào de liǎo.","j":"台北の交通はとても便利で、MRTを例にとると、近くの観光スポットにはすべて行ける。","e":"Taipei's transportation is very convenient; taking the MRT as an example, you can reach all the nearby attractions.","k":"타이베이의 교통은 매우 편리한데, MRT를 예로 들면 근처의 관광명소에 다 갈 수 있다."},{"z":"臺灣的水果很多，<em>以芒果為例</em>，夏天到處都買得到。","py":"Táiwān de shuǐguǒ hěn duō, yǐ mángguǒ wéi lì, xiàtiān dàochù dōu mǎi de dào.","j":"台湾には果物がたくさんあり、マンゴーを例にとると、夏はどこでも買える。","e":"Taiwan has a lot of fruit; taking mangoes as an example, you can buy them everywhere in summer.","k":"대만에는 과일이 많은데, 망고를 예로 들면 여름에는 어디서나 살 수 있다."}]},
{"id":"g5-489","cat":"接続","t":"免得","g":{"j":"「〜しないように」望ましくない結果を避ける","e":"\"so as not to / to avoid\"","k":"'~하지 않도록'"},"p":{"j":"子句１，免得＋子句２(望ましくない結果)","e":"Clause 1, 免得 + Clause 2 (undesired result)","k":"절1, 免得+절2(바람직하지 않은 결과)"},"ex":{"j":"前の動作をすることで避けたい悪い結果を後ろに示す。「以免」とほぼ同じ意味だが、「免得」の方が口語的でよく話し言葉に使われる。","e":"Introduces an undesired outcome to be avoided by doing the action in the first clause. Similar to 以免, but 免得 is more colloquial and commonly used in speech, while 以免 is more formal/written.","k":"앞 절의 행동을 함으로써 피하고 싶은 나쁜 결과를 뒤에 나타낸다. \"以免\"과 뜻이 비슷하지만 \"免得\"가 더 구어적이며 회화에서 자주 쓰인다."},"eg":[{"z":"趕緊把頭髮擦乾，<em>免得</em>感冒了。","py":"Gǎnjǐn bǎ tóufǎ cā gān, miǎnde gǎnmào le.","j":"早く髪を拭いて乾かして、風邪をひかないように。","e":"Dry your hair quickly, so you won't catch a cold.","k":"얼른 머리를 닦아서 말려, 감기 걸리지 않게."},{"z":"出門前記得帶傘，<em>免得</em>淋濕。","py":"Chūmén qián jìde dài sǎn, miǎnde lín shī.","j":"出かける前に傘を忘れずに持って、濡れないように。","e":"Remember to bring an umbrella before you go out, so you won't get soaked.","k":"나가기 전에 우산을 챙겨, 비에 젖지 않게."}]},
{"id":"g5-490","cat":"接続","t":"然而","g":{"j":"「しかし/けれども」前後の対比を表す書き言葉の接続詞","e":"\"however\" — formal written contrastive conjunction","k":"'그러나/하지만' - 문어체 대조 접속사"},"p":{"j":"子句１，然而＋子句２(対比)","e":"Clause 1, 然而 + Clause 2 (contrast)","k":"절1, 然而+절2(대조)"},"ex":{"j":"「然而」は「但是」「不過」の書き言葉版で、前の内容と対照的な内容を導く。「雖然...然而...」の形でよく使われ、日常会話では「但是」の方がよく使われる。","e":"\"然而\" is the formal/written equivalent of 但是/不過, introducing a contrast to what precedes; often paired with 雖然 in the first clause. In casual speech, 但是 is more common.","k":"\"然而\"는 \"但是/不過\"의 문어체 표현으로 앞 내용과 대조되는 내용을 이끈다. \"雖然...然而...\" 형태로 자주 쓰이며, 일상 회화에서는 \"但是\"가 더 자주 쓰인다."},"eg":[{"z":"經濟發展雖然重要，<em>然而</em>也不能忽略環境的保護。","py":"Jīngjì fāzhǎn suīrán zhòngyào, rán'ér yě bùnéng hūlüè huánjìng de bǎohù.","j":"経済発展は重要だが、しかし環境保護もおろそかにしてはいけない。","e":"Economic development is important; however, environmental protection must not be neglected either.","k":"경제 발전은 중요하지만, 그러나 환경 보호도 소홀히 해서는 안 된다."},{"z":"他每天都很努力讀書，<em>然而</em>成績還是不理想。","py":"Tā měitiān dōu hěn nǔlì dúshū, rán'ér chéngjī háishì bù lǐxiǎng.","j":"彼は毎日一生懸命勉強しているが、しかし成績はやはり理想的ではない。","e":"He studies hard every day; however, his grades are still not ideal.","k":"그는 매일 열심히 공부하지만, 그러나 성적은 여전히 이상적이지 않다."}]},
{"id":"g5-491","cat":"接続","t":"不是......而是......","g":{"j":"～ではなく…だ","e":"not A but B","k":"A가 아니라 B이다"},"p":{"j":"不是＋A、而是＋B","e":"bùshì + A, ér shì + B","k":"不是 + A, 而是 + B"},"ex":{"j":"前の内容を否定して、本当の理由・事実を強く言い直す構文。「A不是B」だけの単純否定と違い、必ず対比的な正解Bを示す。「而」だけの対比文とは、否定→訂正の流れが必須な点で異なる。","e":"Used to firmly correct a false assumption by naming the real cause or fact. Unlike plain negation (不是B), it always supplies the correct alternative after 而是. Don't confuse with plain 而, which just contrasts without correcting.","k":"잘못된 생각을 부정하고 진짜 이유를 강조해서 말할 때 쓴다. 단순 부정 '不是B'와 달리 반드시 '而是'로 올바른 내용을 제시해야 한다. 단순 대조를 나타내는 '而'와는 구별해야 한다."},"eg":[{"z":"改變命運的關鍵<em>不是</em>靠算命，<em>而是</em>靠自己的努力。","py":"Gǎibiàn mìngyùn de guānjiàn búshì kào suànmìng, érshì kào zìjǐ de nǔlì.","j":"運命を変える鍵は、占いに頼ることではなく、自分自身の努力に頼ることだ。","e":"The key to changing your destiny is not relying on fortune-telling, but relying on your own effort.","k":"운명을 바꾸는 열쇠는 점술에 의지하는 것이 아니라 자기 자신의 노력에 의지하는 것이다."},{"z":"他<em>不是</em>不想幫忙，<em>而是</em>沒有時間。","py":"Tā búshì bùxiǎng bāngmáng, érshì méiyǒu shíjiān.","j":"彼は手伝いたくないのではなく、時間がないのだ。","e":"It's not that he doesn't want to help, but that he doesn't have time.","k":"그는 도와주고 싶지 않은 것이 아니라 시간이 없는 것이다."}]},
{"id":"g5-492","cat":"接続","t":"(不但)不/沒......反而......","g":{"j":"予想に反して～","e":"not only not..., but on the contrary...","k":"~하지 않고 오히려 ~하다"},"p":{"j":"(不但)不/沒＋動詞、反而＋意外な結果","e":"(bùdàn) bù/méi + V, fǎn'ér + unexpected result","k":"(不但)不/沒 + 동사, 反而 + 의외의 결과"},"ex":{"j":"予想される結果を否定し、その逆の意外な結果を導く。「反而」は必ず前の否定と組み合わさり、驚き・逆説のニュアンスを出す。「而」の単純対比とは違い、期待に反する結果に限定される。","e":"Negates the expected outcome, then 反而 introduces the opposite, unexpected result. Always paired with a preceding negation (不/沒); unlike plain 而 (simple contrast), it specifically marks a reversal against expectation.","k":"예상되는 결과를 부정한 뒤, '反而'로 그 반대의 의외의 결과를 제시한다. 반드시 앞의 부정(不/沒)과 함께 쓰이며, 단순 대조인 '而'와 달리 기대에 반하는 결과에만 쓰인다."},"eg":[{"z":"雖然爬山爬了一整天，但他們<em>不</em>覺得累，<em>反而</em>精神很好。","py":"Suīrán páshān pá le yì zhěngtiān, dàn tāmen bù juéde lèi, fǎn'ér jīngshén hěn hǎo.","j":"一日中山登りをしたのに、彼らは疲れを感じるどころか、かえって元気いっぱいだ。","e":"Although they hiked all day long, they don't feel tired — on the contrary, they're full of energy.","k":"하루 종일 등산을 했는데도 그들은 피곤하기는커녕 오히려 기운이 넘친다."},{"z":"他昨天<em>沒</em>睡好，上班<em>反而</em>更有精神。","py":"Tā zuótiān méi shuì hǎo, shàngbān fǎn'ér gèng yǒu jīngshén.","j":"彼は昨日よく眠れなかったのに、出勤すると逆にもっと元気になった。","e":"He didn't sleep well last night, but at work he was even more energetic instead.","k":"그는 어제 잠을 잘 못 잤는데도 출근하자 오히려 더 활기가 넘쳤다."}]},
{"id":"g5-493","cat":"接続","t":"則","g":{"j":"一方～は(対比)","e":"whereas / on the other hand (formal contrast)","k":"반면에 (격식체 대조)"},"p":{"j":"A，B則＋C(Aとの対比)","e":"A, B zé + C (contrasts with A)","k":"A, B 則 + C (A와 대조)"},"ex":{"j":"書き言葉的に二つの事柄を対比させる接続詞。話し言葉の「可是・不過」より硬い表現で、説明文や比較の文でよく使う。「而」とほぼ同義だが、「則」は前後で主語が変わる対比によく使われる。","e":"A formal, written-style conjunction contrasting two items, more formal than spoken 可是/不過. Commonly used when comparing two different subjects side by side. Very close to 而, but 則 leans more toward listing or comparing parallel facts.","k":"두 가지를 대조하는 문어체 접속사로, 구어체 可是/不過보다 격식적이다. 서로 다른 주어를 나란히 비교할 때 자주 쓴다. '而'와 뜻이 비슷하지만 '則'는 병렬적 비교에 더 자주 쓰인다."},"eg":[{"z":"電動車不會污染空氣，缺點<em>則</em>是價格偏高。","py":"Diàndòngchē bú huì wūrǎn kōngqì, quēdiǎn zé shì jiàgé piāngāo.","j":"電気自動車は空気を汚染しないが、欠点は価格が高めなことだ。","e":"Electric cars don't pollute the air; the drawback, however, is that the price is on the high side.","k":"전기차는 대기를 오염시키지 않지만, 단점은 가격이 다소 비싸다는 것이다."},{"z":"我喜歡爬山，姊姊<em>則</em>喜歡游泳。","py":"Wǒ xǐhuān páshān, jiějie zé xǐhuān yóuyǒng.","j":"私は山登りが好きだが、姉は水泳が好きだ。","e":"I like hiking, whereas my older sister likes swimming.","k":"나는 등산을 좋아하지만, 언니는 수영을 좋아한다."}]},
{"id":"g5-494","cat":"接続","t":"而","g":{"j":"そして／それに対して(書き言葉の接続詞)","e":"and / whereas (literary connective)","k":"그리고 / 반면에 (문어체 접속사)"},"p":{"j":"A，而＋B(対比・追加)","e":"A, ér + B (contrast or addition)","k":"A, 而 + B (대조 또는 추가)"},"ex":{"j":"書き言葉で前後の文をつなぎ、対比や補足を表す。「則」より用法が広く、対比だけでなく並列や因果の補足にも使える。会話ではあまり使わず、正式な文章や説明でよく見る。","e":"A written-style connector linking two clauses to show contrast or addition; broader than 則, which is mainly for parallel contrast. Rarely used in casual speech — typical of formal writing and explanations.","k":"문어체에서 앞뒤 문장을 연결해 대조나 보충을 나타낸다. 병렬 대조에 주로 쓰이는 '則'보다 쓰임이 넓다. 회화에서는 잘 쓰이지 않고 격식 있는 글에서 자주 보인다."},"eg":[{"z":"周末晚上大家都去聚餐，<em>而</em>我寧可在家自己做飯。","py":"Zhōumò wǎnshang dàjiā dōu qù jùcān, ér wǒ níngkě zài jiā zìjǐ zuò fàn.","j":"週末の夜はみんな外食に行くのに、私は家で自分で料理する方がいい。","e":"On weekend evenings everyone goes out to eat together, whereas I'd rather cook for myself at home.","k":"주말 저녁에는 다들 외식하러 가는데, 나는 오히려 집에서 직접 요리하는 편이 낫다."},{"z":"弟弟喜歡打籃球，<em>而</em>妹妹喜歡畫畫。","py":"Dìdi xǐhuān dǎ lánqiú, ér mèimei xǐhuān huàhuà.","j":"弟はバスケットボールが好きだが、妹は絵を描くのが好きだ。","e":"My younger brother likes playing basketball, whereas my younger sister likes drawing.","k":"남동생은 농구를 좋아하지만, 여동생은 그림 그리기를 좋아한다."}]},
{"id":"g5-495","cat":"副詞","t":"竟","g":{"j":"意外にも～/なんと～","e":"unexpectedly / to one's surprise","k":"뜻밖에도 / 놀랍게도"},"p":{"j":"主語＋竟＋(是/動詞/形容詞)","e":"Subject + jìng + (verb/adjective phrase)","k":"주어 + 竟 + (동사/형용사)"},"ex":{"j":"予想を超えた結果に対する話者の驚きを表す副詞。「竟然」とほぼ同じだが「竟」は書き言葉・硬い文でよく使い、単独で動詞や形容詞の前に置く。「居然」より客観的な驚きを表すことが多い。","e":"An adverb expressing the speaker's surprise that a result exceeded expectations. Nearly interchangeable with 竟然, but 竟 alone is more common in formal or written style, placed directly before the verb or adjective.","k":"결과가 예상을 뛰어넘어 화자가 놀랐음을 나타내는 부사. '竟然'과 거의 같지만 '竟'는 단독으로 격식체·문어체에서 더 자주 쓰이며 동사나 형용사 앞에 바로 온다."},"eg":[{"z":"短短不到幾年的時間，這間公司的資本額<em>竟</em>高達數億美金。","py":"Duǎnduǎn bú dào jǐ nián de shíjiān, zhè jiān gōngsī de zīběn'é jìng gāodá shù yì měijīn.","j":"わずか数年足らずの間に、この会社の資本額はなんと数億米ドルにも達した。","e":"In just under a few years, this company's capital unexpectedly reached several hundred million US dollars.","k":"불과 몇 년도 안 되는 사이에, 이 회사의 자본금은 놀랍게도 수억 달러에 달했다."},{"z":"他練習了不到一個月，<em>竟</em>考上了台大。","py":"Tā liànxí le bú dào yí gè yuè, jìng kǎoshàng le Táidà.","j":"彼は1か月も練習していないのに、なんと台湾大学に合格した。","e":"He practiced for less than a month, and unexpectedly got into National Taiwan University.","k":"그는 한 달도 채 연습하지 않았는데, 놀랍게도 국립타이완대학교에 합격했다."}]},
{"id":"g5-496","cat":"書きことば","t":"之","g":{"j":"「的」の書き言葉版","e":"literary equivalent of \"的\"","k":"문어체의 '的'"},"p":{"j":"A + 之 + B(書面語，相當於「A 的 B」)","e":"A + 之 + B (formal written form of \"A 的 B\")","k":"A + 之 + B (문어체, 'A 的 B'에 해당)"},"ex":{"j":"之は書きことばで「的」の代わりに使われ、修飾語と名詞をつなぐ。成語・格言・書面語でよく見られ、日常会話ではほとんど使わない。口語で乱用すると硬く不自然に聞こえる。","e":"\"之\" is the formal, written-language counterpart of \"的\", linking a modifier to a noun. It appears in idioms, proverbs, and formal writing but is rare in everyday speech; using it in casual conversation sounds stiff and unnatural.","k":"之는 문어체에서 '的' 대신 쓰여 수식어와 명사를 연결한다. 성어나 격언, 공식적인 글에서 자주 보이며 일상 회화에서는 거의 쓰지 않는다. 구어체에 남발하면 어색하게 들린다."},"eg":[{"z":"父母陪孩子一起走過成長<em>之</em>路。","py":"Fùmǔ péi háizi yìqǐ zǒuguò chéngzhǎng zhī lù.","j":"父母は子どもと一緒に成長の道を歩んできた。","e":"Parents accompany their children through the road of growth.","k":"부모는 아이와 함께 성장의 길을 걸어왔다."},{"z":"台北是美食<em>之</em>都，觀光客都很喜歡。","py":"Táiběi shì měishí zhī dū, guānguāngkè dōu hěn xǐhuān.","j":"台北はグルメの都で、観光客はみんな大好きだ。","e":"Taipei is a city of gourmet food; tourists all love it.","k":"타이베이는 미식의 도시라서 관광객들이 모두 좋아한다."}]},
{"id":"l5-1","cat":"書面","t":"倘若","g":{"j":"もし〜ならば・書面語","e":"if (literary)","k":"만약 ~라면 (문어)"},"p":{"j":"倘若 ＋ 條件，（就/則）＋ 結果","e":"倘若 + condition, (就/則) + result","k":"倘若 + 조건, (就/則) + 결과"},"ex":{"j":"「如果」の書面語。文章・スピーチ・ビジネス文書で使うと格が上がる。後半に「就」や書面語の「則」を伴うことが多い。","e":"Literary \"if\" (= 如果). Common in writing and formal speech; often paired with 就 or 則.","k":"\"如果\"의 문어체. 격식 있는 글이나 연설에서 쓰며 뒤에 \"就/則\"이 온다."},"eg":[{"z":"<em>倘若</em>計畫失敗，我們就得重新來過。","py":"Tǎngruò jìhuà shībài, wǒmen jiù děi chóngxīn láiguò.","j":"もし計画が失敗すれば、やり直さなければなりません。","e":"If the plan fails, we'll have to start over.","k":"만약 계획이 실패하면 다시 시작해야 합니다."},{"z":"<em>倘若</em>沒有大家的支持，就沒有今天的成果。","py":"Tǎngruò méiyǒu dàjiā de zhīchí, jiù méiyǒu jīntiān de chéngguǒ.","j":"皆さんの支えがなければ、今日の成果はありませんでした。","e":"Without everyone's support, we wouldn't have today's results.","k":"여러분의 지지가 없었다면 오늘의 성과도 없었을 것입니다."}]},
{"id":"l5-2","cat":"書面","t":"縱使","g":{"j":"たとえ〜でも・書面語","e":"even if (literary)","k":"설령 ~일지라도 (문어)"},"p":{"j":"縱使 ＋ A，也 ＋ B","e":"縱使 + A, 也 + B","k":"縱使 + A, 也 + B"},"ex":{"j":"「即使」のさらに硬い書面語。「たとえ〜であっても」と仮定を最大限譲歩する。後半は「也」で受ける。","e":"A more formal 即使: \"even if\". The second clause takes 也.","k":"\"即使\"보다 격식 있는 '설령 ~일지라도'. 뒤 절에 \"也\"가 온다."},"eg":[{"z":"<em>縱使</em>困難重重，我們<em>也</em>不會放棄。","py":"Zòngshǐ kùnnán chóngchóng, wǒmen yě bú huì fàngqì.","j":"たとえ困難が山積みでも、私たちは諦めません。","e":"Even if difficulties abound, we will not give up.","k":"설령 어려움이 겹겹이 쌓여도 우리는 포기하지 않을 것입니다."},{"z":"<em>縱使</em>只有一線希望，<em>也</em>值得一試。","py":"Zòngshǐ zhǐyǒu yíxiàn xīwàng, yě zhíde yí shì.","j":"たとえ一縷の望みしかなくても、試す価値はあります。","e":"Even with only a sliver of hope, it's worth a try.","k":"한 가닥 희망뿐이라도 시도할 가치가 있습니다."}]},
{"id":"l5-3","cat":"語氣","t":"姑且","g":{"j":"ひとまず・とりあえず","e":"for now; tentatively","k":"일단, 우선"},"p":{"j":"姑且 ＋ V","e":"姑且 + V","k":"姑且 + V"},"ex":{"j":"「最善ではないが、ひとまず〜しておく」という暫定のニュアンス。「姑且不論（ひとまず置いておくとして）」は議論の定番表現。","e":"姑且 = \"for the time being; tentatively\". 姑且不論 = \"setting aside… for now\".","k":"\"姑且\" = '일단, 우선'. \"姑且不論\"은 '~은 차치하고'라는 상용 표현."},"eg":[{"z":"價格<em>姑且</em>不論，這個設計真的很棒。","py":"Jiàgé gūqiě búlùn, zhège shèjì zhēn de hěn bàng.","j":"価格はひとまず置いておくとして、このデザインは本当に素晴らしい。","e":"Price aside, this design is truly excellent.","k":"가격은 차치하고 이 디자인은 정말 훌륭합니다."},{"z":"沒有更好的辦法，<em>姑且</em>先這樣處理吧。","py":"Méiyǒu gèng hǎo de bànfǎ, gūqiě xiān zhèyàng chǔlǐ ba.","j":"より良い方法がないので、ひとまずこう処理しましょう。","e":"With no better option, let's handle it this way for now.","k":"더 좋은 방법이 없으니 일단 이렇게 처리합시다."}]},
{"id":"l5-4","cat":"語氣","t":"不妨","g":{"j":"〜してみてはどうか","e":"might as well; why not try","k":"~해 보는 게 어떨까"},"p":{"j":"不妨 ＋ V","e":"不妨 + V","k":"不妨 + V"},"ex":{"j":"「〜しても差し支えない、試しに〜してみては」という柔らかい提案。強制感がなく、アドバイスやコラム文でよく使う。","e":"不妨 = \"might as well; why not try\". A gentle, no-pressure suggestion.","k":"\"不妨\" = '~해 봐도 무방하다'. 부드러운 제안 표현."},"eg":[{"z":"有機會的話，<em>不妨</em>去台東走走。","py":"Yǒu jīhuì dehuà, bùfáng qù Táidōng zǒuzou.","j":"機会があれば、台東を訪ねてみてはいかがですか。","e":"If you get the chance, why not visit Taitung?","k":"기회가 되면 타이둥에 한번 가 보는 것도 좋습니다."},{"z":"與其煩惱，<em>不妨</em>直接問他本人。","py":"Yǔqí fánnǎo, bùfáng zhíjiē wèn tā běnrén.","j":"悩むくらいなら、本人に直接聞いてみたらどうですか。","e":"Rather than worrying, you might as well ask him directly.","k":"고민하느니 본인에게 직접 물어보는 게 낫습니다."}]},
{"id":"l5-5","cat":"接續","t":"固然","g":{"j":"もちろん〜ではあるが","e":"admittedly ..., but","k":"물론 ~이지만"},"p":{"j":"A 固然 ～，但/卻 ～","e":"A 固然 ~, 但/卻 ~","k":"A 固然 ~, 但/卻 ~"},"ex":{"j":"「Aは確かにその通りだが、しかし…」と一度認めてから反論・補足する譲歩表現。議論文の定番。「雖然」より論説的。","e":"固然 concedes a point before countering: \"admittedly…, but…\". More argumentative than 雖然.","k":"\"固然\"은 '물론 ~이지만'이라고 인정한 뒤 반박하는 양보 표현."},"eg":[{"z":"薪水<em>固然</em>重要，但工作的成就感更重要。","py":"Xīnshuǐ gùrán zhòngyào, dàn gōngzuò de chéngjiùgǎn gèng zhòngyào.","j":"給料はもちろん大事ですが、仕事のやりがいのほうがもっと大事です。","e":"Salary matters, of course, but a sense of accomplishment matters more.","k":"월급도 물론 중요하지만 일의 성취감이 더 중요합니다."},{"z":"這個方案<em>固然</em>省錢，風險卻也不小。","py":"Zhège fāng'àn gùrán shěngqián, fēngxiǎn què yě bù xiǎo.","j":"この案は確かに安上がりですが、リスクも小さくありません。","e":"This plan does save money, but the risks aren't small either.","k":"이 방안은 돈이 절약되긴 하지만 위험도 작지 않습니다."}]},
{"id":"l5-6","cat":"書面","t":"鑑於","g":{"j":"〜に鑑みて","e":"in view of; given","k":"~을 감안하여"},"p":{"j":"鑑於 ＋ 狀況，＋ 決定/建議","e":"鑑於 + situation, + decision/suggestion","k":"鑑於 + 상황, + 결정/제안"},"ex":{"j":"「〜という状況を踏まえて」と根拠を示してから決定・提案を述べる、公文書・ニュース調の表現。日本語の「〜に鑑み」とほぼ同じ。","e":"鑑於 = \"in view of; given\". Formal register for citing grounds before a decision.","k":"\"鑑於\" = '~을 감안하여'. 공문서·뉴스체 표현."},"eg":[{"z":"<em>鑑於</em>颱風即將登陸，明天停止上班上課。","py":"Jiànyú táifēng jíjiāng dēnglù, míngtiān tíngzhǐ shàngbān shàngkè.","j":"台風の上陸が迫っていることに鑑み、明日は出勤・授業を取りやめます。","e":"In view of the approaching typhoon, work and classes are canceled tomorrow.","k":"태풍 상륙이 임박한 점을 감안해 내일은 출근과 수업을 중단합니다."},{"z":"<em>鑑於</em>使用者的反映，我們調整了介面設計。","py":"Jiànyú shǐyòngzhě de fǎnyìng, wǒmen tiáozhěng le jièmiàn shèjì.","j":"ユーザーの声を踏まえて、インターフェースのデザインを調整しました。","e":"Given user feedback, we adjusted the interface design.","k":"사용자 의견을 감안하여 인터페이스 디자인을 조정했습니다."}]},
{"id":"l5-7","cat":"目的","t":"以免","g":{"j":"〜しないように","e":"so as to avoid; lest","k":"~하지 않도록"},"p":{"j":"…，以免 ＋ 不希望的結果","e":"..., 以免 + undesired result","k":"…, 以免 + 원치 않는 결과"},"ex":{"j":"「〜という悪い結果にならないように」と前の行動の目的（予防）を示す。文の後半に置く。「省得」は口語版。","e":"以免 = \"so as to avoid; lest\". Placed in the second clause to state what the action prevents.","k":"\"以免\" = '~하지 않도록'. 뒤 절에 놓여 예방 목적을 나타낸다."},"eg":[{"z":"出門前先查天氣，<em>以免</em>淋雨。","py":"Chūmén qián xiān chá tiānqì, yǐmiǎn línyǔ.","j":"雨に濡れないように、出かける前に天気を調べましょう。","e":"Check the weather before heading out, so you don't get caught in the rain.","k":"비를 맞지 않도록 나가기 전에 날씨를 확인하세요."},{"z":"重要資料請先備份，<em>以免</em>遺失。","py":"Zhòngyào zīliào qǐng xiān bèifèn, yǐmiǎn yíshī.","j":"紛失しないように、重要なデータは先にバックアップしてください。","e":"Please back up important data to avoid losing it.","k":"중요한 자료는 분실하지 않도록 먼저 백업하세요."}]},
{"id":"l5-8","cat":"書面","t":"以至於","g":{"j":"〜するほどまでに","e":"to the point that","k":"~할 정도로"},"p":{"j":"原因/程度，以至於 ＋ 結果","e":"cause/degree, 以至於 + result","k":"원인/정도, 以至於 + 결과"},"ex":{"j":"程度が高じて、ある結果にまで至ることを表す「その結果〜するほどだ」。悪い結果にも良い結果にも使えるが、書面語。","e":"以至於 = \"to the point that; so much so that\", introducing the resulting extent.","k":"\"以至於\" = '~할 정도에 이르다'. 결과의 정도를 나타내는 문어체."},"eg":[{"z":"他太專心了，<em>以至於</em>沒聽到有人叫他。","py":"Tā tài zhuānxīn le, yǐzhìyú méi tīngdào yǒu rén jiào tā.","j":"彼は集中しすぎて、呼ばれても聞こえないほどでした。","e":"He was so focused that he didn't hear anyone calling him.","k":"그는 너무 집중해서 부르는 소리도 못 들을 정도였습니다."},{"z":"這款遊戲太受歡迎，<em>以至於</em>伺服器一度當機。","py":"Zhè kuǎn yóuxì tài shòu huānyíng, yǐzhìyú sìfúqì yídù dāngjī.","j":"このゲームは人気がありすぎて、サーバーが一時ダウンするほどでした。","e":"The game was so popular that the servers crashed for a while.","k":"이 게임은 너무 인기가 많아 서버가 한때 다운될 정도였습니다."}]},
{"id":"l5-9","cat":"書面","t":"乃至","g":{"j":"〜さらには・書面語","e":"and even; up to (literary)","k":"나아가 ~까지 (문어)"},"p":{"j":"A、B 乃至 C","e":"A, B 乃至 C","k":"A, B 乃至 C"},"ex":{"j":"列挙の最後に範囲をさらに広げる「〜から、ひいては〜まで」。「乃至於」とも。演説やレポートで範囲の大きさを強調する。","e":"乃至 = \"and even; up to\", extending a list to a broader scope. Formal.","k":"\"乃至\" = '나아가 ~까지'. 열거의 범위를 확장하는 문어체."},"eg":[{"z":"這項技術影響了產業、教育<em>乃至</em>整個社會。","py":"Zhè xiàng jìshù yǐngxiǎng le chǎnyè, jiàoyù nǎizhì zhěngge shèhuì.","j":"この技術は産業、教育、ひいては社会全体に影響を与えました。","e":"This technology affected industry, education, and even society as a whole.","k":"이 기술은 산업, 교육, 나아가 사회 전체에 영향을 미쳤습니다."},{"z":"他的作品在台灣<em>乃至</em>全亞洲都很有名。","py":"Tā de zuòpǐn zài Táiwān nǎizhì quán Yàzhōu dōu hěn yǒumíng.","j":"彼の作品は台湾、さらにはアジア全体で有名です。","e":"His works are famous in Taiwan and indeed across Asia.","k":"그의 작품은 대만은 물론 아시아 전역에서 유명합니다."}]},
{"id":"l5-10","cat":"語氣","t":"無非","g":{"j":"〜にすぎない","e":"nothing but; merely","k":"~에 지나지 않는다"},"p":{"j":"A 無非（是）＋ B","e":"A 無非(是) + B","k":"A 無非(是) + B"},"ex":{"j":"「結局のところ〜にすぎない・〜以外の何ものでもない」と物事を限定・断定する。軽く見るニュアンスを帯びることが多い。","e":"無非 = \"nothing but; simply\". Reduces something to its essence, often dismissively.","k":"\"無非\" = '~에 지나지 않는다'. 다소 깎아내리는 뉘앙스가 있다."},"eg":[{"z":"他說這麼多，<em>無非</em>是想要你幫忙。","py":"Tā shuō zhème duō, wúfēi shì xiǎng yào nǐ bāngmáng.","j":"彼があれこれ言うのは、結局あなたに手伝ってほしいだけです。","e":"All that talk of his is simply because he wants your help.","k":"그가 이렇게 말이 많은 것은 결국 당신의 도움을 원해서일 뿐입니다."},{"z":"廣告說得再好，<em>無非</em>是要你掏錢。","py":"Guǎnggào shuō de zài hǎo, wúfēi shì yào nǐ tāoqián.","j":"広告がどんなにうまいことを言っても、結局は金を出させたいだけです。","e":"However good the ad sounds, it's just trying to get your money.","k":"광고가 아무리 그럴듯해도 결국 돈을 쓰게 하려는 것일 뿐입니다."}]},
{"id":"l5-11","cat":"語氣","t":"不外乎","g":{"j":"〜の範囲を出ない","e":"nothing more than; confined to","k":"~을 벗어나지 않는다"},"p":{"j":"A 不外乎 B、C、D","e":"A 不外乎 B, C, D","k":"A 不外乎 B, C, D"},"ex":{"j":"「だいたい〜のどれかだ、〜の範囲を出ない」と選択肢を数え上げて限定する。「無非」より列挙向き。","e":"不外乎 = \"boils down to nothing more than…\", enumerating the limited possibilities.","k":"\"不外乎\" = '~의 범위를 벗어나지 않는다'. 한정된 선택지를 열거할 때 쓴다."},"eg":[{"z":"台灣人聊天的話題<em>不外乎</em>美食、天氣和房價。","py":"Táiwānrén liáotiān de huàtí búwàihū měishí, tiānqì hàn fángjià.","j":"台湾人の雑談のネタは、だいたいグルメ・天気・不動産価格のどれかです。","e":"Taiwanese small talk boils down to food, weather, and housing prices.","k":"대만 사람들의 잡담 주제는 맛집, 날씨, 집값을 벗어나지 않습니다."},{"z":"失敗的原因<em>不外乎</em>準備不足或運氣不好。","py":"Shībài de yuányīn búwàihū zhǔnbèi bùzú huò yùnqì bù hǎo.","j":"失敗の原因は、準備不足か運の悪さのどちらかにすぎません。","e":"The causes of failure are nothing more than poor preparation or bad luck.","k":"실패의 원인은 준비 부족 아니면 운이 나빴던 것뿐입니다."}]},
{"id":"l5-13","cat":"取捨","t":"與其…不如…","g":{"j":"〜するより…のほうがいい","e":"rather than ..., better to ...","k":"~하느니 ~하는 편이 낫다"},"p":{"j":"與其 A，不如 B","e":"與其 A, 不如 B","k":"與其 A, 不如 B"},"ex":{"j":"二つを比べて「AするよりBのほうがいい」と後者を勧める。「寧可」が意志なのに対し、こちらは比較・提案のニュアンス。","e":"與其 A 不如 B = \"rather than A, better to B\", recommending the latter.","k":"與其 A 不如 B = 'A하느니 B하는 편이 낫다'."},"eg":[{"z":"<em>與其</em>在家滑手機，<em>不如</em>出去運動。","py":"Yǔqí zài jiā huá shǒujī, bùrú chūqù yùndòng.","j":"家でスマホをいじっているより、外へ出て運動したほうがいいですよ。","e":"Rather than scrolling your phone at home, better to go out and exercise.","k":"집에서 휴대폰만 보느니 나가서 운동하는 게 낫습니다."},{"z":"<em>與其</em>抱怨環境，<em>不如</em>先改變自己。","py":"Yǔqí bàoyuàn huánjìng, bùrú xiān gǎibiàn zìjǐ.","j":"環境に文句を言うより、まず自分を変えたほうがいい。","e":"Rather than complaining about circumstances, change yourself first.","k":"환경을 탓하느니 먼저 자신을 바꾸는 게 낫습니다."}]},
{"id":"l5-15","cat":"書面","t":"勢必","g":{"j":"必然的に〜になる","e":"inevitably will","k":"필연적으로 ~하게 된다"},"p":{"j":"勢必 ＋ V","e":"勢必 + V","k":"勢必 + V"},"ex":{"j":"「成り行きから見て必ず〜になる」という必然の予測。ニュース・分析文でよく使う。「一定」より客観的・論理的な響き。","e":"勢必 = \"inevitably will\", an objective prediction from the momentum of events.","k":"\"勢必\" = '필연적으로 ~하게 된다'. 뉴스·분석문에서 자주 쓴다."},"eg":[{"z":"原物料上漲，物價<em>勢必</em>跟著上升。","py":"Yuánwùliào shàngzhǎng, wùjià shìbì gēnzhe shàngshēng.","j":"原材料が値上がりすれば、物価も必然的に上昇します。","e":"With raw materials rising, prices are bound to follow.","k":"원자재가 오르면 물가도 필연적으로 따라 오릅니다."},{"z":"少子化<em>勢必</em>影響未來的勞動力。","py":"Shǎozǐhuà shìbì yǐngxiǎng wèilái de láodònglì.","j":"少子化は将来の労働力に必ず影響を及ぼします。","e":"The falling birthrate will inevitably affect the future workforce.","k":"저출산은 미래의 노동력에 필연적으로 영향을 미칩니다."}]},
{"id":"l5-16","cat":"語氣","t":"免不了","g":{"j":"避けられない・つい〜してしまう","e":"unavoidable; bound to happen","k":"피할 수 없다, ~하기 마련이다"},"p":{"j":"免不了 ＋ V/名詞","e":"免不了 + V/noun","k":"免不了 + V/명사"},"ex":{"j":"「どうしても避けられない、〜は付き物だ」という容認。深刻さは低めで、「人間だから仕方ない」という寛容なニュアンスが出る。","e":"免不了 = \"can't avoid; bound to happen\", with a forgiving, that's-life tone.","k":"\"免不了\" = '피할 수 없다, ~하기 마련이다'. 관용적인 뉘앙스."},"eg":[{"z":"剛到新環境，<em>免不了</em>會有點不習慣。","py":"Gāng dào xīn huánjìng, miǎnbùliǎo huì yǒudiǎn bù xíguàn.","j":"新しい環境に来たばかりだと、多少慣れないのは仕方ありません。","e":"In a new environment, some discomfort is inevitable at first.","k":"새 환경에 막 왔으니 어색한 것은 어쩔 수 없습니다."},{"z":"一家人住在一起，<em>免不了</em>有些小摩擦。","py":"Yìjiārén zhù zài yìqǐ, miǎnbùliǎo yǒuxiē xiǎo mócā.","j":"家族が一緒に住んでいれば、多少の小さな衝突は付き物です。","e":"Living together as a family, small frictions are bound to happen.","k":"가족이 함께 살다 보면 작은 마찰은 있기 마련입니다."}]}
];
